/**
 * Configuracion central leida de variables de entorno.
 *
 * IMPORTANTE: este modulo es SOLO de servidor. Nunca importar desde un
 * componente cliente, porque expone claves de API y secretos.
 */

function texto(nombre: string, porDefecto: string): string {
  const valor = process.env[nombre];
  return valor === undefined || valor === '' ? porDefecto : valor;
}

function opcional(nombre: string): string | undefined {
  const valor = process.env[nombre];
  return valor === undefined || valor.trim() === '' ? undefined : valor;
}

function entero(nombre: string, porDefecto: number): number {
  const valor = process.env[nombre];
  if (valor === undefined || valor.trim() === '') return porDefecto;
  const n = Number.parseInt(valor, 10);
  return Number.isFinite(n) ? n : porDefecto;
}

function booleano(nombre: string, porDefecto: boolean): boolean {
  const valor = process.env[nombre];
  if (valor === undefined || valor.trim() === '') return porDefecto;
  return ['1', 'true', 'si', 'sí', 'yes', 'on'].includes(valor.trim().toLowerCase());
}

export type ProveedorLlm = 'anthropic' | 'openai' | 'mock';

function proveedorLlm(): ProveedorLlm {
  const valor = texto('LLM_PROVIDER', 'mock').toLowerCase();
  if (valor === 'anthropic' || valor === 'openai' || valor === 'mock') return valor;
  return 'mock';
}

export const esProduccion = process.env.NODE_ENV === 'production';

export const env = {
  appUrl: texto('APP_URL', 'http://localhost:3000'),
  appSecret: texto('APP_SECRET', 'secreto-de-desarrollo-inseguro'),
  esProduccion,

  bcryptRounds: entero('BCRYPT_ROUNDS', 10),
  sessionTtlHoras: entero('SESSION_TTL_HOURS', 12),

  maxUploadMb: entero('MAX_UPLOAD_MB', 15),
  uploadDir: texto('UPLOAD_DIR', './storage/uploads'),

  llm: {
    proveedor: proveedorLlm(),
    anthropicApiKey: opcional('ANTHROPIC_API_KEY'),
    anthropicModelo: texto('ANTHROPIC_MODEL', 'claude-3-5-sonnet-latest'),
    openaiApiKey: opcional('OPENAI_API_KEY'),
    openaiModelo: texto('OPENAI_MODEL', 'gpt-4o-mini'),
    openaiBaseUrl: texto('OPENAI_BASE_URL', 'https://api.openai.com/v1'),
    maxTokens: entero('LLM_MAX_OUTPUT_TOKENS', 8000),
    timeoutMs: entero('LLM_TIMEOUT_MS', 120000),
  },

  pdf: {
    ocrActivo: booleano('OCR_ENABLED', false),
    ocrIdioma: texto('OCR_LANGUAGE', 'spa+eng'),
    ocrMaxPaginas: entero('OCR_MAX_PAGES', 10),
    chunkSize: entero('CHUNK_SIZE_CHARS', 8000),
    chunkSolape: entero('CHUNK_OVERLAP_CHARS', 800),
  },

  limites: {
    loginMax: entero('LOGIN_RATE_LIMIT_MAX', 10),
    loginVentanaSeg: entero('LOGIN_RATE_LIMIT_WINDOW_SEC', 300),
    respuestaMax: entero('ANSWER_RATE_LIMIT_MAX', 120),
    respuestaVentanaSeg: entero('ANSWER_RATE_LIMIT_WINDOW_SEC', 60),
    exportMaxFilas: entero('REPORTS_EXPORT_MAX_ROWS', 5000),
  },
} as const;

/** Indica si el proveedor LLM configurado tiene credenciales utilizables. */
export function llmConfigurado(): boolean {
  if (env.llm.proveedor === 'mock') return true;
  if (env.llm.proveedor === 'anthropic') return Boolean(env.llm.anthropicApiKey);
  if (env.llm.proveedor === 'openai') return Boolean(env.llm.openaiApiKey);
  return false;
}

import { PrismaClient } from '@prisma/client';

/**
 * Cliente Prisma unico (singleton) para evitar abrir demasiadas conexiones
 * durante el hot-reload de Next.js en desarrollo.
 */
const globalForPrisma = globalThis as unknown as { prisma?: PrismaClient };

export const prisma =
  globalForPrisma.prisma ??
  new PrismaClient({
    log: process.env.NODE_ENV === 'development' ? ['warn', 'error'] : ['error'],
  });

if (process.env.NODE_ENV !== 'production') {
  globalForPrisma.prisma = prisma;
}

/**
 * Constantes de dominio y etiquetas en espanol.
 *
 * SQLite no soporta enums nativos en Prisma, asi que todos los "enum" viven
 * aqui y se validan con Zod en los bordes del servidor.
 */
import { z } from 'zod';

// --- Usuarios --------------------------------------------------------------

export const ROLES = ['ADMIN', 'TEACHER', 'STUDENT'] as const;
export type Rol = (typeof ROLES)[number];
export const rolSchema = z.enum(ROLES);

export const ETIQUETA_ROL: Record<Rol, string> = {
  ADMIN: 'Administrador',
  TEACHER: 'Docente',
  STUDENT: 'Estudiante',
};

// --- Documentos ------------------------------------------------------------

export const ESTADOS_DOCUMENTO = ['PENDING', 'EXTRACTED', 'EMPTY', 'FAILED', 'OCR_USED'] as const;
export type EstadoDocumento = (typeof ESTADOS_DOCUMENTO)[number];

export const ETIQUETA_ESTADO_DOCUMENTO: Record<EstadoDocumento, string> = {
  PENDING: 'Pendiente de extraccion',
  EXTRACTED: 'Texto extraido',
  EMPTY: 'Sin texto utilizable',
  FAILED: 'Error al procesar',
  OCR_USED: 'Extraido con OCR',
};

// --- Preguntas -------------------------------------------------------------

export const TIPOS_PREGUNTA = ['MCQ_SINGLE', 'MCQ_MULTI', 'TRUE_FALSE', 'SHORT_ANSWER'] as const;
export type TipoPregunta = (typeof TIPOS_PREGUNTA)[number];
export const tipoPreguntaSchema = z.enum(TIPOS_PREGUNTA);

export const ETIQUETA_TIPO_PREGUNTA: Record<TipoPregunta, string> = {
  MCQ_SINGLE: 'Opcion multiple (una respuesta)',
  MCQ_MULTI: 'Seleccion multiple (varias respuestas)',
  TRUE_FALSE: 'Verdadero / Falso',
  SHORT_ANSWER: 'Respuesta corta',
};

export const DIFICULTADES = ['EASY', 'MEDIUM', 'HARD'] as const;
export type Dificultad = (typeof DIFICULTADES)[number];
export const dificultadSchema = z.enum(DIFICULTADES);

export const ETIQUETA_DIFICULTAD: Record<Dificultad, string> = {
  EASY: 'Facil',
  MEDIUM: 'Media',
  HARD: 'Dificil',
};

export const ESTADOS_PREGUNTA = ['DRAFT', 'PENDING_REVIEW', 'APPROVED'] as const;
export type EstadoPregunta = (typeof ESTADOS_PREGUNTA)[number];

export const ORIGENES_PREGUNTA = ['MANUAL', 'GENERATED', 'IMPORTED'] as const;
export type OrigenPregunta = (typeof ORIGENES_PREGUNTA)[number];

export const ETIQUETA_ORIGEN_PREGUNTA: Record<OrigenPregunta, string> = {
  MANUAL: 'Manual',
  GENERATED: 'Generada por IA',
  IMPORTED: 'Importada de PDF',
};

// --- Quices ----------------------------------------------------------------

export const ESTADOS_QUIZ = ['DRAFT', 'PUBLISHED', 'CLOSED'] as const;
export type EstadoQuiz = (typeof ESTADOS_QUIZ)[number];

export const ETIQUETA_ESTADO_QUIZ: Record<EstadoQuiz, string> = {
  DRAFT: 'Borrador',
  PUBLISHED: 'Publicado',
  CLOSED: 'Cerrado',
};

export const MODOS_NAVEGACION = ['FORWARD_ONLY', 'FREE'] as const;
export type ModoNavegacion = (typeof MODOS_NAVEGACION)[number];
export const modoNavegacionSchema = z.enum(MODOS_NAVEGACION);

export const ETIQUETA_MODO_NAVEGACION: Record<ModoNavegacion, string> = {
  FORWARD_ONLY: 'Solo hacia adelante (sin retroceder)',
  FREE: 'Permitir retroceder y cambiar respuestas',
};

export const MODOS_RESULTADO = ['NONE', 'SCORE', 'SCORE_AND_ANSWERS'] as const;
export type ModoResultado = (typeof MODOS_RESULTADO)[number];
export const modoResultadoSchema = z.enum(MODOS_RESULTADO);

export const ETIQUETA_MODO_RESULTADO: Record<ModoResultado, string> = {
  NONE: 'No mostrar nada al terminar',
  SCORE: 'Mostrar solo la nota',
  SCORE_AND_ANSWERS: 'Mostrar nota y respuestas correctas',
};

export const ACCIONES_INFRACCION = ['VOID', 'AUTO_SUBMIT', 'REGISTER_ONLY'] as const;
export type AccionInfraccion = (typeof ACCIONES_INFRACCION)[number];
export const accionInfraccionSchema = z.enum(ACCIONES_INFRACCION);

export const ETIQUETA_ACCION_INFRACCION: Record<AccionInfraccion, string> = {
  VOID: 'Anular el intento',
  AUTO_SUBMIT: 'Enviar automaticamente el intento',
  REGISTER_ONLY: 'Solo registrar y notificar al docente',
};

// --- Intentos --------------------------------------------------------------

export const ESTADOS_INTENTO = ['IN_PROGRESS', 'SUBMITTED', 'VOIDED'] as const;
export type EstadoIntento = (typeof ESTADOS_INTENTO)[number];

export const ETIQUETA_ESTADO_INTENTO: Record<EstadoIntento, string> = {
  IN_PROGRESS: 'En progreso',
  SUBMITTED: 'Enviado',
  VOIDED: 'Anulado',
};

export const MOTIVOS_ENVIO = ['MANUAL', 'TIME_UP', 'INFRACTIONS', 'FORCED'] as const;
export type MotivoEnvio = (typeof MOTIVOS_ENVIO)[number];

export const ETIQUETA_MOTIVO_ENVIO: Record<MotivoEnvio, string> = {
  MANUAL: 'Envio manual',
  TIME_UP: 'Tiempo agotado',
  INFRACTIONS: 'Infracciones excedidas',
  FORCED: 'Forzado por el docente o el sistema',
};

// --- Proctoring ------------------------------------------------------------

export const TIPOS_EVENTO_PROCTOR = [
  'FULLSCREEN_EXIT',
  'FULLSCREEN_ENTER',
  'TAB_HIDDEN',
  'WINDOW_BLUR',
  'CONTEXT_MENU',
  'COPY',
  'PASTE',
  'CUT',
  'PRINT',
  'SHORTCUT',
  'SELECTION',
  'NO_FULLSCREEN_SUPPORT',
  'RESUMED',
] as const;
export type TipoEventoProctor = (typeof TIPOS_EVENTO_PROCTOR)[number];
export const tipoEventoProctorSchema = z.enum(TIPOS_EVENTO_PROCTOR);

export const ETIQUETA_EVENTO_PROCTOR: Record<TipoEventoProctor, string> = {
  FULLSCREEN_EXIT: 'Salida de pantalla completa',
  FULLSCREEN_ENTER: 'Entrada a pantalla completa',
  TAB_HIDDEN: 'Cambio de pestana / app oculta',
  WINDOW_BLUR: 'Pérdida de foco de la ventana',
  CONTEXT_MENU: 'Intento de abrir menu contextual',
  COPY: 'Copia',
  PASTE: 'Pegado',
  CUT: 'Corte',
  PRINT: 'Intento de imprimir',
  SHORTCUT: 'Atajo de teclado restringido',
  SELECTION: 'Intento de seleccionar texto',
  NO_FULLSCREEN_SUPPORT: 'Navegador sin soporte de pantalla completa',
  RESUMED: 'Reanudacion del intento',
};

/** Tipos de evento que cuentan como infraccion (suman al contador). */
export const EVENTOS_INFRACCION: TipoEventoProctor[] = [
  'FULLSCREEN_EXIT',
  'TAB_HIDDEN',
  'WINDOW_BLUR',
  'CONTEXT_MENU',
  'COPY',
  'CUT',
  'PRINT',
  'SELECTION',
  'NO_FULLSCREEN_SUPPORT',
];

// --- Utilidades ------------------------------------------------------------

export function etiqueta<T extends string>(mapa: Record<T, string>, clave: string): string {
  return (mapa as Record<string, string>)[clave] ?? clave;
}

/** Convierte un texto en slug seguro para nombres de archivo. */
export function slug(texto: string): string {
  return texto
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .toLowerCase()
    .slice(0, 60);
}

import { NextResponse, type NextRequest } from 'next/server';
import { ZodError, type ZodSchema } from 'zod';

/** Error de API con codigo HTTP y codigo de negocio. */
export class ErrorApi extends Error {
  readonly estado: number;
  readonly codigo: string;
  readonly detalles?: unknown;

  constructor(estado: number, codigo: string, mensaje: string, detalles?: unknown) {
    super(mensaje);
    this.name = 'ErrorApi';
    this.estado = estado;
    this.codigo = codigo;
    this.detalles = detalles;
  }
}

export const noAutenticado = () =>
  new ErrorApi(401, 'NO_AUTENTICADO', 'Debes iniciar sesion para continuar.');
export const sinPermiso = () =>
  new ErrorApi(403, 'SIN_PERMISO', 'No tienes permisos para realizar esta accion.');
export const noEncontrado = (que = 'Recurso') =>
  new ErrorApi(404, 'NO_ENCONTRADO', `${que} no encontrado.`);
export const solicitudInvalida = (mensaje: string, detalles?: unknown) =>
  new ErrorApi(400, 'SOLICITUD_INVALIDA', mensaje, detalles);
export const conflicto = (mensaje: string) => new ErrorApi(409, 'CONFLICTO', mensaje);
export const demasiadasPeticiones = (mensaje: string, reintentarEn: number) =>
  new ErrorApi(429, 'DEMASIADAS_PETICIONES', mensaje, { reintentarEn });

export function respuestaOk<T>(datos: T, estado = 200): NextResponse {
  return NextResponse.json({ datos }, { status: estado });
}

function cuerpoError(estado: number, codigo: string, mensaje: string, campos?: unknown) {
  return NextResponse.json({ error: { codigo, mensaje, campos } }, { status: estado });
}

/** Convierte cualquier excepcion en una respuesta JSON homogenea. */
export function respuestaError(error: unknown): NextResponse {
  if (error instanceof ErrorApi) {
    return cuerpoError(error.estado, error.codigo, error.message, error.detalles);
  }
  if (error instanceof ZodError) {
    const campos: Record<string, string> = {};
    for (const problema of error.errors) {
      campos[problema.path.join('.') || '_'] = problema.message;
    }
    return cuerpoError(400, 'DATOS_INVALIDOS', 'Los datos enviados no son validos.', campos);
  }
  const mensaje = error instanceof Error ? error.message : 'Error desconocido';
  if (process.env.NODE_ENV !== 'production') {
    console.error('[API]', error);
  }
  return cuerpoError(500, 'ERROR_INTERNO', `Error interno del servidor: ${mensaje}`);
}

type ContextoRuta<P> = { params: Promise<P> };

/**
 * Envuelve un handler de route de Next para capturar errores y
 * validar automaticamente.
 */
export function ruta<P = Record<string, never>>(
  fn: (req: NextRequest, ctx: ContextoRuta<P>) => Promise<NextResponse> | NextResponse,
) {
  return async (req: NextRequest, ctx: ContextoRuta<P>): Promise<NextResponse> => {
    try {
      return await fn(req, ctx);
    } catch (error) {
      return respuestaError(error);
    }
  };
}

/** Lee y valida el cuerpo JSON de una peticion. */
export async function leerCuerpo<T>(req: NextRequest, esquema: ZodSchema<T>): Promise<T> {
  let json: unknown;
  try {
    json = await req.json();
  } catch {
    throw solicitudInvalida('El cuerpo de la peticion no es JSON valido.');
  }
  const resultado = esquema.safeParse(json);
  if (!resultado.success) throw resultado.error;
  return resultado.data;
}

/** Valida datos que pueden venir de query string, JSON o formulario. */
export function validar<T>(esquema: ZodSchema<T>, datos: unknown): T {
  const resultado = esquema.safeParse(datos);
  if (!resultado.success) throw resultado.error;
  return resultado.data;
}

/** Extrae datos de autenticacion del cliente (IP y user-agent). */
export function infoCliente(req: NextRequest): { ip: string | null; userAgent: string | null } {
  const reenviada = req.headers.get('x-forwarded-for');
  const ip = reenviada?.split(',')[0]?.trim() || req.headers.get('x-real-ip') || null;
  return { ip, userAgent: req.headers.get('user-agent') };
}

