// --- Variantes para componentes de servidor (paginas) ----------------------

/** Devuelve el usuario o `null` (no redirige). */
export async function usuarioActual(): Promise<UsuarioSesion | null> {
  const sesion = await sesionActual();
  return sesion?.usuario ?? null;
}

/** Exige sesion; si no hay, redirige a /login. */
export async function requiereUsuario(): Promise<SesionConUsuario> {
  const sesion = await sesionActual();
  if (!sesion) redirect('/login');
  return sesion;
}

/** Exige sesion y rol; si el rol no coincide, redirige al panel. */
export async function requiereRol(...roles: Rol[]): Promise<SesionConUsuario> {
  const sesion = await requiereUsuario();
  if (!roles.includes(sesion.usuario.role as Rol)) redirect('/panel');
  return sesion;
}

// --- Variantes para route handlers (API) ----------------------------------

export async function requiereUsuarioApi(): Promise<SesionConUsuario> {
  const sesion = await sesionActual();
  if (!sesion) throw noAutenticado();
  return sesion;
}

export async function requiereRolApi(...roles: Rol[]): Promise<SesionConUsuario> {
  const sesion = await requiereUsuarioApi();
  if (!roles.includes(sesion.usuario.role as Rol)) throw sinPermiso();
  return sesion;
}

/**
 * Verifica el token CSRF (double submit) comparando la cabecera
 * `x-csrf-token` con el token guardado en la sesion.
 */
export function verificarCsrf(req: NextRequest, sesion: SesionConUsuario): void {
  const enviado = req.headers.get('x-csrf-token');
  if (!enviado || enviado !== sesion.csrfToken) {
    throw new ErrorApi(403, 'CSRF_INVALIDO', 'Token CSRF ausente o invalido. Recarga la pagina.');
  }
}

/**
 * Rate limiting en memoria (ventana deslizante por cubos).
 *
 * Limitacion honesta: es un limiter por proceso. Con varias instancias de
 * Next.js o serverless cada instancia tiene su propio contador. Para
 * produccion en varias instancias se debe usar Redis/Upstash. Se documenta
 * en el README.
 */

type Cubo = { conteo: number; expira: number };

const cubos = new Map<string, Cubo>();
let ultimaLimpieza = Date.now();

function limpiar(): void {
  const ahora = Date.now();
  if (ahora - ultimaLimpieza < 60_000) return;
  ultimaLimpieza = ahora;
  for (const [clave, cubo] of cubos) {
    if (cubo.expira <= ahora) cubos.delete(clave);
  }
}

export type ResultadoLimite = {
  permitido: boolean;
  restantes: number;
  reintentarEn: number;
};

export function limitar(clave: string, max: number, ventanaSeg: number): ResultadoLimite {
  limpiar();
  const ahora = Date.now();
  const actual = cubos.get(clave);

  if (!actual || actual.expira <= ahora) {
    cubos.set(clave, { conteo: 1, expira: ahora + ventanaSeg * 1000 });
    return { permitido: true, restantes: Math.max(max - 1, 0), reintentarEn: 0 };
  }

  actual.conteo += 1;
  if (actual.conteo > max) {
    return {
      permitido: false,
      restantes: 0,
      reintentarEn: Math.ceil((actual.expira - ahora) / 1000),
    };
  }
  return { permitido: true, restantes: max - actual.conteo, reintentarEn: 0 };
}

/** Reinicia un contador (por ejemplo tras un login correcto). */
export function reiniciarLimite(clave: string): void {
  cubos.delete(clave);
}

/** Solo para pruebas. */
export function _reiniciarTodo(): void {
  cubos.clear();
}

