export const CLAVES_AJUSTES = DEFINICIONES_AJUSTES.map((d) => d.clave);

function validador(def: DefinicionAjuste): z.ZodType<string> {
  if (def.tipo === 'booleano') {
    return z.enum(['true', 'false'], {
      errorMap: () => ({ message: 'Debe ser "true" o "false".' }),
    });
  }
  if (def.tipo === 'texto') {
    return z.string().trim().min(1, 'No puede estar vacio.').max(160);
  }
  const num = z
    .string()
    .trim()
    .refine((v) => v !== '' && Number.isFinite(Number(v)), 'Debe ser un numero.');
  return num
    .refine((v) => def.min === undefined || Number(v) >= def.min, `Minimo ${def.min}.`)
    .refine((v) => def.max === undefined || Number(v) <= def.max, `Maximo ${def.max}.`)
    .refine(
      (v) => def.tipo !== 'entero' || Number.isInteger(Number(v)),
      'Debe ser un numero entero.',
    );
}

export const esquemaAjustes = z
  .object(
    Object.fromEntries(DEFINICIONES_AJUSTES.map((d) => [d.clave, validador(d)])) as Record<
      string,
      z.ZodType<string>
    >,
  )
  .partial();

export type Ajustes = Record<string, string>;

/** Ajustes por defecto (sin consultar la base). */
export function ajustesPorDefecto(): Ajustes {
  return Object.fromEntries(DEFINICIONES_AJUSTES.map((d) => [d.clave, d.porDefecto]));
}

/** Lee todos los ajustes, completando con los valores por defecto. */
export async function obtenerAjustes(): Promise<Ajustes> {
  const filas = await prisma.setting.findMany();
  const resultado = ajustesPorDefecto();
  for (const fila of filas) {
    if (fila.key in resultado) resultado[fila.key] = fila.value;
  }
  return resultado;
}

/** Lee un unico ajuste. */
export async function obtenerAjuste(clave: string): Promise<string> {
  const fila = await prisma.setting.findUnique({ where: { key: clave } });
  if (fila) return fila.value;
  return DEFINICIONES_AJUSTES.find((d) => d.clave === clave)?.porDefecto ?? '';
}

export async function obtenerAjusteNumero(clave: string, porDefecto = 0): Promise<number> {
  const valor = await obtenerAjuste(clave);
  const n = Number(valor);
  return Number.isFinite(n) ? n : porDefecto;
}

export async function obtenerAjusteBooleano(clave: string, porDefecto = false): Promise<boolean> {
  const valor = await obtenerAjuste(clave);
  if (valor === '') return porDefecto;
  return valor === 'true';
}

/** Guarda (upsert) un conjunto de ajustes ya validados. */
export async function guardarAjustes(parcial: Ajustes): Promise<void> {
  const entradas = Object.entries(parcial).filter(([clave]) => CLAVES_AJUSTES.includes(clave));
  for (const [clave, valor] of entradas) {
    await prisma.setting.upsert({
      where: { key: clave },
      create: { key: clave, value: valor },
      update: { value: valor },
    });
  }
}

/**
 * Cliente HTTP para el navegador: adjunta automaticamente el token CSRF
 * leido de la cookie `qc_csrf` y normaliza los errores en espanol.
 */

export class ErrorPeticion extends Error {
  readonly codigo: string;
  readonly estado: number;
  readonly campos?: Record<string, string>;

  constructor(estado: number, codigo: string, mensaje: string, campos?: Record<string, string>) {
    super(mensaje);
    this.name = 'ErrorPeticion';
    this.estado = estado;
    this.codigo = codigo;
    this.campos = campos;
  }
}

function leerCookie(nombre: string): string | null {
  if (typeof document === 'undefined') return null;
  const partes = document.cookie.split(';').map((p) => p.trim());
  for (const parte of partes) {
    const [clave, ...resto] = parte.split('=');
    if (clave === nombre) return decodeURIComponent(resto.join('='));
  }
  return null;
}

type Opciones = Omit<RequestInit, 'body'> & { cuerpo?: unknown; cuerpoCrudo?: BodyInit };

export async function peticion<T>(url: string, opciones: Opciones = {}): Promise<T> {
  const { cuerpo, cuerpoCrudo, headers, ...resto } = opciones;
  const metodo = (opciones.method ?? 'GET').toUpperCase();
  const cabeceras = new Headers(headers);

  if (cuerpo !== undefined && !cabeceras.has('content-type')) {
    cabeceras.set('content-type', 'application/json');
  }
  if (metodo !== 'GET' && metodo !== 'HEAD') {
    const csrf = leerCookie('qc_csrf');
    if (csrf) cabeceras.set('x-csrf-token', csrf);
  }

  const respuesta = await fetch(url, {
    ...resto,
    method: metodo,
    headers: cabeceras,
    credentials: 'same-origin',
    body: cuerpoCrudo ?? (cuerpo !== undefined ? JSON.stringify(cuerpo) : undefined),
  });

  const tipo = respuesta.headers.get('content-type') ?? '';
  const esJson = tipo.includes('application/json');
  const payload = esJson ? await respuesta.json() : await respuesta.text();

  if (!respuesta.ok) {
    if (esJson && payload && typeof payload === 'object' && 'error' in payload) {
      const error = (payload as { error: { codigo: string; mensaje: string; campos?: Record<string, string> } }).error;
      throw new ErrorPeticion(respuesta.status, error.codigo, error.mensaje, error.campos);
    }
    throw new ErrorPeticion(respuesta.status, 'ERROR_DESCONOCIDO', 'Ocurrio un error inesperado.');
  }

  if (esJson && payload && typeof payload === 'object' && 'datos' in payload) {
    return (payload as { datos: T }).datos;
  }
  return payload as T;
}

export const api = {
  get: <T>(url: string) => peticion<T>(url, { method: 'GET' }),
  post: <T>(url: string, cuerpo?: unknown) => peticion<T>(url, { method: 'POST', cuerpo }),
  patch: <T>(url: string, cuerpo?: unknown) => peticion<T>(url, { method: 'PATCH', cuerpo }),
  put: <T>(url: string, cuerpo?: unknown) => peticion<T>(url, { method: 'PUT', cuerpo }),
  del: <T>(url: string, cuerpo?: unknown) => peticion<T>(url, { method: 'DELETE', cuerpo }),
};

import { NextResponse, type NextRequest } from 'next/server';

const COOKIE_SESION = 'qc_session';

/**
 * Middleware de seguridad.
 *  1. Aplica cabeceras de seguridad (CSP, anti-framing, nosniff, etc.).
 *  2. Hace un control rapido de acceso: si no existe cookie de sesion en una
 *     ruta privada, redirige a /login. La autorizacion real (rol y propiedad
 *     del recurso) SIEMPRE se valida en el servidor, nunca aqui.
 */

const RUTAS_PUBLICAS = ['/login'];

function cabecerasSeguridad(respuesta: NextResponse, esDesarrollo: boolean): NextResponse {
  const csp = [
    "default-src 'self'",
    // Next.js inyecta scripts inline en el HTML; sin nonce necesitamos
    // 'unsafe-inline'. Ver README > Limitaciones y mejoras.
    `script-src 'self' 'unsafe-inline'${esDesarrollo ? " 'unsafe-eval'" : ''}`,
    "style-src 'self' 'unsafe-inline'",
    "img-src 'self' data: blob:",
    "font-src 'self' data:",
    "connect-src 'self'",
    "media-src 'self'",
    "worker-src 'self' blob:",
    "object-src 'none'",
    "base-uri 'self'",
    "form-action 'self'",
    "frame-ancestors 'none'",
    esDesarrollo ? '' : 'upgrade-insecure-requests',
  ]
    .filter(Boolean)
    .join('; ');

  respuesta.headers.set('Content-Security-Policy', csp);
  respuesta.headers.set('X-Frame-Options', 'DENY');
  respuesta.headers.set('X-Content-Type-Options', 'nosniff');
  respuesta.headers.set('Referrer-Policy', 'strict-origin-when-cross-origin');
  respuesta.headers.set(
    'Permissions-Policy',
    'camera=(), microphone=(), geolocation=(), payment=(), usb=(), fullscreen=(self)',
  );
  respuesta.headers.set('Cross-Origin-Opener-Policy', 'same-origin');
  respuesta.headers.set('Cross-Origin-Resource-Policy', 'same-origin');
  respuesta.headers.set('X-Permitted-Cross-Domain-Policies', 'none');
  if (!esDesarrollo) {
    respuesta.headers.set('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  }
  return respuesta;
}

export function middleware(req: NextRequest) {
  const { pathname, search } = req.nextUrl;
  const esDesarrollo = process.env.NODE_ENV !== 'production';
  const tieneSesion = Boolean(req.cookies.get(COOKIE_SESION)?.value);

  // Las rutas de API responden JSON; no se redirigen, cada handler autentica.
  if (pathname.startsWith('/api')) {
    return cabecerasSeguridad(NextResponse.next(), esDesarrollo);
  }

  const esPublica = RUTAS_PUBLICAS.some((ruta) => pathname === ruta || pathname.startsWith(`${ruta}/`));

  if (tieneSesion && pathname === '/login') {
    return cabecerasSeguridad(NextResponse.redirect(new URL('/panel', req.url)), esDesarrollo);
  }

  if (!esPublica && !tieneSesion) {
    const destino = new URL('/login', req.url);
    if (pathname !== '/') destino.searchParams.set('siguiente', `${pathname}${search}`);
    return cabecerasSeguridad(NextResponse.redirect(destino), esDesarrollo);
  }

  return cabecerasSeguridad(NextResponse.next(), esDesarrollo);
}

