import { prisma } from '@/lib/db';
import { ruta, leerCuerpo, respuestaOk, infoCliente, conflicto } from '@/lib/http';
import { requiereRolApi, verificarCsrf } from '@/lib/auth/guard';
import { auditar, ACCIONES } from '@/lib/audit';
import { esquemaCrearGrupo } from '@/lib/esquemas/grupos';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

/** GET /api/admin/grupos?anio=&buscar= */
export const GET = ruta(async (req) => {
  await requiereRolApi('ADMIN', 'TEACHER');

  const url = new URL(req.url);
  const anioParam = url.searchParams.get('anio');
  const buscar = url.searchParams.get('buscar')?.trim();

  const grupos = await prisma.group.findMany({
    where: {
      ...(anioParam ? { year: Number(anioParam) } : {}),
      ...(buscar ? { name: { contains: buscar } } : {}),
    },
    orderBy: [{ year: 'desc' }, { name: 'asc' }],
    include: {
      _count: { select: { memberships: true, assignments: true } },
    },
  });

  return respuestaOk({
    grupos: grupos.map((g) => ({
      id: g.id,
      nombre: g.name,
      grado: g.grado ?? g.grade,
      anio: g.year,
      descripcion: g.description,
      activo: g.active,
      miembros: g._count.memberships,
      asignaciones: g._count.assignments,
      creadoEn: g.createdAt,
    })),
  });
});

/** POST /api/admin/grupos */
export const POST = ruta(async (req) => {
  const sesion = await requiereRolApi('ADMIN');
  verificarCsrf(req, sesion);
  const { ip } = infoCliente(req);
  const datos = await leerCuerpo(req, esquemaCrearGrupo);

  const existente = await prisma.group.findFirst({
    where: { name: datos.nombre, year: datos.anio },
  });
  if (existente) throw conflicto('Ya existe un grupo con ese nombre en el mismo ano.');

  const grupo = await prisma.group.create({
    data: {
      name: datos.nombre,
      grade: datos.grado || null,
      year: datos.anio,
      description: datos.descripcion || null,
      createdById: sesion.usuario.id,
    },
  });

  await auditar({
    accion: ACCIONES.GRUPO_CREADO,
    actorId: sesion.usuario.id,
    tipoEntidad: 'Group',
    entidadId: grupo.id,
    meta: { nombre: grupo.name, anio: grupo.year },
    ip,
  });

  return respuestaOk(
    {
      grupo: {
        id: grupo.id,
        nombre: grupo.name,
        grado: grupo.grade,
        anio: grupo.year,
        descripcion: grupo.description,
        activo: grupo.active,
        miembros: 0,
        asignaciones: 0,
      },
    },
    201,
  );
});

import { prisma } from '@/lib/db';
import {
  ruta,
  leerCuerpo,
  respuestaOk,
  infoCliente,
  conflicto,
  noEncontrado,
} from '@/lib/http';
import { requiereRolApi, verificarCsrf } from '@/lib/auth/guard';
import { auditar, ACCIONES } from '@/lib/audit';
import { esquemaActualizarGrupo } from '@/lib/esquemas/grupos';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

type Ctx = { params: Promise<{ id: string }> };

/** PATCH /api/admin/grupos/[id] */
export const PATCH = ruta<Ctx['params']>(async (req, ctx) => {
  const sesion = await requiereRolApi('ADMIN');
  verificarCsrf(req, sesion);
  const { ip } = infoCliente(req);
  const { id } = await ctx.params;
  const datos = await leerCuerpo(req, esquemaActualizarGrupo);

  const grupo = await prisma.group.findUnique({ where: { id } });
  if (!grupo) throw noEncontrado('Grupo');

  const nombreFinal = datos.nombre ?? grupo.name;
  const anioFinal = datos.anio ?? grupo.year;

  if (nombreFinal !== grupo.name || anioFinal !== grupo.year) {
    const duplicado = await prisma.group.findFirst({
      where: { name: nombreFinal, year: anioFinal, id: { not: id } },
    });
    if (duplicado) throw conflicto('Ya existe otro grupo con ese nombre en el mismo ano.');
  }

  await prisma.group.update({
    where: { id },
    data: {
      ...(datos.nombre !== undefined ? { name: datos.nombre } : {}),
      ...(datos.grado !== undefined ? { grade: datos.grado || null } : {}),
      ...(datos.anio !== undefined ? { year: datos.anio } : {}),
      ...(datos.descripcion !== undefined ? { description: datos.descripcion || null } : {}),
      ...(datos.activo !== undefined ? { active: datos.activo } : {}),
    },
  });

  await auditar({
    accion: ACCIONES.GRUPO_ACTUALIZADO,
    actorId: sesion.usuario.id,
    tipoEntidad: 'Group',
    entidadId: id,
    meta: { campos: Object.keys(datos) },
    ip,
  });

  return respuestaOk({ actualizado: true });
});

/** DELETE /api/admin/grupos/[id] */
export const DELETE = ruta<Ctx['params']>(async (req, ctx) => {
  const sesion = await requiereRolApi('ADMIN');
  verificarCsrf(req, sesion);
  const { ip } = infoCliente(req);
  const { id } = await ctx.params;

  const grupo = await prisma.group.findUnique({
    where: { id },
    include: { _count: { select: { assignments: true } } },
  });
  if (!grupo) throw noEncontrado('Grupo');

  const intentos = await prisma.attempt.count({
    where: { quiz: { assignments: { some: { groupId: id } } } },
  });
  if (intentos > 0) {
    throw conflicto(
      'No se puede eliminar el grupo porque tiene intentos de quiz registrados. Desactivalo en su lugar.',
    );
  }

  await prisma.group.delete({ where: { id } });

  await auditar({
    accion: ACCIONES.GRUPO_ELIMINADO,
    actorId: sesion.usuario.id,
    tipoEntidad: 'Group',
    entidadId: id,
    meta: { nombre: grupo.name, asignaciones: grupo._count.assignments },
    ip,
  });

  return respuestaOk({ eliminado: true });
});

import { prisma } from '@/lib/db';
import { ruta, leerCuerpo, respuestaOk, infoCliente, solicitudInvalida, noEncontrado } from '@/lib/http';
import { requiereRolApi, verificarCsrf } from '@/lib/auth/guard';
import { auditar, ACCIONES } from '@/lib/audit';
import { esquemaMiembros, esquemaQuitarMiembro } from '@/lib/esquemas/grupos';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

type Ctx = { params: Promise<{ id: string }> };

/** GET /api/admin/grupos/[id]/miembros */
export const GET = ruta<Ctx['params']>(async (_req, ctx) => {
  await requiereRolApi('ADMIN', 'TEACHER');
  const { id } = await ctx.params;

  const grupo = await prisma.group.findUnique({
    where: { id },
    include: {
      memberships: { include: { user: true }, orderBy: { createdAt: 'asc' } },
    },
  });
  if (!grupo) throw noEncontrado('Grupo');

  return respuestaOk({
    grupo: { id: grupo.id, nombre: grupo.name, anio: grupo.year },
    miembros: grupo.memberships.map((m) => ({
      id: m.user.id,
      nombre: m.user.name,
      correo: m.user.email,
      activo: m.user.active,
    })),
  });
});

/** POST /api/admin/grupos/[id]/miembros */
export const POST = ruta<Ctx['params']>(async (req, ctx) => {
  const sesion = await requiereRolApi('ADMIN');
  verificarCsrf(req, sesion);
  const { ip } = infoCliente(req);
  const { id } = await ctx.params;
  const datos = await leerCuerpo(req, esquemaMiembros);

  const grupo = await prisma.group.findUnique({ where: { id } });
  if (!grupo) throw noEncontrado('Grupo');

  const estudiantes = await prisma.user.findMany({
    where: { id: { in: datos.usuarioIds }, role: 'STUDENT' },
    select: { id: true },
  });
  if (estudiantes.length !== datos.usuarioIds.length) {
    throw solicitudInvalida('Todos los usuarios seleccionados deben existir y ser estudiantes.');
  }

  const existentes = await prisma.groupMembership.findMany({
    where: { groupId: id, userId: { in: datos.usuarioIds } },
    select: { userId: true },
  });
  const yaEstan = new Set(existentes.map((e) => e.userId));
  const nuevos = estudiantes.filter((e) => !yaEstan.has(e.id));

  if (nuevos.length) {
    await prisma.groupMembership.createMany({
      data: nuevos.map((e) => ({ userId: e.id, groupId: id })),
    });
  }

  await auditar({
    accion: ACCIONES.MIEMBRO_AGREGADO,
    actorId: sesion.usuario.id,
    tipoEntidad: 'Group',
    entidadId: id,
    meta: { agregados: nuevos.length, yaEstaban: yaEstan.size },
    ip,
  });

  return respuestaOk({ agregados: nuevos.length, yaEstaban: yaEstan.size });
});

/** DELETE /api/admin/grupos/[id]/miembros  (body: { usuarioId }) */
export const DELETE = ruta<Ctx['params']>(async (req, ctx) => {
  const sesion = await requiereRolApi('ADMIN');
  verificarCsrf(req, sesion);
  const { ip } = infoCliente(req);
  const { id } = await ctx.params;
  const { usuarioId } = await leerCuerpo(req, esquemaQuitarMiembro);

  const eliminados = await prisma.groupMembership.deleteMany({
    where: { groupId: id, userId: usuarioId },
  });

  await auditar({
    accion: ACCIONES.MIEMBRO_ELIMINADO,
    actorId: sesion.usuario.id,
    tipoEntidad: 'Group',
    entidadId: id,
    meta: { usuarioId, eliminados: eliminados.count },
    ip,
  });

  return respuestaOk({ eliminado: eliminados.count > 0 });
});

import { ruta, leerCuerpo, respuestaOk, infoCliente, validar } from '@/lib/http';
import { requiereRolApi, verificarCsrf } from '@/lib/auth/guard';
import { auditar, ACCIONES } from '@/lib/audit';
import { esquemaAjustes, guardarAjustes, obtenerAjustes, DEFINICIONES_AJUSTES } from '@/lib/settings';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

/** GET /api/admin/ajustes */
export const GET = ruta(async () => {
  await requiereRolApi('ADMIN');
  const valores = await obtenerAjustes();
  return respuestaOk({ valores, definiciones: DEFINICIONES_AJUSTES });
});

/** PUT /api/admin/ajustes */
export const PUT = ruta(async (req) => {
  const sesion = await requiereRolApi('ADMIN');
  verificarCsrf(req, sesion);
  const { ip } = infoCliente(req);

  const datos = await leerCuerpo(req, esquemaAjustes);
  const limpios = validar(esquemaAjustes, datos);

  await guardarAjustes(limpios);
  await auditar({
    accion: ACCIONES.AJUSTES_ACTUALIZADOS,
    actorId: sesion.usuario.id,
    meta: { claves: Object.keys(limpios) },
    ip,
  });

  const valores = await obtenerAjustes();
  return respuestaOk({ valores });
});

import { Suspense } from 'react';
import { redirect } from 'next/navigation';
import type { Metadata } from 'next';
import { usuarioActual } from '@/lib/auth/guard';
import { obtenerAjuste } from '@/lib/settings';
import { FormularioLogin } from './FormularioLogin';

export const metadata: Metadata = { title: 'Iniciar sesion' };
export const dynamic = 'force-dynamic';

export default async function PaginaLogin({
  searchParams,
}: {
  searchParams: Promise<{ siguiente?: string }>;
}) {
  const usuario = await usuarioActual();
  if (usuario) redirect('/panel');

  const { siguiente } = await searchParams;
  const nombreInstitucion = await obtenerAjuste('institucion.nombre');

  return (
    <main className="flex min-h-screen items-center justify-center bg-gradient-to-br from-brand-50 via-slate-50 to-white px-4 py-10">
      <div className="w-full max-w-md">
        <div className="mb-8 text-center">
          <p className="text-sm font-semibold uppercase tracking-widest text-brand-600">
            QuizColegio
          </p>
          <h1 className="mt-2 text-2xl font-bold text-slate-900">{nombreInstitucion}</h1>
          <p className="mt-1 text-sm text-slate-600">
            Sistema de gestion y aplicacion de quices
          </p>
        </div>

        <div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm">
          <Suspense fallback={<p className="text-sm text-slate-500">Cargando formulario...</p>}>
            <FormularioLogin siguiente={siguiente ?? '/panel'} />
          </Suspense>
        </div>

        <p className="mt-6 text-center text-xs text-slate-500">
          Acceso restringido. Todas las acciones quedan registradas en la auditoria del sistema.
        </p>
      </div>
    </main>
  );
}

'use client';

import { useRouter } from 'next/navigation';
import { useState, type FormEvent } from 'react';
import { api, ErrorPeticion } from '@/lib/cliente/api';
import { Alerta, Boton, Campo, Entrada } from '@/components/ui';

export function FormularioLogin({ siguiente }: { siguiente: string }) {
  const router = useRouter();
  const [email, setEmail] = useState('');
  const [contrasena, setContrasena] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [enviando, setEnviando] = useState(false);

  async function enviar(evento: FormEvent<HTMLFormElement>) {
    evento.preventDefault();
    setError(null);
    setEnviando(true);
    try {
      await api.post('/api/auth/login', { email, contrasena });
      router.push(siguiente.startsWith('/') ? siguiente : '/panel');
      router.refresh();
    } catch (e) {
      if (e instanceof ErrorPeticion) setError(e.message);
      else setError('No se pudo iniciar sesion. Intentalo nuevamente.');
      setEnviando(false);
    }
  }

  return (
    <form onSubmit={enviar} className="flex flex-col gap-4" noValidate>
      <h2 className="text-lg font-semibold text-slate-900">Iniciar sesion</h2>

      {error && <Alerta tipo="error">{error}</Alerta>}

      <Campo etiqueta="Correo electronico" htmlFor="email" requerido>
        <Entrada
          id="email"
          name="email"
          type="email"
          autoComplete="username"
          required
          autoFocus
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          placeholder="docente@colegio.edu"
        />
      </Campo>

      <Campo etiqueta="Contrasena" htmlFor="contrasena" requerido>
        <Entrada
          id="contrasena"
          name="contrasena"
          type="password"
          autoComplete="current-password"
          required
          value={contrasena}
          onChange={(e) => setContrasena(e.target.value)}
          placeholder="••••••••"
        />
      </Campo>

      <Boton type="submit" disabled={enviando} tamano="lg">
        {enviando ? 'Verificando...' : 'Entrar'}
      </Boton>
    </form>
  );
}

