export function menuParaRol(rol: Rol | string): ItemMenu[] {
  const comunes: ItemMenu[] = [{ href: '/panel', etiqueta: 'Panel', icono: '🏠' }];

  if (rol === 'ADMIN') {
    return [
      ...comunes,
      { href: '/docentes/documentos', etiqueta: 'Documentos', icono: '📄' },
      { href: '/docentes/quices', etiqueta: 'Quices', icono: '📝' },
      { href: '/reportes', etiqueta: 'Reportes', icono: '📊' },
      { href: '/admin/usuarios', etiqueta: 'Usuarios', icono: '👥' },
      { href: '/admin/grupos', etiqueta: 'Grupos', icono: '🏫' },
      { href: '/admin/configuracion', etiqueta: 'Configuracion', icono: '⚙️' },
      { href: '/admin/auditoria', etiqueta: 'Auditoria', icono: '🕵️' },
    ];
  }

  if (rol === 'TEACHER') {
