'use client';

import { useMemo, useState } from 'react';
import { useRouter } from 'next/navigation';
import { api, ErrorPeticion } from '@/lib/cliente/api';
import type { GrupoDto, UsuarioDto } from '@/lib/cliente/tipos';
import {
  Alerta,
  Boton,
  Campo,
  Casilla,
  Entrada,
  Insignia,
  Selector,
  Tabla,
  Tarjeta,
  Vacio,
} from '@/components/ui';
import { ETIQUETA_ROL, ROLES, type Rol } from '@/lib/dominio/constantes';

type Formulario = {
  id: string | null;
  nombre: string;
  correo: string;
  contrasena: string;
  rol: Rol;
  activo: boolean;
  grupos: string[];
};

const FORMULARIO_VACIO: Formulario = {
  id: null,
  nombre: '',
  correo: '',
  contrasena: '',
  rol: 'STUDENT',
  activo: true,
  grupos: [],
};

export function GestorUsuarios({
  usuariosIniciales,
  grupos,
}: {
  usuariosIniciales: UsuarioDto[];
  grupos: GrupoDto[];
}) {
  const router = useRouter();
  const [usuarios, setUsuarios] = useState(usuariosIniciales);
  const [form, setForm] = useState<Formulario | null>(null);
  const [buscar, setBuscar] = useState('');
  const [filtroRol, setFiltroRol] = useState<'TODOS' | Rol>('TODOS');
  const [mensaje, setMensaje] = useState<{ tipo: 'exito' | 'error'; texto: string } | null>(null);
  const [errores, setErrores] = useState<Record<string, string>>({});
  const [guardando, setGuardando] = useState(false);

  const filtrados = useMemo(() => {
    const termino = buscar.trim().toLowerCase();
    return usuarios.filter((usuario) => {
      const coincideRol = filtroRol === 'TODOS' || usuario.rol === filtroRol;
      const coincideTexto =
        termino === '' ||
        usuario.nombre.toLowerCase().includes(termino) ||
        usuario.correo.toLowerCase().includes(termino);
      return coincideRol && coincideTexto;
    });
  }, [usuarios, buscar, filtroRol]);

  function abrirCrear() {
    setErrores({});
    setForm({ ...FORMULARIO_VACIO });
  }

  function abrirEditar(usuario: UsuarioDto) {
    setErrores({});
    setForm({
      id: usuario.id,
      nombre: usuario.nombre,
      correo: usuario.correo,
      contrasena: '',
      rol: usuario.rol as Rol,
      activo: usuario.activo,
      grupos: usuario.grupos.map((g) => g.id),
    });
  }

  async function recargar() {
    const datos = await api.get<{ usuarios: UsuarioDto[] }>('/api/admin/usuarios');
    setUsuarios(datos.usuarios);
    router.refresh();
  }

  async function guardar() {
    if (!form) return;
    setGuardando(true);
    setErrores({});
    setMensaje(null);
    try {
      if (form.id) {
        await api.patch(`/api/admin/usuarios/${form.id}`, {
          nombre: form.nombre,
          correo: form.correo,
          rol: form.rol,
          activo: form.activo,
          grupos: form.rol === 'STUDENT' ? form.grupos : [],
          ...(form.contrasena ? { contrasena: form.contrasena } : {}),
        });
        setMensaje({ tipo: 'exito', texto: 'Usuario actualizado correctamente.' });
      } else {
        await api.post('/api/admin/usuarios', {
          nombre: form.nombre,
          correo: form.correo,
          contrasena: form.contrasena,
          rol: form.rol,
          activo: form.activo,
          grupos: form.rol === 'STUDENT' ? form.grupos : [],
        });
        setMensaje({ tipo: 'exito', texto: 'Usuario creado correctamente.' });
      }
      setForm(null);
      await recargar();
    } catch (e) {
      if (e instanceof ErrorPeticion) {
        setMensaje({ tipo: 'error', texto: e.message });
        setErrores(e.campos ?? {});
      } else {
        setMensaje({ tipo: 'error', texto: 'No se pudo guardar el usuario.' });
      }
    } finally {
      setGuardando(false);
    }
  }

  async function eliminar(usuario: UsuarioDto) {
    const confirmado = window.confirm(
      `¿Eliminar definitivamente a ${usuario.nombre}? Esta accion no se puede deshacer.`,
    );
    if (!confirmado) return;
    setMensaje(null);
    try {
      await api.del(`/api/admin/usuarios/${usuario.id}`);
      setMensaje({ tipo: 'exito', texto: `Usuario ${usuario.nombre} eliminado.` });
      await recargar();
    } catch (e) {
      setMensaje({
        tipo: 'error',
        texto: e instanceof ErrorPeticion ? e.message : 'No se pudo eliminar el usuario.',
      });
    }
  }

  function alternarGrupo(id: string) {
    setForm((actual) => {
      if (!actual) return actual;
      const yaEsta = actual.grupos.includes(id);
      return {
        ...actual,
        grupos: yaEsta ? actual.grupos.filter((g) => g !== id) : [...actual.grupos, id],
      };
    });
  }

  const estudiantesFiltrables = form?.rol === 'STUDENT';

  return (
    <div className="flex flex-col gap-4">
      {mensaje && <Alerta tipo={mensaje.tipo}>{mensaje.texto}</Alerta>}

      <Tarjeta
        titulo="Usuarios del colegio"
        descripcion={`${usuarios.length} usuario(s) registrados`}
        acciones={
          <Boton type="button" onClick={abrirCrear}>
            + Nuevo usuario
          </Boton>
        }
      >
        <div className="mb-4 flex flex-wrap gap-3">
          <div className="min-w-[220px] flex-1">
            <Campo etiqueta="Buscar">
              <Entrada
                type="search"
                placeholder="Nombre o correo"
                value={buscar}
                onChange={(e) => setBuscar(e.target.value)}
              />
            </Campo>
          </div>
          <div className="w-48">
            <Campo etiqueta="Rol">
              <Selector
                value={filtroRol}
                onChange={(e) => setFiltroRol(e.target.value as 'TODOS' | Rol)}
              >
                <option value="TODOS">Todos</option>
                {ROLES.map((rol) => (
                  <option key={rol} value={rol}>
                    {ETIQUETA_ROL[rol]}
                  </option>
                ))}
              </Selector>
            </Campo>
          </div>
        </div>

        {filtrados.length === 0 ? (
          <Vacio mensaje="No hay usuarios que coincidan con el filtro." />
        ) : (
          <Tabla cabeceras={['Nombre', 'Correo', 'Rol', 'Grupos', 'Estado', 'Acciones']}>
            {filtrados.map((usuario) => (
              <tr key={usuario.id}>
                <td className="px-3 py-2 font-medium text-slate-800">{usuario.nombre}</td>
                <td className="px-3 py-2 text-slate-600">{usuario.correo}</td>
                <td className="px-3 py-2">
                  <Insignia
                    tono={
                      usuario.rol === 'ADMIN' ? 'violeta' : usuario.rol === 'TEACHER' ? 'azul' : 'verde'
                    }
                  >
                    {ETIQUETA_ROL[usuario.rol as Rol] ?? usuario.rol}
                  </Insignia>
                </td>
                <td className="px-3 py-2 text-slate-600">
                  {usuario.grupos.length === 0 ? '-' : usuario.grupos.map((g) => g.nombre).join(', ')}
                </td>
                <td className="px-3 py-2">
                  {usuario.activo ? (
                    <Insignia tono="verde">Activo</Insignia>
                  ) : (
                    <Insignia tono="rojo">Inactivo</Insignia>
                  )}
                </td>
                <td className="px-3 py-2">
                  <div className="flex gap-2">
                    <Boton tamano="sm" variante="secundario" onClick={() => abrirEditar(usuario)}>
                      Editar
                    </Boton>
                    <Boton tamano="sm" variante="peligro" onClick={() => eliminar(usuario)}>
                      Eliminar
                    </Boton>
                  </div>
                </td>
              </tr>
            ))}
          </Tabla>
        )}
      </Tarjeta>

      {form && (
        <Tarjeta
          titulo={form.id ? 'Editar usuario' : 'Nuevo usuario'}
          descripcion={
            form.id
              ? 'Deja la contrasena vacia para conservarla. Si la cambias, se cerraran sus sesiones.'
              : 'La contrasena debe tener al menos 8 caracteres.'
          }
          acciones={
            <Boton variante="secundario" tamano="sm" onClick={() => setForm(null)}>
              Cancelar
            </Boton>
          }
        >
          <form
            className="flex flex-col gap-4"
            onSubmit={(e) => {
              e.preventDefault();
              void guardar();
            }}
          >
            <div className="grid gap-4 md:grid-cols-2">
              <Campo etiqueta="Nombre completo" requerido error={errores.nombre}>
                <Entrada
                  value={form.nombre}
                  onChange={(e) => setForm({ ...form, nombre: e.target.value })}
                  required
                  minLength={3}
                />
              </Campo>
              <Campo etiqueta="Correo electronico" requerido error={errores.email ?? errores.correo}>
                <Entrada
                  type="email"
                  value={form.correo}
                  onChange={(e) => setForm({ ...form, correo: e.target.value })}
                  required
                />
              </Campo>
              <Campo
                etiqueta="Contrasena"
                requerido={!form.id}
                error={errores.contrasena}
                ayuda={form.id ? 'Opcional al editar' : undefined}
              >
                <Entrada
                  type="password"
                  value={form.contrasena}
                  onChange={(e) => setForm({ ...form, contrasena: e.target.value })}
                  required={!form.id}
                  minLength={8}
                  autoComplete="new-password"
                />
              </Campo>
              <Campo etiqueta="Rol" requerido error={errores.rol}>
                <Selector
                  value={form.rol}
                  onChange={(e) => setForm({ ...form, rol: e.target.value as Rol })}
                >
                  {ROLES.map((rol) => (
                    <option key={rol} value={rol}>
                      {ETIQUETA_ROL[rol]}
                    </option>
                  ))}
                </Selector>
              </Campo>
            </div>

            <Casilla
              etiqueta="Cuenta activa"
              descripcion="Si la desactivas, el usuario no podra iniciar sesion."
              checked={form.activo}
              onChange={(e) => setForm({ ...form, activo: e.target.checked })}
            />

            {estudiantesFiltrables && (
              <div>
                <p className="mb-2 text-sm font-medium text-slate-700">Grupos del estudiante</p>
                {grupos.length === 0 ? (
                  <Alerta tipo="aviso">
                    Todavia no hay grupos creados. Crea uno en la seccion Grupos.
                  </Alerta>
                ) : (
                  <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
                    {grupos.map((grupo) => (
                      <label
                        key={grupo.id}
                        className="flex cursor-pointer items-center gap-2 rounded-lg border border-slate-200 px-3 py-2 text-sm hover:bg-slate-50"
                      >
                        <input
                          type="checkbox"
                          className="h-4 w-4 rounded border-slate-300 text-brand-600"
                          checked={form.grupos.includes(grupo.id)}
                          onChange={() => alternarGrupo(grupo.id)}
                        />
                        <span>
                          {grupo.nombre}
                          <span className="ml-1 text-xs text-slate-500">({grupo.anio})</span>
                        </span>
                      </label>
                    ))}
                  </div>
                )}
              </div>
            )}

            <div className="flex gap-2">
              <Boton type="submit" disabled={guardando}>
                {guardando ? 'Guardando...' : form.id ? 'Guardar cambios' : 'Crear usuario'}
              </Boton>
              <Boton type="button" variante="secundario" onClick={() => setForm(null)}>
                Cancelar
              </Boton>
            </div>
          </form>
        </Tarjeta>
      )}
    </div>
  );
}

import { prisma } from '@/lib/db';
import { requiereRol } from '@/lib/auth/guard';
import type { GrupoDto, UsuarioDto } from '@/lib/cliente/tipos';
import { GestorUsuarios } from './GestorUsuarios';

export const dynamic = 'force-dynamic';

export default async function PaginaUsuarios() {
  await requiereRol('ADMIN');

  const [usuarios, grupos] = await Promise.all([
    prisma.user.findMany({
      orderBy: [{ role: 'asc' }, { name: 'asc' }],
      include: { memberships: { include: { group: true } } },
    }),
    prisma.group.findMany({ where: { active: true }, orderBy: [{ year: 'desc' }, { name: 'asc' }] }),
  ]);

  const usuariosDto: UsuarioDto[] = usuarios.map((u) => ({
    id: u.id,
    nombre: u.name,
    correo: u.email,
    rol: u.role,
    activo: u.active,
    grupos: u.memberships.map((m) => ({ id: m.group.id, nombre: m.group.name })),
  }));

  const gruposDto: GrupoDto[] = grupos.map((g) => ({
    id: g.id,
    nombre: g.name,
    grado: g.grade,
    anio: g.year,
    descripcion: g.description,
    activo: g.active,
    miembros: 0,
    asignaciones: 0,
  }));

  return (
    <div className="flex flex-col gap-4">
      <div>
        <h1 className="text-2xl font-bold text-slate-900">Usuarios</h1>
        <p className="mt-1 text-sm text-slate-600">
          Crea administradores, docentes y estudiantes, asignalos a grupos y controla su acceso.
        </p>
      </div>
      <GestorUsuarios usuariosIniciales={usuariosDto} grupos={gruposDto} />
    </div>
  );
}

'use client';

import { useMemo, useState } from 'react';
import { useRouter } from 'next/navigation';
import { api, ErrorPeticion } from '@/lib/cliente/api';
import type { GrupoDto, UsuarioDto } from '@/lib/cliente/tipos';
import {
  Alerta,
  Boton,
  Campo,
  Entrada,
  Insignia,
  Selector,
  Tabla,
  Tarjeta,
  Vacio,
} from '@/components/ui';

type FormularioGrupo = {
  id: string | null;
  nombre: string;
  grado: string;
  anio: number;
  descripcion: string;
  activo: boolean;
};

export function GestorGrupos({
  gruposIniciales,
  estudiantes,
  anioActual,
}: {
  gruposIniciales: GrupoDto[];
  estudiantes: UsuarioDto[];
  anioActual: number;
}) {
  const router = useRouter();
  const [grupos, setGrupos] = useState(gruposIniciales);
  const [form, setForm] = useState<FormularioGrupo | null>(null);
  const [mensaje, setMensaje] = useState<{ tipo: 'exito' | 'error' | 'aviso'; texto: string } | null>(null);
  const [errores, setErrores] = useState<Record<string, string>>({});
  const [guardando, setGuardando] = useState(false);
  const [grupoMiembros, setGrupoMiembros] = useState<GrupoDto | null>(null);
  const [seleccionados, setSeleccionados] = useState<string[]>([]);
  const [filtroEstudiante, setFiltroEstudiante] = useState('');

  const estudiantesFiltrados = useMemo(() => {
    const termino = filtroEstudiante.trim().toLowerCase();
    const yaEnGrupo = new Set(
      estudiantes.filter((e) => e.grupos.some((g) => g.id === grupoMiembros?.id)).map((e) => e.id),
    );
    return estudiantes
      .filter((e) => !termino || e.nombre.toLowerCase().includes(termino) || e.correo.toLowerCase().includes(termino))
      .sort((a, b) => Number(yaEnGrupo.has(a.id)) - Number(yaEnGrupo.has(b.id)) || a.nombre.localeCompare(b.nombre))
      .map((e) => ({ ...e, yaEsta: yaEnGrupo.has(e.id) }));
  }, [estudiantes, filtroEstudiante, grupoMiembros]);

  async function recargar() {
    const datos = await api.get<{ grupos: GrupoDto[] }>('/api/admin/grupos');
    setGrupos(datos.grupos);
    router.refresh();
  }

  async function guardar() {
    if (!form) return;
    setGuardando(true);
    setErrores({});
    setMensaje(null);
    try {
      const cuerpo = {
        nombre: form.nombre,
        grado: form.grado,
        anio: form.anio,
        descripcion: form.descripcion,
      };
      if (form.id) {
        await api.patch(`/api/admin/grupos/${form.id}`, { ...cuerpo, activo: form.activo });
        setMensaje({ tipo: 'exito', texto: 'Grupo actualizado.' });
      } else {
        await api.post('/api/admin/grupos', cuerpo);
        setMensaje({ tipo: 'exito', texto: 'Grupo creado.' });
      }
      setForm(null);
      await recargar();
    } catch (e) {
      if (e instanceof ErrorPeticion) {
        setMensaje({ tipo: 'error', texto: e.message });
        setErrores(e.campos ?? {});
      } else {
        setMensaje({ tipo: 'error', texto: 'No se pudo guardar el grupo.' });
      }
    } finally {
      setGuardando(false);
    }
  }

  async function eliminar(grupo: GrupoDto) {
    if (!window.confirm(`¿Eliminar el grupo ${grupo.nombre}? Los estudiantes no seran eliminados.`)) return;
    setMensaje(null);
    try {
      await api.del(`/api/admin/grupos/${grupo.id}`);
      setMensaje({ tipo: 'exito', texto: 'Grupo eliminado.' });
      if (grupoMiembros?.id === grupo.id) setGrupoMiembros(null);
      await recargar();
    } catch (e) {
      setMensaje({
        tipo: 'error',
        texto: e instanceof ErrorPeticion ? e.message : 'No se pudo eliminar el grupo.',
      });
    }
  }

  async function agregarMiembros() {
    if (!grupoMiembros || seleccionados.length === 0) return;
    setGuardando(true);
    setMensaje(null);
    try {
      const resultado = await api.post<{ agregados: number; yaEstaban: number }>(
        `/api/admin/grupos/${grupoMiembros.id}/miembros`,
        { usuarioIds: seleccionados },
      );
      setMensaje({
        tipo: 'exito',
        texto: `Se agregaron ${resultado.agregados} estudiante(s).${
          resultado.yaEstaban ? ` ${resultado.yaEstaban} ya estaban en el grupo.` : ''
        }`,
      });
      setSeleccionados([]);
      await recargar();
    } catch (e) {
      setMensaje({
        tipo: 'error',
        texto: e instanceof ErrorPeticion ? e.message : 'No se pudieron agregar los estudiantes.',
      });
    } finally {
      setGuardando(false);
    }
  }

  async function quitarMiembro(usuarioId: string) {
    if (!grupoMiembros) return;
    setMensaje(null);
    try {
      await api.del(`/api/admin/grupos/${grupoMiembros.id}/miembros`, { usuarioId });
      await recargar();
      setEstudiantes((previos) =>
        previos.map((e) =>
          e.id === usuarioId
            ? { ...e, grupos: e.grupos.filter((g) => g.id !== grupoMiembros.id) }
            : e,
        ),
      );
    } catch (e) {
      setMensaje({
        tipo: 'error',
        texto: e instanceof ErrorPeticion ? e.message : 'No se pudo quitar el estudiante.',
      });
    }
  }

  // Mantenemos una copia local de estudiantes para reflejar cambios sin recargar la pagina.
  const [estudiantesLocales, setEstudiantes] = useState(estudiantes);

  return (
    <div className="flex flex-col gap-4">
      {mensaje && <Alerta tipo={mensaje.tipo}>{mensaje.texto}</Alerta>}

      <Tarjeta
        titulo="Cursos y grupos"
        descripcion={`${grupos.length} grupo(s)`}
        acciones={
          <Boton
            onClick={() =>
              setForm({
                id: null,
                nombre: '',
                grado: '',
                anio: anioActual,
                descripcion: '',
                activo: true,
              })
            }
          >
            + Nuevo grupo
          </Boton>
        }
      >
        {grupos.length === 0 ? (
          <Vacio mensaje="Todavia no hay grupos creados." />
        ) : (
          <Tabla cabeceras={['Grupo', 'Grado', 'Ano', 'Estudiantes', 'Quices asignados', 'Estado', 'Acciones']}>
            {grupos.map((grupo) => (
              <tr key={grupo.id}>
                <td className="px-3 py-2 font-medium text-slate-800">{grupo.nombre}</td>
                <td className="px-3 py-2 text-slate-600">{grupo.grado ?? '-'}</td>
                <td className="px-3 py-2 text-slate-600">{grupo.anio}</td>
                <td className="px-3 py-2 text-slate-600">{grupo.miembros}</td>
                <td className="px-3 py-2 text-slate-600">{grupo.asignaciones}</td>
                <td className="px-3 py-2">
                  {grupo.activo ? <Insignia tono="verde">Activo</Insignia> : <Insignia tono="rojo">Inactivo</Insignia>}
                </td>
                <td className="px-3 py-2">
                  <div className="flex flex-wrap gap-2">
                    <Boton tamano="sm" variante="secundario" onClick={() => setGrupoMiembros(grupo)}>
                      Estudiantes
                    </Boton>
                    <Boton
                      tamano="sm"
                      variante="secundario"
                      onClick={() =>
                        setForm({
                          id: grupo.id,
                          nombre: grupo.nombre,
                          grado: grupo.grado ?? '',
                          anio: grupo.anio,
                          descripcion: grupo.descripcion ?? '',
                          activo: grupo.activo,
                        })
                      }
                    >
                      Editar
                    </Boton>
                    <Boton tamano="sm" variante="peligro" onClick={() => eliminar(grupo)}>
                      Eliminar
                    </Boton>
                  </div>
                </td>
              </tr>
            ))}
          </Tabla>
        )}
      </Tarjeta>

      {form && (
        <Tarjeta
          titulo={form.id ? 'Editar grupo' : 'Nuevo grupo'}
          acciones={
            <Boton variante="secundario" tamano="sm" onClick={() => setForm(null)}>
              Cancelar
            </Boton>
          }
        >
          <form
            className="flex flex-col gap-4"
            onSubmit={(e) => {
              e.preventDefault();
              void guardar();
            }}
          >
            <div className="grid gap-4 md:grid-cols-3">
              <Campo etiqueta="Nombre del grupo" requerido error={errores.nombre}>
                <Entrada
                  value={form.nombre}
                  onChange={(e) => setForm({ ...form, nombre: e.target.value })}
                  required
                  placeholder="Ej: Decimo A"
                />
              </Campo>
              <Campo etiqueta="Grado / nivel" error={errores.grado}>
                <Entrada
                  value={form.grado}
                  onChange={(e) => setForm({ ...form, grado: e.target.value })}
                  placeholder="Ej: 10"
                />
              </Campo>
              <Campo etiqueta="Ano escolar" requerido error={errores.anio}>
                <Entrada
                  type="number"
                  value={form.anio}
                  min={2000}
                  max={2100}
                  onChange={(e) => setForm({ ...form, anio: Number(e.target.value) })}
                  required
                />
              </Campo>
            </div>
            <Campo etiqueta="Descripcion" error={errores.descripcion}>
              <Entrada
                value={form.descripcion}
                onChange={(e) => setForm({ ...form, descripcion: e.target.value })}
                placeholder="Opcional"
              />
            </Campo>
            {form.id && (
              <label className="flex items-center gap-2 text-sm text-slate-700">
                <input
                  type="checkbox"
                  className="h-4 w-4 rounded border-slate-300 text-brand-600"
                  checked={form.activo}
                  onChange={(e) => setForm({ ...form, activo: e.target.checked })}
                />
                Grupo activo
              </label>
            )}
            <div className="flex gap-2">
              <Boton type="submit" disabled={guardando}>
                {guardando ? 'Guardando...' : form.id ? 'Guardar cambios' : 'Crear grupo'}
              </Boton>
              <Boton type="button" variante="secundario" onClick={() => setForm(null)}>
                Cancelar
              </Boton>
            </div>
          </form>
        </Tarjeta>
      )}

      {grupoMiembros && (
        <Tarjeta
          titulo={`Estudiantes de ${grupoMiembros.nombre}`}
          descripcion="Selecciona estudiantes para agregarlos. Los que ya pertenecen aparecen marcados."
          acciones={
            <Boton variante="secundario" tamano="sm" onClick={() => setGrupoMiembros(null)}>
              Cerrar
            </Boton>
          }
        >
          <div className="flex flex-col gap-4">
            <div className="max-w-sm">
              <Campo etiqueta="Filtrar estudiantes">
                <Entrada
                  type="search"
                  placeholder="Nombre o correo"
                  value={filtroEstudiante}
                  onChange={(e) => setFiltroEstudiante(e.target.value)}
                />
              </Campo>
            </div>

            {estudiantesLocales.length === 0 ? (
              <Alerta tipo="aviso">
                No hay estudiantes registrados. Crea estudiantes en la seccion Usuarios.
              </Alerta>
            ) : (
              <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
                {estudiantesFiltrados.map((estudiante) => (
                  <label
                    key={estudiante.id}
                    className="flex cursor-pointer items-center gap-2 rounded-lg border border-slate-200 px-3 py-2 text-sm hover:bg-slate-50"
                  >
                    <input
                      type="checkbox"
                      className="h-4 w-4 rounded border-slate-300 text-brand-600"
                      checked={seleccionados.includes(estudiante.id)}
                      onChange={() =>
                        setSeleccionados((actual) =>
                          actual.includes(estudiante.id)
                            ? actual.filter((id) => id !== estudiante.id)
                            : [...actual, estudiante.id],
                        )
                      }
                    />
                    <span>
                      {estudiante.nombre}
                      <span className="ml-1 text-xs text-slate-500">{estudiante.correo}</span>
                      {estudiante.yaEsta && (
                        <span className="ml-1 text-xs font-medium text-emerald-700">· ya en el grupo</span>
                      )}
                    </span>
                  </label>
                ))}
              </div>
            )}

            <div className="flex flex-wrap gap-2">
              <Boton onClick={agregarMiembros} disabled={guardando || seleccionados.length === 0}>
                {guardando ? 'Agregando...' : `Agregar ${seleccionados.length || ''} estudiante(s)`}
              </Boton>
              <Boton
                variante="secundario"
                onClick={() => setSeleccionados(estudiantesLocales.map((e) => e.id))}
              >
                Seleccionar todos
              </Boton>
              <Boton variante="secundario" onClick={() => setSeleccionados([])}>
                Limpiar seleccion
              </Boton>
            </div>

            <div>
              <p className="mb-2 text-sm font-medium text-slate-700">
                Miembros actuales ({estudiantesLocales.filter((e) => e.grupos.some((g) => g.id === grupoMiembros.id)).length})
              </p>
              <div className="flex flex-wrap gap-2">
                {estudiantesLocales
                  .filter((e) => e.grupos.some((g) => g.id === grupoMiembros.id))
                  .map((estudiante) => (
                    <span
                      key={estudiante.id}
                      className="inline-flex items-center gap-2 rounded-full border border-slate-200 bg-white px-3 py-1 text-sm text-slate-700"
                    >
                      {estudiante.nombre}
                      <button
                        type="button"
                        onClick={() => quitarMiembro(estudiante.id)}
                        className="text-xs font-semibold text-red-600 hover:underline"
                        aria-label={`Quitar a ${estudiante.nombre} del grupo`}
                      >
                        Quitar
                      </button>
                    </span>
                  ))}
                {estudiantesLocales.filter((e) => e.grupos.some((g) => g.id === grupoMiembros.id)).length === 0 && (
                  <p className="text-sm text-slate-500">Este grupo aun no tiene estudiantes.</p>
                )}
              </div>
            </div>
          </div>
        </Tarjeta>
      )}
    </div>
  );
}

