input.content:
import { prisma } from '@/lib/db';
import { requiereRol } from '@/lib/auth/guard';
import { obtenerAjusteNumero } from '@/lib/settings';
import type { GrupoDto, UsuarioDto } from '@/lib/cliente/tipos';
import { GestorGrupos } from './GestorGrupos';

export const dynamic = 'force-dynamic';

export default async function PaginaGrupos() {
  await requiereRol('ADMIN');

  const [grupos, estudiantes, anioActual] = await Promise.all([
    prisma.group.findMany({
      orderBy: [{ year: 'desc' }, { name: 'asc' }],
      include: { _count: { select: { memberships: true, assignments: true } } },
    }),
    prisma.user.findMany({
      where: { role: 'STUDENT' },
      orderBy: { name: 'asc' },
      include: { memberships: { include: { group: true } } },
    }),
    obtenerAjusteNumero('institucion.anio', new Date().getFullYear()),
  ]);

  const gruposDto: GrupoDto[] = grupos.map((g) => ({
    id: g.id,
    nombre: g.name,
    grado: g.grade,
    anio: g.year,
    descripcion: g.description,
    activo: g.active,
    miembros: g._count.memberships,
    asignaciones: g._count.assignments,
  }));

  const estudiantesDto: UsuarioDto[] = estudiantes.map((e) => ({
    id: e.id,
    nombre: e.name,
    correo: e.email,
    rol: e.role,
    activo: e.active,
    grupos: e.memberships.map((m) => ({ id: m.group.id, nombre: m.group.name })),
  }));

  return (
    <div className="flex flex-col gap-4">
      <div>
        <h1 className="text-2xl font-bold text-slate-900">Grupos</h1>
        <p className="mt-1 text-sm text-slate-600">
          Organiza a los estudiantes en cursos o grupos y administra sus miembros.
        </p>
      </div>
      <GestorGrupos gruposIniciales={gruposDto} estudiantes={estudiantesDto} anioActual={anioActual} />
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { api, ErrorPeticion } from '@/lib/cliente/api';
import type { AjusteDto } from '@/lib/cliente/tipos';
import { Alerta, Boton, Campo, Casilla, Entrada, Selector, Tarjeta } from '@/components/ui';

const TITULOS_GRUPO: Record<AjusteDto['grupo'], string> = {
  institucion: 'Institucion',
  academico: 'Academico',
  quiz: 'Quices',
  archivos: 'Archivos',
  seguridad: 'Seguridad y modo seguro',
};

export function FormularioAjustes({
  definiciones,
  valoresIniciales,
  proveedorLlm,
  llmListo,
  maxUploadMb,
}: {
  definiciones: AjusteDto[];
  valoresIniciales: Record<string, string>;
  proveedorLlm: string;
  llmListo: boolean;
  maxUploadMb: number;
}) {
  const router = useRouter();
  const [valores, setValores] = useState(valoresIniciales);
  const [mensaje, setMensaje] = useState<{ tipo: 'exito' | 'error'; texto: string } | null>(null);
  const [errores, setErrores] = useState<Record<string, string>>({});
  const [guardando, setGuardando] = useState(false);

  const grupos = Array.from(new Set(definiciones.map((d) => d.grupo)));

  function actualizar(clave: string, valor: string) {
    setValores((actual) => ({ ...actual, [clave]: valor }));
  }

  async function guardar() {
    setGuardando(true);
    setMensaje(null);
    setErrores({});
    try {
      const datos = await api.put<{ valores: Record<string, string> }>('/api/admin/ajustes', valores);
      setValores(datos.valores);
      setMensaje({ tipo: 'exito', texto: 'Configuracion guardada correctamente.' });
      router.refresh();
    } catch (e) {
      if (e instanceof ErrorPeticion) {
        setMensaje({ tipo: 'error', texto: e.message });
        setErrores(e.campos ?? {});
      } else {
        setMensaje({ tipo: 'error', texto: 'No se pudo guardar la configuracion.' });
      }
    } finally {
      setGuardando(false);
    }
  }

  return (
    <form
      className="flex flex-col gap-4"
      onSubmit={(e) => {
        e.preventDefault();
        void guardar();
      }}
    >
      {mensaje && <Alerta tipo={mensaje.tipo}>{mensaje.texto}</Alerta>}

      {grupos.map((grupo) => (
        <Tarjeta key={grupo} titulo={TITULOS_GRUPO[grupo]}>
          <div className="grid gap-4 md:grid-cols-2">
            {definiciones
              .filter((definicion) => definicion.grupo === grupo)
              .map((definicion) => (
                <div key={definicion.clave}>
                  {definicion.tipo === 'booleano' ? (
                    <Casilla
                      etiqueta={definicion.etiqueta}
                      descripcion={definicion.descripcion}
                      checked={valores[definicion.clave] === 'true'}
                      onChange={(e) => actualizar(definicion.clave, e.target.checked ? 'true' : 'false')}
                    />
                  ) : (
                    <Campo
                      etiqueta={definicion.etiqueta}
                      ayuda={definicion.descripcion}
                      error={errores[definicion.clave]}
                      htmlFor={definicion.clave}
                    >
                      {definicion.tipo === 'texto' ? (
                        <Entrada
                          id={definicion.clave}
                          value={valores[definicion.clave] ?? ''}
                          onChange={(e) => actualizar(definicion.clave, e.target.value)}
                        />
                      ) : (
                        <Entrada
                          id={definicion.clave}
                          type="number"
                          step={definicion.tipo === 'entero' ? 1 : 'any'}
                          value={valores[definicion.clave] ?? ''}
                          onChange={(e) => actualizar(definicion.clave, e.target.value)}
                        />
                      )}
                    </Campo>
                  )}
                </div>
              ))}
          </div>
        </Tarjeta>
      ))}

      <Tarjeta
        titulo="Proveedor de inteligencia artificial"
        descripcion="Se configura con variables de entorno. La clave de API nunca llega al navegador."
      >
        <div className="flex flex-col gap-3 text-sm">
          <div className="flex items-center gap-2">
            <span className="text-slate-600">Proveedor activo:</span>
            <code className="rounded bg-slate-100 px-2 py-0.5 font-mono text-xs text-slate-800">
              {proveedorLlm}
            </code>
            {llmListo ? (
              <span className="text-emerald-700">Configurado</span>
            ) : (
              <span className="text-amber-700">Sin credenciales: define la API key en el archivo .env</span>
            )}
          </div>
          <p className="text-xs text-slate-500">
            Para cambiar de proveedor edita <code className="font-mono">LLM_PROVIDER</code> y las claves
            correspondientes en el archivo <code className="font-mono">.env</code>, y reinicia el servidor.
          </p>
          <Campo etiqueta="Tamano maximo de subida efectivo" ayuda="Valor tomado de MAX_UPLOAD_MB en el entorno.">
            <Selector disabled value={String(maxUploadMb)}>
              <option value={String(maxUploadMb)}>{maxUploadMb} MB</option>
            </Selector>
          </Campo>
        </div>
      </Tarjeta>

      <div className="flex gap-2">
        <Boton type="submit" disabled={guardando}>
          {guardando ? 'Guardando...' : 'Guardar configuracion'}
        </Boton>
        <Boton type="button" variante="secundario" onClick={() => setValores(valoresIniciales)}>
          Descartar cambios
        </Boton>
      </div>
    </form>
  );
}

import { requiereRol } from '@/lib/auth/guard';
import { env, llmConfigurado } from '@/lib/env';
import { DEFINICIONES_AJUSTES, obtenerAjustes } from '@/lib/settings';
import { FormularioAjustes } from './FormularioAjustes';

export const dynamic = 'force-dynamic';

export default async function PaginaConfiguracion() {
  await requiereRol('ADMIN');
  const valores = await obtenerAjustes();

  return (
    <div className="flex flex-col gap-4">
      <div>
        <h1 className="text-2xl font-bold text-slate-900">Configuracion global</h1>
        <p className="mt-1 text-sm text-slate-600">
          Valores por defecto y parametros generales del sistema.
        </p>
      </div>
      <FormularioAjustes
        definiciones={DEFINICIONES_AJUSTES.map((d) => ({
          clave: d.clave,
          etiqueta: d.etiqueta,
          descripcion: d.descripcion,
          tipo: d.tipo,
          grupo: d.grupo,
        }))}
        valoresIniciales={valores}
        proveedorLlm={env.llm.proveedor}
        llmListo={llmConfigurado()}
        maxUploadMb={env.maxUploadMb}
      />
    </div>
  );
}

import 'dotenv/config';
import { PrismaClient } from '@prisma/client';
import bcrypt from 'bcryptjs';

const prisma = new PrismaClient();
const RONDAS = Number(process.env.BCRYPT_ROUNDS ?? 10);

/** Utilidades de fecha para la ventana de disponibilidad del quiz demo. */
function dias(n: number): Date {
  return new Date(Date.now() + n * 24 * 60 * 60 * 1000);
}

async function limpiar(): Promise<void> {
  // Orden seguro respecto a las claves foraneas.
  await prisma.proctorEvent.deleteMany();
  await prisma.answer.deleteMany();
  await prisma.attempt.deleteMany();
  await prisma.quizAssignment.deleteMany();
  await prisma.quizQuestion.deleteMany();
  await prisma.quiz.deleteMany();
  await prisma.questionOption.deleteMany();
  await prisma.question.deleteMany();
  await prisma.document.deleteMany();
  await prisma.groupMembership.deleteMany();
  await prisma.group.deleteMany();
  await prisma.session.deleteMany();
  await prisma.auditLog.deleteMany();
  await prisma.setting.deleteMany();
  await prisma.user.deleteMany();
}

async function main(): Promise<void> {
  console.log('Sembrando datos de ejemplo de QuizColegio...');
  await limpiar();

  const [admin, docente, estudiante1, estudiante2, estudiante3] = await Promise.all([
    prisma.user.create({
      data: {
        name: 'Ana Administradora',
        email: 'admin@colegio.edu',
        passwordHash: await bcrypt.hash('Admin123!', RONDAS),
        role: 'ADMIN',
      },
    }),
    prisma.user.create({
      data: {
        name: 'David Docente',
        email: 'docente@colegio.edu',
        passwordHash: await bcrypt.hash('Docente123!', RONDAS),
        role: 'TEACHER',
      },
    }),
    prisma.user.create({
      data: {
        name: 'Elena Estudiante',
        email: 'estudiante1@colegio.edu',
        passwordHash: await bcrypt.hash('Estudiante123!', RONDAS),
        role: 'STUDENT',
      },
    }),
    prisma.user.create({
      data: {
        name: 'Esteban Estudiante',
        email: 'estudiante2@colegio.edu',
        passwordHash: await bcrypt.hash('Estudiante123!', RONDAS),
        role: 'STUDENT',
      },
    }),
    prisma.user.create({
      data: {
        name: 'Sofia Estudiante',
        email: 'estudiante3@colegio.edu',
        passwordHash: await bcrypt.hash('Estudiante123!', RONDAS),
        role: 'STUDENT',
      },
    }),
  ]);

  const anio = new Date().getFullYear();

  const grupoDecimo = await prisma.group.create({
    data: {
      name: 'Decimo A',
      grade: '10',
      year: anio,
      description: 'Grupo de decimo grado, jornada de la manana.',
      createdById: admin.id,
    },
  });

  const grupoNoveno = await prisma.group.create({
    data: {
      name: 'Noveno B',
      grade: '9',
      year: anio,
      description: 'Grupo de noveno grado.',
      createdById: admin.id,
    },
  });

  await prisma.groupMembership.createMany({
    data: [
      { userId: estudiante1.id, groupId: grupoDecimo.id },
      { userId: estudiante2.id, groupId: grupoDecimo.id },
      { userId: estudiante3.id, groupId: grupoNoveno.id },
    ],
  });

  // --- Documento de ejemplo (texto extraido, sin PDF asociado) --------------
  await prisma.document.create({
    data: {
      title: 'Material de estudio: el sistema solar',
      originalName: 'sistema-solar.pdf',
      storagePath: './storage/uploads/demo-sistema-solar.pdf',
      mimeType: 'application/pdf',
      sizeBytes: 0,
      pageCount: 3,
      charCount: 620,
      status: 'EXTRACTED',
      extractedText:
        'El sistema solar esta formado por el Sol y todos los cuerpos que orbitan a su alrededor. ' +
        'Los planetas interiores son Mercurio, Venus, la Tierra y Marte; son pequenos y rocosos. ' +
        'Los planetas exteriores son Jupiter, Saturno, Urano y Neptuno; son gigantes gaseosos o helados. ' +
        'Jupiter es el planeta mas grande del sistema solar y Saturno es famoso por sus anillos. ' +
        'La Tierra completa una orbita alrededor del Sol en aproximadamente 365 dias.',
      uploadedById: docente.id,
    },
  });

  // --- Banco de preguntas ---------------------------------------------------
  type Definicion = {
    tipo: string;
    enunciado: string;
    explicacion: string;
    tema: string;
    dificultad: string;
    pagina: number;
    opciones: { texto: string; correcta: boolean }[];
  };

  const definiciones: Definicion[] = [
    {
      tipo: 'MCQ_SINGLE',
      enunciado: '¿Cual es el planeta mas grande del sistema solar?',
      explicacion: 'Jupiter es el planeta de mayor tamano y masa del sistema solar.',
      tema: 'Sistema solar',
      dificultad: 'EASY',
      pagina: 1,
      opciones: [
        { texto: 'Jupiter', correcta: true },
        { texto: 'Saturno', correcta: false },
        { texto: 'La Tierra', correcta: false },
        { texto: 'Neptuno', correcta: false },
      ],
    },
    {
      tipo: 'MCQ_SINGLE',
      enunciado: '¿Cuantos dias tarda la Tierra en completar una orbita alrededor del Sol?',
      explicacion: 'La Tierra tarda aproximadamente 365 dias en dar una vuelta completa al Sol.',
      tema: 'Sistema solar',
      dificultad: 'EASY',
      pagina: 2,
      opciones: [
        { texto: '365 dias', correcta: true },
        { texto: '24 horas', correcta: false },
        { texto: '30 dias', correcta: false },
        { texto: '100 dias', correcta: false },
      ],
    },
    {
      tipo: 'MCQ_MULTI',
      enunciado: '¿Cuales de los siguientes son planetas interiores?',
      explicacion:
        'Mercurio, Venus, la Tierra y Marte son los planetas interiores, rocosos y mas cercanos al Sol.',
      tema: 'Sistema solar',
      dificultad: 'MEDIUM',
      pagina: 1,
      opciones: [
        { texto: 'Mercurio', correcta: true },
        { texto: 'Venus', correcta: true },
        { texto: 'Jupiter', correcta: false },
        { texto: 'Saturno', correcta: false },
      ],
    },
    {
      tipo: 'TRUE_FALSE',
      enunciado: 'Saturno es conocido por sus anillos visibles.',
      explicacion: 'Saturno posee el sistema de anillos mas grande y visible del sistema solar.',
      tema: 'Sistema solar',
      dificultad: 'EASY',
      pagina: 3,
      opciones: [
        { texto: 'Verdadero', correcta: true },
        { texto: 'Falso', correcta: false },
      ],
    },
    {
      tipo: 'SHORT_ANSWER',
      enunciado: 'Escribe el nombre del cuerpo celeste alrededor del cual orbitan los planetas.',
      explicacion: 'Todos los planetas del sistema solar orbitan alrededor del Sol.',
      tema: 'Sistema solar',
      dificultad: 'EASY',
      pagina: 1,
      opciones: [{ texto: 'Sol', correcta: true }],
    },
  ];

  const preguntasCreadas = [];
  for (const definicion of definiciones) {
    const pregunta = await prisma.question.create({
      data: {
        type: definicion.tipo,
        statement: definicion.enunciado,
        explanation: definicion.explicacion,
        topic: definicion.tema,
        difficulty: definicion.dificultad,
        sourcePage: definicion.pagina,
        status: 'APPROVED',
        origin: 'MANUAL',
        points: 1,
        authorId: docente.id,
        options: {
          create: definicion.opciones.map((opcion, indice) => ({
            label: String.fromCharCode(65 + indice),
            text: opcion.texto,
            isCorrect: opcion.correcta,
            position: indice,
          })),
        },
      },
    });
    preguntasCreadas.push(pregunta);
  }

  // --- Quiz demo publicado --------------------------------------------------
  const quizDemo = await prisma.quiz.create({
    data: {
      title: 'Quiz de ejemplo: el sistema solar',
      description:
        'Quiz de demostracion con cinco preguntas sobre el sistema solar. Usalo para probar el flujo completo del estudiante.',
      authorId: docente.id,
      status: 'PUBLISHED',
      publishedAt: new Date(),
      availableFrom: dias(-1),
      availableTo: dias(30),
      navigationMode: 'FREE',
      timeLimitSec: 600,
      shuffleQuestions: true,
      shuffleOptions: true,
      maxAttempts: 2,
      questionCount: null,
      defaultPoints: 1,
      passingScore: 3,
      maxGrade: 5,
      showResults: 'SCORE_AND_ANSWERS',
      allowReview: true,
      secureMode: false,
      infractionThreshold: 3,
      infractionAction: 'AUTO_SUBMIT',
      blockWithoutFullscreen: true,
      questions: {
        create: preguntasCreadas.map((pregunta, indice) => ({
          questionId: pregunta.id,
          position: indice,
          points: 1,
        })),
      },
      assignments: {
        create: [{ groupId: grupoDecimo.id }],
      },
    },
  });

  await prisma.setting.createMany({
    data: [
      { key: 'institucion.nombre', value: 'Colegio San Ejemplo' },
      { key: 'institucion.anio', value: String(anio) },
      { key: 'academico.notaMinima', value: '3' },
      { key: 'academico.notaMaxima', value: '5' },
      { key: 'quiz.intentosMaximos', value: '2' },
      { key: 'quiz.modoSeguroPorDefecto', value: 'false' },
      { key: 'quiz.umbralInfracciones', value: '3' },
      { key: 'archivos.maxMB', value: process.env.MAX_UPLOAD_MB ?? '15' },
    ],
  });

  console.log('\nDatos de ejemplo creados correctamente.\n');
  console.log('Credenciales de acceso:');
  console.log('  Administrador  admin@colegio.edu         / Admin123!');
  console.log('  Docente        docente@colegio.edu       / Docente123!');
  console.log('  Estudiante 1   estudiante1@colegio.edu   / Estudiante123!');
  console.log('  Estudiante 2   estudiante2@colegio.edu   / Estudiante123!');
  console.log('  Estudiante 3   estudiante3@colegio.edu   / Estudiante123!');
  console.log('\nGrupos: Decimo A (2 estudiantes), Noveno B (1 estudiante)');
  console.log(`Quiz publicado: "${quizDemo.title}" asignado a Decimo A\n`);
}

main()
  .catch((error) => {
    console.error('Error al sembrar la base de datos:', error);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });

