$ErrorActionPreference = 'Stop'
$base = 'http://localhost:3000'
$resultados = @()

function Anota($nombre, $ok, $detalle) {
  $script:resultados += [pscustomobject]@{ Prueba = $nombre; Ok = $ok; Detalle = $detalle }
}

# 1) Ruta privada sin sesion debe redirigir a /login
try {
  $r = Invoke-WebRequest -Uri "$base/panel" -MaximumRedirection 0 -SkipHttpErrorCheck -ErrorAction SilentlyContinue
  $loc = $r.Headers.Location
  Anota 'GET /panel sin sesion redirige' ($r.StatusCode -ge 300 -and $loc -like '*/login*') "status=$($r.StatusCode) location=$loc"
} catch {
  Anota 'GET /panel sin sesion redirige' $false $_.Exception.Message
}

# 2) Login incorrecto
try {
  $r = Invoke-WebRequest -Uri "$base/api/auth/login" -Method POST -ContentType 'application/json' -Body '{"email":"admin@colegio.edu","contrasena":"clave-mala"}' -SkipHttpErrorCheck
  $cuerpo = $r.Content | ConvertFrom-Json
  Anota 'Login con clave incorrecta devuelve 401' ($r.StatusCode -eq 401) "status=$($r.StatusCode) codigo=$($cuerpo.error.codigo)"
} catch {
  Anota 'Login con clave incorrecta devuelve 401' $false $_.Exception.Message
}

# 3) Login correcto del administrador
$sesion = New-Object Microsoft.PowerShell.Commands.WebRequestSession
try {
  $r = Invoke-WebRequest -Uri "$base/api/auth/login" -Method POST -ContentType 'application/json' -WebSession $sesion -Body '{"email":"admin@colegio.edu","contrasena":"Admin123!"}' -SkipHttpErrorCheck
  $cuerpo = $r.Content | ConvertFrom-Json
  Anota 'Login correcto del administrador' ($r.StatusCode -eq 200 -and $cuerpo.datos.usuario.rol -eq 'ADMIN') "status=$($r.StatusCode) rol=$($cuerpo.datos.usuario.rol)"
} catch {
  Anota 'Login correcto del administrador' $false $_.Exception.Message
}

$cookies = $sesion.Cookies.GetCookies($base)
$csrf = $cookies['qc_csrf'].Value
Anota 'Cookie CSRF emitida' ([bool]$csrf) "csrf=$($csrf.Substring(0,6))..."

# 4) Mutacion sin token CSRF debe ser rechazada (403)
try {
  $r = Invoke-WebRequest -Uri "$base/api/admin/usuarios" -Method POST -ContentType 'application/json' -WebSession $sesion -Body '{"nombre":"Sin Csrf","correo":"sincsrf@colegio.edu","contrasena":"Clave12345","rol":"STUDENT"}' -SkipHttpErrorCheck
  $cuerpo = $r.Content | ConvertFrom-Json
  Anota 'POST sin CSRF rechazado (403)' ($r.StatusCode -eq 403) "status=$($r.StatusCode) codigo=$($cuerpo.error.codigo)"
} catch {
  Anota 'POST sin CSRF rechazado (403)' $false $_.Exception.Message
}

# 5) Crear usuario con CSRF valido
$nuevoId = $null
try {
  $r = Invoke-WebRequest -Uri "$base/api/admin/usuarios" -Method POST -ContentType 'application/json' -WebSession $sesion -Headers @{ 'x-csrf-token' = $csrf } -Body '{"nombre":"Nuevo Estudiante","correo":"nuevo@colegio.edu","contrasena":"Clave12345","rol":"STUDENT","activo":true,"grupos":[]}' -SkipHttpErrorCheck
  $cuerpo = $r.Content | ConvertFrom-Json
  $nuevoId = $cuerpo.datos.usuario.id
  Anota 'Crear usuario con CSRF valido' ($r.StatusCode -eq 200 -or $r.StatusCode -eq 201) "status=$($r.StatusCode) id=$nuevoId"
} catch {
  Anota 'Crear usuario con CSRF valido' $false $_.Exception.Message
}

# 6) Validacion Zod: correo invalido
try {
  $r = Invoke-WebRequest -Uri "$base/api/admin/usuarios" -Method POST -ContentType 'application/json' -WebSession $sesion -Headers @{ 'x-csrf-token' = $csrf } -Body '{"nombre":"X","correo":"no-es-correo","contrasena":"123","rol":"STUDENT"}' -SkipHttpErrorCheck
  $cuerpo = $r.Content | ConvertFrom-Json
  Anota 'Validacion Zod rechaza datos invalidos' ($r.StatusCode -eq 400 -and $cuerpo.error.codigo -eq 'DATOS_INVALIDOS') "status=$($r.StatusCode) campos=$(($cuerpo.error.campos.PSObject.Properties.Name) -join ',')"
} catch {
  Anota 'Validacion Zod rechaza datos invalidos' $false $_.Exception.Message
}

# 7) El docente no puede listar usuarios (403)
$sesionDocente = New-Object Microsoft.PowerShell.Commands.WebRequestSession
try {
  Invoke-WebRequest -Uri "$base/api/auth/login" -Method POST -ContentType 'application/json' -WebSession $sesionDocente -Body '{"email":"docente@colegio.edu","contrasena":"Docente123!"}' | Out-Null
  $r = Invoke-WebRequest -Uri "$base/api/admin/usuarios" -WebSession $sesionDocente -SkipHttpErrorCheck
  $cuerpo = $r.Content | ConvertFrom-Json
  Anota 'Docente no puede listar usuarios (403)' ($r.StatusCode -eq 403) "status=$($r.StatusCode) codigo=$($cuerpo.error.codigo)"
} catch {
  Anota 'Docente no puede listar usuarios (403)' $false $_.Exception.Message
}

# 8) /panel autenticado responde 200 y muestra el nombre
try {
  $r = Invoke-WebRequest -Uri "$base/panel" -WebSession $sesion -SkipHttpErrorCheck
  Anota 'GET /panel con sesion responde 200' ($r.StatusCode -eq 200 -and $r.Content -match 'Hola, Ana') "status=$($r.StatusCode)"
} catch {
  Anota 'GET /panel con sesion responde 200' $false $_.Exception.Message
}

# 9) Cabeceras de seguridad
try {
  $r = Invoke-WebRequest -Uri "$base/login" -SkipHttpErrorCheck
  $ok = ($r.Headers['X-Frame-Options'] -eq 'DENY') -and ($r.Headers['Content-Security-Policy'] -match "frame-ancestors 'none'") -and ($r.Headers['X-Content-Type-Options'] -eq 'nosniff')
  Anota 'Cabeceras de seguridad presentes' $ok "csp=$($r.Headers['Content-Security-Policy'])"
} catch {
  Anota 'Cabeceras de seguridad presentes' $false $_.Exception.Message
}

# 10) Limpieza del usuario creado
if ($nuevoId) {
  try {
    $r = Invoke-WebRequest -Uri "$base/api/admin/usuarios/$nuevoId" -Method DELETE -WebSession $sesion -Headers @{ 'x-csrf-token' = $csrf } -SkipHttpErrorCheck
    Anota 'Eliminar usuario creado' ($r.StatusCode -eq 200) "status=$($r.StatusCode)"
  } catch {
    Anota 'Eliminar usuario creado' $false $_.Exception.Message
  }
}

$resultados | Format-Table -AutoSize -Wrap
$fallos = ($resultados | Where-Object { -not $_.Ok }).Count
Write-Host "RESULTADO: $($resultados.Count - $fallos)/$($resultados.Count) pruebas correctas"
if ($fallos -gt 0) { exit 1 }

