import { mkdir, writeFile, readFile, unlink, stat } from 'node:fs/promises';
import path from 'node:path';
import { env } from '@/lib/env';

/** Utilidades de almacenamiento local de los PDFs subidos. */

export function directorioUploads(): string {
  return path.resolve(process.cwd(), env.uploadDir);
}

export async function asegurarDirectorioUploads(): Promise<string> {
  const dir = directorioUploads();
  await mkdir(dir, { recursive: true });
  return dir;
}

/**
 * Guarda un archivo dentro del directorio de subidas y devuelve su ruta
 * absoluta. El nombre se compone de la fecha y un identificador aleatorio
 * para evitar colisiones y ataques de "path traversal".
 */
export async function guardarArchivo(nombreOriginal: string, datos: Buffer): Promise<string> {
  const dir = await asegurarDirectorioUploads();
  const extension = path.extname(nombreOriginal).toLowerCase().replace(/[^.a-z0-9]/g, '') || '.pdf';
  const base = path
    .basename(nombreOriginal, path.extname(nombreOriginal))
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9_-]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 40) || 'documento';
  const identificador = `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
  const destino = path.join(dir, `${base}-${identificador}${extension}`);
  await writeFile(destino, datos);
  return destino;
}

/** Verifica que una ruta este dentro del directorio de subidas (anti traversal). */
export function rutaPermitida(ruta: string): boolean {
  const absoluta = path.resolve(ruta);
  const base = directorioUploads();
  const relativa = path.relative(base, absoluta);
  return relativa !== '' && !relativa.startsWith('..') && !path.isAbsolute(relativa);
}

export async function leerArchivo(ruta: string): Promise<Buffer> {
  if (!rutaPermitida(ruta)) throw new Error('Ruta de archivo no permitida.');
  return readFile(ruta);
}

export async function borrarArchivo(ruta: string): Promise<void> {
  if (!rutaPermitida(ruta)) return;
  try {
    await unlink(ruta);
  } catch {
    // Si el archivo ya no existe, no es un error relevante.
  }
}

export async function existeArchivo(ruta: string): Promise<boolean> {
  if (!rutaPermitida(ruta)) return false;
  try {
    const info = await stat(ruta);
    return info.isFile();
  } catch {
    return false;
  }
}

export function formatearBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(2)} MB`;
}

/**
 * Generador de PDF minimo (sin dependencias) usado para crear documentos de
 * demostracion y para las pruebas automatizadas.
 *
 * Produce un PDF 1.4 valido con texto usando la fuente base Helvetica, con
 * tabla xref correcta, de forma que pdfjs-dist pueda extraer el texto.
 */

function escaparTexto(texto: string): string {
  return texto
    .replace(/\\/g, '\\\\')
    .replace(/\(/g, '\\(')
    .replace(/\)/g, '\\)')
    .replace(/[^\x20-\x7E]/g, '?');
}

function escaparCadenaPdf(texto: string): string {
  return texto.replace(/\\/g, '\\\\').replace(/\(/g, '\\(').replace(/\)/g, '\\)');
}

type Objeto = { numero: number; contenido: string };

export function crearPdfSimple(paginas: string[][], titulo = 'Documento de demostracion'): Buffer {
  const FUENTE = 12;
  const ANCHO = 612;
  const ALTO = 792;
  const MARGEN_X = 56;
  const MARGEN_Y = 60;
  const INTERLINEADO = 16;
  const lineasPorPagina = Math.floor((ALTO - MARGEN_Y * 2) / INTERLINEADO);

  // Divide el contenido en lineas fisicas respetando el ancho aproximado.
  const lineasFisicas: string[] = [];
  for (const pagina of paginas) {
    if (lineasFisicas.length > 0) lineasFisicas.push('\f');
    for (const parrafo of pagina) {
      const maxCaracteres = Math.floor((ANCHO - MARGEN_X * 2) / (FUENTE * 0.5));
      let resto = parrafo.trim();
      if (resto === '') {
        lineasFisicas.push('');
        continue;
      }
      while (resto.length > maxCaracteres) {
        let corte = resto.lastIndexOf(' ', maxCaracteres);
        if (corte < maxCaracteres * 0.5) corte = maxCaracteres;
        lineasFisicas.push(resto.slice(0, corte));
        resto = resto.slice(corte).trim();
      }
      lineasFisicas.push(resto);
    }
  }

  // Reparte las lineas en paginas reales.
  const paginasFinales: string[][] = [];
  let actual: string[] = [];
  for (const linea of lineasFisicas) {
    if (linea === '\f' || actual.length >= lineasPorPagina) {
      if (actual.length > 0) paginasFinales.push(actual);
      actual = [];
      if (linea === '\f') continue;
    }
    actual.push(linea);
  }
  if (actual.length > 0) paginasFinales.push(actual);
  if (paginasFinales.length === 0) paginasFinales.push(['(documento vacio)']);

  const objetos: Objeto[] = [];
  const totalPaginas = paginasFinales.length;
  const idPaginas = 2;
  const idFuente = 3;
  const primerContenido = 4;

  objetos.push({ numero: 1, contenido: `<< /Type /Catalog /Pages ${idPaginas} 0 R >>` });

  const idsPaginas: number[] = [];
  const idsContenido: number[] = [];
  for (let i = 0; i < totalPaginas; i += 1) {
    idsPaginas.push(primerContenido + i * 2);
    idsContenido.push(primerContenido + i * 2 + 1);
  }

  objetos.push({
    numero: idPaginas,
    contenido: `<< /Type /Pages /Kids [${idsPaginas
      .map((id) => `${id} 0 R`)
      .join(' ')}] /Count ${totalPaginas} >>`,
  });

  objetos.push({
    numero: idFuente,
    contenido: '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>',
  });

  for (let i = 0; i < totalPaginas; i += 1) {
    const numeroPagina = idsPaginas[i]!;
    const numeroContenido = idsContenido[i]!;

    objetos.push({
      numero: numeroPagina,
      contenido:
        `<< /Type /Page /Parent ${idPaginas} 0 R /MediaBox [0 0 ${ANCHO} ${ALTO}] ` +
        `/Resources << /Font << /F1 ${idFuente} 0 R >> >> /Contents ${numeroContenido} 0 R >>`,
    });

    const lineas = paginasFinales[i]!;
    let flujo = 'BT\n';
    lineas.forEach((linea, indice) => {
      const y = ALTO - MARGEN_Y - indice * INTERLINEADO;
      flujo += `/F1 ${FUENTE} Tf 1 0 0 1 ${MARGEN_X} ${y} Tm (${escaparTexto(linea)}) Tj\n`;
    });
    flujo += 'ET';

    objetos.push({
      numero: numeroContenido,
      contenido: `<< /Length ${Buffer.byteLength(flujo, 'latin1')} >>\nstream\n${flujo}\nendstream`,
    });
  }

  objetos.push({
    numero: idFuente + totalPaginas * 2 + 1,
    contenido: `<< /Title (${escaparCadenaPdf(titulo)}) /Producer (QuizColegio) >>`,
  });

  objetos.sort((a, b) => a.numero - b.numero);

  let pdf = '%PDF-1.4\n';
  const offsets: number[] = [];
  for (const objeto of objetos) {
    offsets[objeto.numero] = Buffer.byteLength(pdf, 'latin1');
    pdf += `${objeto.numero} 0 obj\n${objeto.contenido}\nendobj\n`;
  }

  const maxObjeto = Math.max(...objetos.map((o) => o.numero));
  const inicioXref = Buffer.byteLength(pdf, 'latin1');
  pdf += `xref\n0 ${maxObjeto + 1}\n0000000000 65535 f \n`;
  for (let i = 1; i <= maxObjeto; i += 1) {
    const offset = offsets[i];
    pdf += offset === undefined
      ? '0000000000 65535 f \n'
      : `${offset.toString().padStart(10, '0')} 00000 n \n`;
  }
  pdf += `trailer\n<< /Size ${maxObjeto + 1} /Root 1 0 R /Info ${maxObjeto} 0 R >>\nstartxref\n${inicioXref}\n%%EOF\n`;

  return Buffer.from(pdf, 'latin1');
}

import { env } from '@/lib/env';

export type ResultadoExtraccion = {
  paginas: string[];
  texto: string;
  pageCount: number;
  usadoOcr: boolean;
  caracteres: number;
  aviso?: string;
};

export class ErrorPdf extends Error {
  readonly codigo: string;
  constructor(codigo: string, mensaje: string) {
    super(mensaje);
    this.name = 'ErrorPdf';
    this.codigo = codigo;
  }
}

type ItemTexto = { str?: string; hasEOL?: boolean };

/**
 * Extrae el texto de un PDF usando pdfjs-dist (build legacy para Node).
 * Si el PDF no tiene capa de texto (documento escaneado) y el OCR esta
 * habilitado, se intenta reconocer el texto con tesseract.js.
 */
export async function extraerTextoPdf(datos: Buffer): Promise<ResultadoExtraccion> {
  if (datos.length === 0) {
    throw new ErrorPdf('PDF_VACIO', 'El archivo PDF esta vacio (0 bytes).');
  }
  const cabecera = datos.subarray(0, 5).toString('latin1');
  if (!cabecera.startsWith('%PDF')) {
    throw new ErrorPdf(
      'PDF_INVALIDO',
      'El archivo no parece ser un PDF valido (no se encontro la cabecera %PDF).',
    );
  }

  const paginas = await extraerConPdfjs(datos);
  const texto = paginas.join('\n\n').trim();

  // Umbral heuristico: menos de 40 caracteres suele indicar un PDF escaneado.
  if (texto.length >= 40) {
    return {
      paginas,
      texto,
      pageCount: paginas.length,
      usadoOcr: false,
      caracteres: texto.length,
    };
  }

  if (!env.pdf.ocrActivo) {
    return {
      paginas,
      texto,
      pageCount: paginas.length,
      usadoOcr: false,
      caracteres: texto.length,
      aviso:
        'El PDF no tiene capa de texto utilizable (parece escaneado). Activa OCR_ENABLED=true en el archivo .env para intentar reconocerlo con OCR.',
    };
  }

  const ocr = await extraerConOcr(datos, paginas.length);
  return {
    paginas: ocr.paginas,
    texto: ocr.texto,
    pageCount: ocr.paginas.length,
    usadoOcr: true,
    caracteres: ocr.texto.length,
    aviso: ocr.aviso,
  };
}

async function extraerConPdfjs(datos: Buffer): Promise<string[]> {
  let pdfjs: any;
  try {
    pdfjs = await import('pdfjs-dist/legacy/build/pdf.mjs');
  } catch (error) {
    throw new ErrorPdf(
      'PDFJS_NO_DISPONIBLE',
      `No se pudo cargar el motor de PDF: ${(error as Error).message}`,
    );
  }

  const tarea = pdfjs.getDocument({
    data: new Uint8Array(datos),
    useSystemFonts: false,
    isEvalSupported: false,
    disableFontFace: true,
    // Evita que pdfjs intente descargar datos de fuentes por red.
    useWorkerFetch: false,
  });

  let documento: any;
  try {
    documento = await tarea.promise;
  } catch (error) {
    throw new ErrorPdf(
      'PDF_CORRUPTO',
      `No se pudo leer el PDF (archivo corrupto o protegido): ${(error as Error).message}`,
    );
  }

  const paginas: string[] = [];
  try {
    for (let numero = 1; numero <= documento.numPages; numero += 1) {
      const pagina = await documento.getPage(numero);
      const contenido = await pagina.getTextContent();
      let textoPagina = '';
      for (const item of contenido.items as ItemTexto[]) {
        if (typeof item.str === 'string') textoPagina += item.str;
        if (item.hasEOL) textoPagina += '\n';
      }
      paginas.push(limpiarTexto(textoPagina));
      pagina.cleanup?.();
    }
  } finally {
    await documento.destroy?.();
  }

  return paginas;
}

function limpiarTexto(texto: string): string {
  return texto
    .replace(/\r\n?/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/ ?\n ?/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

/**
 * OCR opcional. Se necesita renderizar cada pagina a imagen; para ello se
 * importa dinamicamente "@napi-rs/canvas" (opcional). Si no esta instalado se
 * devuelve un aviso claro en lugar de fallar.
 */
async function extraerConOcr(
  datos: Buffer,
  paginasEstimadas: number,
): Promise<{ paginas: string[]; texto: string; aviso?: string }> {
  let canvas: any;
  try {
    canvas = await import('@napi-rs/canvas');
  } catch {
    return {
      paginas: [''],
      texto: '',
      aviso:
        'OCR solicitado, pero falta el paquete opcional "@napi-rs/canvas" para rasterizar las paginas. Ejecuta "npm install @napi-rs/canvas" para habilitarlo.',
    };
  }

  const { createWorker } = await import('tesseract.js');
  const pdfjs: any = await import('pdfjs-dist/legacy/build/pdf.mjs');
  const documento = await pdfjs.getDocument({ data: new Uint8Array(datos), isEvalSupported: false })
    .promise;

  const maximo = Math.min(documento.numPages, Math.max(env.pdf.ocrMaxPaginas, 1));
  const trabajador = await createWorker(env.pdf.ocrIdioma);
  const paginas: string[] = [];

  try {
    for (let numero = 1; numero <= maximo; numero += 1) {
      const pagina = await documento.getPage(numero);
      const viewport = pagina.getViewport({ scale: 2 });
      const lienzo = canvas.createCanvas(viewport.width, viewport.height);
      const contexto = lienzo.getContext('2d');
      contexto.fillStyle = '#ffffff';
      contexto.fillRect(0, 0, viewport.width, viewport.height);
      await pagina.render({ canvasContext: contexto, viewport, canvas: lienzo }).promise;
      const png: Buffer = lienzo.toBuffer('image/png');
      const resultado = await trabajador.recognize(png);
      paginas.push(limpiarTexto(resultado.data.text ?? ''));
      pagina.cleanup?.();
    }
  } finally {
    await trabajador.terminate();
    await documento.destroy?.();
  }

  const aviso =
    documento.numPages > maximo
      ? `Se aplico OCR solo a las primeras ${maximo} de ${documento.numPages} paginas (OCR_MAX_PAGES).`
      : undefined;

  return { paginas: paginas.length ? paginas : [`(${paginasEstimadas} paginas sin texto reconocible)`], texto: paginas.join('\n\n'), aviso };
}

import { env } from '@/lib/env';

export type Fragmento = {
  indice: number;
  texto: string;
  paginaInicio: number;
  paginaFin: number;
  caracteres: number;
};

const MARCA_PAGINA = /\[\[PAGINA (\d+)\]\]/g;

/**
 * Divide el documento en fragmentos (chunks) con solape, respetando limites de
 * parrafo y oracion, y conservando de que pagina proviene cada fragmento.
 */
export function fragmentarPaginas(
  paginas: string[],
  tamano = env.pdf.chunkSize,
  solape = env.pdf.chunkSolape,
): Fragmento[] {
  const tamanoSeguro = Math.max(tamano, 500);
  const solapeSeguro = Math.min(Math.max(solape, 0), Math.floor(tamanoSeguro / 2));

  // Texto marcado con la pagina de origen.
  const marcado = paginas
    .map((pagina, indice) => `\n[[PAGINA ${indice + 1}]]\n${pagina}`)
    .join('\n')
    .trim();

  if (marcado.length === 0) return [];

  const fragmentos: Fragmento[] = [];
  let inicio = 0;
  let indice = 0;

  while (inicio < marcado.length) {
    let fin = Math.min(inicio + tamanoSeguro, marcado.length);

    if (fin < marcado.length) {
      // Busca un buen punto de corte: doble salto, salto de pagina o punto.
      const ventana = marcado.slice(inicio, fin);
      const minimo = Math.floor(ventana.length * 0.6);
      const candidatos = [
        ventana.lastIndexOf('\n\n', ventana.length),
        ventana.lastIndexOf('. ', ventana.length),
        ventana.lastIndexOf('\n', ventana.length),
      ].filter((posicion) => posicion >= minimo);
      if (candidatos.length > 0) {
        fin = inicio + Math.max(...candidatos) + 1;
      }
    }

    const crudo = marcado.slice(inicio, fin);
    const paginasDetectadas: number[] = [];
    for (const coincidencia of crudo.matchAll(MARCA_PAGINA)) {
      paginasDetectadas.push(Number(coincidencia[1]));
    }

    const texto = crudo.replace(MARCA_PAGINA, '').trim();

    if (texto.length >= 40) {
      fragmentos.push({
        indice,
        texto,
        paginaInicio: paginasDetectadas[0] ?? anteriorPagina(fragments(fragmentos)) ?? 1,
        paginaFin: paginasDetectadas[paginasDetectadas.length - 1] ?? (paginasDetectadas[0] ?? 1),
        caracteres: texto.length,
      });
      indice += 1;
    }

    if (fin >= marcado.length) break;
    inicio = Math.max(fin - solapeSeguro, inicio + 1);
  }

  return fragmentos;
}

// Utilidades internas ------------------------------------------------------

function fragments(lista: Fragmento[]): Fragmento[] {
  return lista;
}

function anteriorPagina(lista: Fragmento[]): number | undefined {
  const ultimo = lista[lista.length - 1];
  return ultimo ? ultimo.paginaFin : undefined;
}

/** Resumen legible del contenido de un fragmento (para la interfaz). */
export function vistaPreviaFragmento(fragmento: Fragmento, largo = 160): string {
  const texto = fragmento.texto.replace(/\s+/g, ' ').trim();
  return texto.length > largo ? `${texto.slice(0, largo)}…` : texto;
}

