import { z } from 'zod';
import {
  dificultadSchema,
  tipoPreguntaSchema,
  type Dificultad,
  type TipoPregunta,
} from '@/lib/dominio/constantes';

/* ------------------------------------------------------------------ *
 * Contrato de la capa de abstraccion de proveedores de LLM
 * ------------------------------------------------------------------ */

export type PeticionGeneracionLlm = {
  texto: string;
  paginaInicio: number;
  paginaFin: number;
  cantidad: number;
  tipos: TipoPregunta[];
  dificultad: Dificultad;
  idioma: string;
  instruccionesExtra?: string;
  /** Enunciados ya existentes para evitar repetirlos. */
  evitar: string[];
};

export type PeticionImportacionLlm = {
  texto: string;
  paginaInicio: number;
  paginaFin: number;
  idioma: string;
};

export interface LLMProvider {
  readonly nombre: string;
  readonly modelo: string;
  generarPreguntas(peticion: PeticionGeneracionLlm): Promise<unknown>;
  importarPreguntas(peticion: PeticionImportacionLlm): Promise<unknown>;
}

export class ErrorLlm extends Error {
  readonly codigo: string;
  readonly detalle?: unknown;
  constructor(codigo: string, mensaje: string, detalle?: unknown) {
    super(mensaje);
    this.name = 'ErrorLlm';
    this.codigo = codigo;
    this.detalle = detalle;
  }
}

/* ------------------------------------------------------------------ *
 * Esquema estricto de la respuesta del modelo
 * ------------------------------------------------------------------ */

export const opcionLlmSchema = z.object({
  texto: z.string().trim().min(1, 'La opcion no puede estar vacia.').max(600),
  // null cuando se importa un examen y no se puede determinar la respuesta.
  correcta: z.boolean().nullable(),
});

export const preguntaLlmSchema = z.object({
  enunciado: z.string().trim().min(8, 'El enunciado es demasiado corto.').max(2000),
  tipo: tipoPreguntaSchema.optional(),
  opciones: z.array(opcionLlmSchema).min(1).max(10).optional(),
  explicacion: z.string().trim().max(1200).optional(),
  tema: z.string().trim().max(160).optional(),
  pagina: z.coerce.number().int().positive().max(100000).optional(),
  dificultad: dificultadSchema.optional(),
  requiereRevision: z.boolean().optional(),
});

export const loteLlmSchema = z.object({
  preguntas: z.array(preguntaLlmSchema).min(0).max(40),
});

export type PreguntaLlm = z.infer<typeof preguntaLlmSchema>;
export type LoteLlm = z.infer<typeof loteLlmSchema>;

/* ------------------------------------------------------------------ *
 * Normalizacion: convierte la salida del modelo en datos consistentes
 * ------------------------------------------------------------------ */

export type OpcionNormalizada = { etiqueta: string; texto: string; correcta: boolean };

export type PreguntaNormalizada = {
  enunciado: string;
  tipo: TipoPregunta;
  opciones: OpcionNormalizada[];
  explicacion: string;
  tema: string;
  pagina: number | null;
  dificultad: Dificultad;
  respuestaPendiente: boolean;
};

export type OpcionesNormalizacion = {
  tipoPorDefecto: TipoPregunta;
  dificultadPorDefecto: Dificultad;
  paginaPorDefecto: number;
};

function esVerdaderoFalso(texto: string): boolean {
  const limpio = texto
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
  return ['verdadero', 'falso', 'true', 'false', 'v', 'f'].includes(limpio);
}

function inferirTipo(pregunta: PreguntaLlm, correctas: number, total: number): TipoPregunta {
  if (pregunta.tipo) return pregunta.tipo;
  if (total === 2) {
    const textos = (pregunta.opciones ?? []).map((o) => o.texto);
    if (textos.length === 2 && textos.every(esVerdaderoFalso)) return 'TRUE_FALSE';
  }
  if (correctas > 1) return 'MCQ_MULTI';
  if (correctas <= 1 && total >= 2) return 'MCQ_SINGLE';
  return 'SHORT_ANSWER';
}

/**
 * Valida y normaliza una lista de preguntas devuelta por el modelo.
 * Descarta las que no cumplen las reglas minimas (por ejemplo: opcion
 * multiple sin ninguna respuesta correcta cuando venia de generacion).
 */
export function normalizarPreguntas(
  lote: LoteLlm,
  opciones: OpcionesNormalizacion,
  permitirSinRespuesta: boolean,
): { validas: PreguntaNormalizada[]; descartadas: { enunciado: string; motivo: string }[] } {
  const validas: PreguntaNormalizada[] = [];
  const descartadas: { enunciado: string; motivo: string }[] = [];

  for (const pregunta of lote.preguntas) {
    const enunciado = pregunta.enunciado.replace(/\s+/g, ' ').trim();
    const opcionesCrudas = (pregunta.opciones ?? []).map((opcion) => ({
      texto: opcion.texto.replace(/\s+/g, ' ').trim(),
      correcta: opcion.correcta === true,
      sinDefinir: opcion.correcta === null || opcion.correcta === undefined,
    }));

    const sinDefinir = opcionesCrudas.some((o) => o.sinDefinir);
    const correctas = opcionesCrudas.filter((o) => o.correcta).length;
    const tipo = inferirTipo(pregunta, correctas, opcionesCrudas.length);

    const respuestaPendiente = (sinDefinir || correctas === 0) && permitirSinRespuesta;
    if (sinDefinir && !permitirSinRespuesta) {
      descartadas.push({ enunciado, motivo: 'La respuesta correcta no esta definida.' });
      continue;
    }
    if (correctas === 0 && !permitirSinRespuesta) {
      descartadas.push({ enunciado, motivo: 'Ninguna opcion marcada como correcta.' });
      continue;
    }
    if (tipo !== 'SHORT_ANSWER' && opcionesCrudas.length < 2) {
      descartadas.push({ enunciado, motivo: 'Se requieren al menos dos opciones.' });
      continue;
    }
    if (tipo === 'MCQ_SINGLE' && correctas > 1) {
      descartadas.push({ enunciado, motivo: 'Se marcaron varias respuestas correctas.' });
      continue;
    }

    let opcionesFinales = opcionesCrudas.map((opcion) => ({
      texto: opcion.texto,
      correcta: opcion.correcta,
    }));

    if (tipo === 'TRUE_FALSE') {
      // Normaliza las dos opciones a Verdadero/Falso conservando el orden.
      opcionesFinales = (pregunta.opciones ?? []).map((opcion) => {
        const limpio = opcion.texto.trim().toLowerCase();
        const esVerdadero = ['verdadero', 'true', 'v'].includes(limpio);
        return { texto: esVerdadero ? 'Verdadero' : 'Falso', correcta: opcion.correcta === true };
      });
      if (opcionesFinales.length !== 2) {
        descartadas.push({ enunciado, motivo: 'Verdadero/Falso necesita exactamente dos opciones.' });
        continue;
      }
    }

    if (tipo === 'SHORT_ANSWER' && opcionesFinales.length === 0) {
      opcionesFinales = [{ texto: '(respuesta abierta)', correcta: false }];
    }

    validas.push({
      enunciado,
      tipo,
      opciones: opcionesFinales.map((opcion, indice) => ({
        etiqueta: String.fromCharCode(65 + indice),
        texto: opcion.texto,
        correcta: opcion.correcta,
      })),
      explicacion: (pregunta.explicacion ?? '').trim(),
      tema: (pregunta.tema ?? '').trim(),
      pagina: pregunta.pagina ?? opciones.paginaPorDefecto,
      dificultad: pregunta.dificultad ?? opciones.dificultadPorDefecto,
      respuestaPendiente: pregunta.requiereRevision === true || respuestaPendiente,
    });
  }

  return { validas, descartadas };
}

import { z } from 'zod';
import { ErrorLlm } from '@/lib/llm/tipos';

/**
 * Extrae un objeto JSON de la respuesta de un modelo, que puede venir con
 * texto adicional o dentro de un bloque de codigo Markdown.
 */
export function extraerJson(respuesta: string): unknown {
  const texto = respuesta.trim();

  const bloques = texto.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidatos: string[] = [];
  if (bloques && bloques[1]) candidatos.push(bloques[1].trim());

  const primerLlave = texto.indexOf('{');
  const ultimaLlave = texto.lastIndexOf('}');
  if (primerLlave !== -1 && ultimaLlave > primerLlave) {
    candidatos.push(texto.slice(primerLlave, ultimaLlave + 1));
  }
  candidatos.push(texto);

  for (const candidato of candidatos) {
    try {
      return JSON.parse(candidato);
    } catch {
      // Se prueba con el siguiente candidato.
    }
  }
  throw new ErrorLlm('JSON_NO_PARSEABLE', 'La respuesta del modelo no contiene JSON valido.', {
    respuesta: texto.slice(0, 800),
  });
}

export type OpcionesJson<T> = {
  /** Funcion que realiza una llamada al modelo y devuelve el texto. */
  invocar: (mensajeCorreccion?: string) => Promise<string>;
  esquema: z.ZodType<T>;
  /** Reintentos adicionales cuando el JSON es invalido (por defecto 2). */
  maxReintentos?: number;
};

/**
 * Llama al modelo y valida la respuesta con Zod. Si el JSON es invalido o no
 * cumple el esquema, se reintenta (hasta 2 veces) indicando el error exacto.
 */
export async function generarJsonValidado<T>({
  invocar,
  esquema,
  maxReintentos = 2,
}: OpcionesJson<T>): Promise<T> {
  let correccion: string | undefined;
  let ultimoError = 'Error desconocido';

  for (let intento = 0; intento <= maxReintentos; intento += 1) {
    let respuesta: string;
    try {
      respuesta = await invocar(correccion);
    } catch (error) {
      if (error instanceof ErrorLlm) throw error;
      const mensaje = error instanceof Error ? error.message : String(error);
      // Los errores de red si se reintentan.
      ultimoError = mensaje;
      correccion = `La llamada anterior fallo: ${mensaje}. Responde solo con el JSON pedido.`;
      continue;
    }

    try {
      const crudo = extraerJson(respuesta);
      const resultado = esquema.safeParse(crudo);
      if (resultado.success) return resultado.data;

      const problemas = resultado.error.errors
        .slice(0, 8)
        .map((problema) => `${problema.path.join('.') || 'raiz'}: ${problema.message}`)
        .join('; ');
      ultimoError = problemas;
      correccion = `El JSON anterior no cumplio el esquema. Errores: ${problemas}. Devuelve unicamente el JSON corregido, sin texto adicional.`;
    } catch (error) {
      ultimoError = error instanceof Error ? error.message : String(error);
      correccion = `${ultimoError} Devuelve unicamente JSON valido, sin bloques de codigo ni comentarios.`;
    }
  }

  throw new ErrorLlm(
    'JSON_INVALIDO',
    `El modelo no devolvio un JSON valido tras ${maxReintentos + 1} intentos. Ultimo error: ${ultimoError}`,
  );
}

import { ETIQUETA_TIPO_PREGUNTA, type TipoPregunta } from '@/lib/dominio/constantes';
import type { PeticionGeneracionLlm, PeticionImportacionLlm } from '@/lib/llm/tipos';

const ESQUEMA_JSON_GENERACION = `{
  "preguntas": [
    {
      "enunciado": "texto de la pregunta",
      "tipo": "MCQ_SINGLE | MCQ_MULTI | TRUE_FALSE | SHORT_ANSWER",
      "opciones": [{ "texto": "texto de la opcion", "correcta": true }],
      "explicacion": "justificacion breve de la respuesta correcta",
      "tema": "tema o subtema",
      "pagina": 3,
      "dificultad": "EASY | MEDIUM | HARD",
      "requiereRevision": false
    }
  ]
}`;

const REGLAS_COMUNES = [
  'Responde UNICAMENTE con un objeto JSON valido, sin texto adicional ni bloques de codigo.',
  'Todas las preguntas deben poder responderse usando exclusivamente la informacion del material entregado.',
  'No inventes datos que no aparezcan en el material.',
  'Para MCQ_SINGLE marca exactamente una opcion con "correcta": true y entre 3 y 5 opciones.',
  'Para MCQ_MULTI marca al menos dos opciones con "correcta": true.',
  'Para TRUE_FALSE usa exactamente dos opciones con texto "Verdadero" y "Falso".',
  'Para SHORT_ANSWER incluye una unica opcion con la respuesta esperada.',
  'Los distractores deben ser plausibles, del mismo tipo y longitud que la respuesta correcta.',
  'Indica en "pagina" el numero de pagina del material donde aparece la informacion.',
].join('\n- ');

export function promptSistemaGeneracion(): string {
  return [
    'Eres un docente experto que redacta preguntas de evaluacion de alta calidad en espanol.',
    'Debes devolver JSON estricto que cumpla exactamente este esquema:',
    ESQUEMA_JSON_GENERACION,
    'Reglas:',
    `- ${REGLAS_COMUNES}`,
  ].join('\n');
}

export function promptUsuarioGeneracion(peticion: PeticionGeneracionLlm): string {
  const tipos = peticion.tipos.map((tipo) => `${tipo} (${ETIQUETA_TIPO_PREGUNTA[tipo]})`).join(', ');
  const evitar = peticion.evitar.slice(0, 20);
  return [
    `Idioma de las preguntas: ${peticion.idioma}.`,
    `Numero de preguntas a generar: exactamente ${peticion.cantidad}.`,
    `Tipos permitidos: ${tipos}. Distribuyelos de forma equilibrada.`,
    `Dificultad: ${peticion.dificultad}.`,
    peticion.instruccionesExtra ? `Instrucciones adicionales del docente: ${peticion.instruccionesExtra}` : '',
    `El material proviene de las paginas ${peticion.paginaInicio} a ${peticion.paginaFin}.`,
    evitar.length
      ? `No repitas ni reformules estas preguntas ya existentes:\n- ${evitar.join('\n- ')}`
      : '',
    '',
    'MATERIAL DE ESTUDIO:',
    '"""',
    peticion.texto,
    '"""',
  ]
    .filter(Boolean)
    .join('\n');
}

export function promptSistemaImportacion(): string {
  return [
    'Eres un asistente que digitaliza examenes y bancos de preguntas ya existentes.',
    'Recibiras el texto extraido de un PDF con preguntas de evaluacion.',
    'Debes devolver JSON estricto con este esquema:',
    ESQUEMA_JSON_GENERACION,
    'Reglas:',
    '- Responde UNICAMENTE con el objeto JSON, sin explicaciones ni bloques de codigo.',
    '- Extrae TODAS las preguntas detectadas en el texto, respetando su orden de aparicion.',
    '- Conserva literalmente el enunciado y el texto de cada opcion.',
    '- Si el documento marca la respuesta correcta (negrita, subrayado, asterisco, "(x)", una hoja de respuestas al final), marca esa opcion con "correcta": true y las demas con false.',
    '- Si NO es posible determinar la respuesta correcta, pon "correcta": null en todas las opciones y "requiereRevision": true.',
    '- Nunca inventes opciones que no aparezcan en el documento.',
    '- Si una pregunta es de verdadero/falso usa texto "Verdadero" y "Falso".',
  ].join('\n');
}

export function promptUsuarioImportacion(peticion: PeticionImportacionLlm): string {
  return [
    `Idioma del documento: ${peticion.idioma}.`,
    `Las paginas ${peticion.paginaInicio} a ${peticion.paginaFin} del PDF contienen el texto a procesar.`,
    'Extrae las preguntas, sus opciones y las respuestas correctas que puedas determinar.',
    '',
    'TEXTO DEL PDF:',
    '"""',
    peticion.texto,
    '"""',
  ].join('\n');
}

export function descripcionTipos(tipos: TipoPregunta[]): string {
  return tipos.map((tipo) => ETIQUETA_TIPO_PREGUNTA[tipo]).join(', ');
}

import { env } from '@/lib/env';
import { ErrorLlm, loteLlmSchema, type LLMProvider, type LoteLlm, type PeticionGeneracionLlm, type PeticionImportacionLlm } from '@/lib/llm/tipos';
import { generarJsonValidado } from '@/lib/llm/http-json';
import { promptSistemaGeneracion, promptSistemaImportacion, promptUsuarioGeneracion, promptUsuarioImportacion } from '@/lib/llm/prompts';

/** Proveedor Anthropic (Claude) usando la API HTTP de mensajes. */

const ENDPOINT = 'https://api.anthropic.com/v1/messages';
const VERSION_API = '2023-06-01';

async function invocar(sistema: string, usuario: string, maxTokens: number, correccion?: string): Promise<string> {
  const clave = env.llm.anthropicApiKey;
  if (!clave) {
    throw new ErrorLlm(
      'SIN_CREDENCIALES',
      'Falta ANTHROPIC_API_KEY. Configura la clave en el archivo .env o usa LLM_PROVIDER=mock.',
    );
  }

  const controlador = new AbortController();
  const temporizador = setTimeout(() => controlador.abort(), env.llm.timeoutMs);

  try {
    const respuesta = await fetch(ENDPOINT, {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        'x-api-key': clave,
        'anthropic-version': VERSION_API,
      },
      body: JSON.stringify({
        model: env.llm.anthropicModelo,
        max_tokens: Math.min(maxTokens, env.llm.maxTokens),
        temperature: 0.2,
        system: sistema,
        messages: [
          {
            role: 'user',
            content: correccion ? `${usuario}\n\nCORRECCION: ${correccion}` : usuario,
          },
        ],
      }),
      signal: controlador.signal,
    });

    if (!respuesta.ok) {
      const detalle = await respuesta.text();
      throw new ErrorLlm(
        'ERROR_PROVEEDOR',
        `Anthropic respondio ${respuesta.status}: ${detalle.slice(0, 400)}`,
      );
    }

    const datos = (await respuesta.json()) as { content?: { type: string; text?: string }[] };
    const texto = (datos.content ?? [])
      .filter((bloque) => bloque.type === 'text')
      .map((bloque) => bloque.text ?? '')
      .join('\n')
      .trim();

    if (!texto) throw new ErrorLlm('RESPUESTA_VACIA', 'Anthropic devolvio una respuesta vacia.');
    return texto;
  } catch (error) {
    if (error instanceof ErrorLlm) throw error;
    if (error instanceof Error && error.name === 'AbortError') {
      throw new ErrorLlm('TIEMPO_AGOTADO', 'La llamada al proveedor de IA supero el tiempo limite.');
    }
    throw new ErrorLlm('ERROR_RED', `No se pudo contactar al proveedor de IA: ${(error as Error).message}`);
  } finally {
    clearTimeout(temporizador);
  }
}

export const proveedorAnthropic: LLMProvider = {
  nombre: 'anthropic',
  modelo: env.llm.anthropicModelo,

  async generarPreguntas(peticion: PeticionGeneracionLlm): Promise<LoteLlm> {
    return generarJsonValidado<LoteLlm>({
      esquema: loteLlmSchema,
      maxReintentos: 2,
      invocar: (correccion) =>
        invocar(promptSistemaGeneracion(), promptUsuarioGeneracion(peticion), 6000, correccion),
    });
  },

  async importarPreguntas(peticion: PeticionImportacionLlm): Promise<LoteLlm> {
    return generarJsonValidado<LoteLlm>({
      esquema: loteLlmSchema,
      maxReintentos: 2,
      invocar: (correccion) =>
        invocar(promptSistemaImportacion(), promptUsuarioImportacion(peticion), 8000, correccion),
    });
  },
};

import { env } from '@/lib/env';
import { ErrorLlm, loteLlmSchema, type LLMProvider, type LoteLlm, type PeticionGeneracionLlm, type PeticionImportacionLlm } from '@/lib/llm/tipos';
import { generarJsonValidado } from '@/lib/llm/http-json';
import { promptSistemaGeneracion, promptSistemaImportacion, promptUsuarioGeneracion, promptUsuarioImportacion } from '@/lib/llm/prompts';

/** Proveedor OpenAI (Chat Completions) usando fetch. */

async function invocar(sistema: string, usuario: string, maxTokens: number, correccion?: string): Promise<string> {
  const clave = env.llm.openaiApiKey;
  if (!clave) {
    throw new ErrorLlm(
      'SIN_CREDENCIALES',
      'Falta OPENAI_API_KEY. Configura la clave en el archivo .env o usa LLM_PROVIDER=mock.',
    );
  }

  const controlador = new AbortController();
  const temporizador = setTimeout(() => controlador.abort(), env.llm.timeoutMs);

  try {
    const respuesta = await fetch(`${env.llm.openaiBaseUrl.replace(/\/$/, '')}/chat/completions`, {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        authorization: `Bearer ${clave}`,
      },
      body: JSON.stringify({
        model: env.llm.openaiModelo,
        max_tokens: Math.min(maxTokens, env.llm.maxTokens),
        temperature: 0.2,
        response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: sistema },
          { role: 'user', content: correccion ? `${usuario}\n\nCORRECCION: ${correccion}` : usuario },
        ],
      }),
      signal: controlador.signal,
    });

    if (!respuesta.ok) {
      const detalle = await respuesta.text();
      throw new ErrorLlm(
        'ERROR_PROVEEDOR',
        `OpenAI respondio ${respuesta.status}: ${detalle.slice(0, 400)}`,
      );
    }

    const datos = (await respuesta.json()) as {
      choices?: { message?: { content?: string } }[];
    };
    const texto = (datos.choices?.[0]?.message?.content ?? '').trim();
    if (!texto) throw new ErrorLlm('RESPUESTA_VACIA', 'OpenAI devolvio una respuesta vacia.');
    return texto;
  } catch (error) {
    if (error instanceof ErrorLlm) throw error;
    if (error instanceof Error && error.name === 'AbortError') {
      throw new ErrorLlm('TIEMPO_AGOTADO', 'La llamada al proveedor de IA supero el tiempo limite.');
    }
    throw new ErrorLlm('ERROR_RED', `No se pudo contactar al proveedor de IA: ${(error as Error).message}`);
  } finally {
    clearTimeout(temporizador);
  }
}

