import type { Dificultad, TipoPregunta } from '@/lib/dominio/constantes';
import type {
  LLMProvider,
  LoteLlm,
  PeticionGeneracionLlm,
  PeticionImportacionLlm,
} from '@/lib/llm/tipos';

/**
 * Proveedor "mock": genera preguntas de forma local, sin salir a internet.
 *
 * Sirve para dos cosas:
 *  1. Desarrollo y demostracion sin coste ni claves de API.
 *  2. Pruebas automatizadas y e2e, ya que es 100 % determinista.
 *
 * No pretende ser un buen generador pedagogico, pero si respeta el contrato
 * de la interfaz LLMProvider (mismo JSON, mismas reglas).
 */

const PALABRAS_VACIAS = new Set([
  'para', 'como', 'porque', 'desde', 'hasta', 'entre', 'sobre', 'tambien', 'puede',
  'tienen', 'tiene', 'estos', 'estas', 'aquel', 'aquella', 'cuando', 'donde', 'mientras',
  'aunque', 'segun', 'tras', 'hacia', 'mediante', 'través', 'traves', 'cada', 'todos',
  'todas', 'otros', 'otras', 'mismo', 'misma', 'sera', 'seran', 'fueron', 'habia',
]);

function oraciones(texto: string): string[] {
  return texto
    .replace(/\s+/g, ' ')
    .split(/(?<=[.!?])\s+(?=[A-ZÁÉÍÓÚÑ¿¡])/)
    .map((oracion) => oracion.trim())
    .filter((oracion) => oracion.split(' ').length >= 6 && oracion.length >= 40 && oracion.length <= 320);
}

function vocabulario(texto: string): string[] {
  const palabras = texto
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .match(/[a-z]{6,}/g);
  if (!palabras) return [];
  const unicas = Array.from(new Set(palabras.filter((p) => !PALABRAS_VACIAS.has(p))));
  return unicas.sort((a, b) => b.length - a.length);
}

function palabraClave(oracion: string, vocabularioTexto: string[]): string {
  const normalizar = (valor: string) =>
    valor.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const palabras = oracion.split(/\s+/).map((palabra) => palabra.replace(/[^\p{L}\p{N}-]/gu, ''));
  const candidatas = palabras.filter((palabra) => normalizar(palabra).length >= 5);
  const ordenadas = candidatas.sort((a, b) => b.length - a.length);
  const enVocabulario = ordenadas.find((palabra) =>
    vocabularioTexto.includes(normalizar(palabra)),
  );
  return enVocabulario ?? ordenadas[0] ?? palabras[0] ?? 'concepto';
}

function alterarOracion(oracion: string, vocabularioTexto: string[], semilla: number): string {
  const clave = palabraClave(oracion, vocabularioTexto);
  const sustitutos = vocabularioTexto.filter(
    (palabra) => palabra !== clave.toLowerCase() && palabra.length >= clave.length - 2,
  );
  const sustituto = sustitutos[(semilla * 7) % Math.max(sustitutos.length, 1)] ?? 'elemento';
  return oracion.replace(new RegExp(clave, 'i'), sustituto);
}

function paginaPara(indice: number, total: number, inicio: number, fin: number): number {
  if (fin <= inicio) return inicio;
  const proporcion = total <= 1 ? 0 : indice / (total - 1);
  return Math.min(fin, Math.max(inicio, inicio + Math.round(proporcion * (fin - inicio))));
}

function generar(peticion: PeticionGeneracionLlm): LoteLlm {
  const frases = oraciones(peticion.texto);
  const vocabularioTexto = vocabulario(peticion.texto);
  const tipos: TipoPregunta[] = peticion.tipos.length
    ? peticion.tipos
    : ['MCQ_SINGLE', 'TRUE_FALSE', 'MCQ_MULTI', 'SHORT_ANSWER'];

  if (frases.length === 0 || vocabularioTexto.length < 3) {
    return { preguntas: [] };
  }

  const cantidad = Math.max(1, Math.min(peticion.cantidad, 20));
  const preguntas: LoteLlm['preguntas'] = [];

  for (let i = 0; i < cantidad; i += 1) {
    const frase = frases[i % frases.length]!;
    const tipo = tipos[i % tipos.length]!;
    const pagina = paginaPara(i, cantidad, peticion.paginaInicio, peticion.paginaFin);
    const dificultad: Dificultad = peticion.dificultad;
    const clave = palabraClave(frase, vocabularioTexto);

    if (tipo === 'TRUE_FALSE') {
      const esFalsa = i % 3 === 2;
      const enunciado = esFalsa ? alterarOracion(frase, vocabularioTexto, i) : frase;
      preguntas.push({
        enunciado: `Segun el material, ¿es correcto afirmar que ${enunciado.replace(/\.$/, '')}?`,
        tipo: 'TRUE_FALSE',
        opciones: [
          { texto: 'Verdadero', correcta: !esFalsa },
          { texto: 'Falso', correcta: esFalsa },
        ],
        explicacion: `La afirmacion ${esFalsa ? 'fue alterada respecto' : 'aparece tal cual en'} al material de estudio.`,
        tema: 'Material de estudio',
        pagina,
        dificultad,
      });
      continue;
    }

    if (tipo === 'MCQ_MULTI') {
      const otra = frases[(i + 1) % frases.length]!;
      const distractores = [
        alterarOracion(frase, vocabularioTexto, i + 3),
        alterarOracion(otra, vocabularioTexto, i + 5),
      ];
      preguntas.push({
        enunciado: '¿Cuales de las siguientes afirmaciones aparecen en el material de estudio?',
        tipo: 'MCQ_MULTI',
        opciones: [
          { texto: frase, correcta: true },
          { texto: otra === frase ? `${otra} (variante)` : otra, correcta: otra !== frase },
          { texto: distractores[0]!, correcta: false },
          { texto: distractores[1]!, correcta: false },
        ],
        explicacion: 'Selecciona unicamente los enunciados presentes de forma literal en el material.',
        tema: 'Material de estudio',
        pagina,
        dificultad,
      });
      continue;
    }

    if (tipo === 'SHORT_ANSWER') {
      preguntas.push({
        enunciado: `Completa con la palabra que falta: ${frase.replace(
          new RegExp(clave, 'i'),
          '______',
        )}`,
        tipo: 'SHORT_ANSWER',
        opciones: [{ texto: clave.toLowerCase(), correcta: true }],
        explicacion: `La palabra solicitada es "${clave.toLowerCase()}".`,
        tema: 'Material de estudio',
        pagina,
        dificultad,
      });
      continue;
    }

    // MCQ_SINGLE (por defecto)
    const distractores = vocabularioTexto
      .filter((palabra) => palabra !== clave.toLowerCase())
      .slice(i % 5, (i % 5) + 3);
    const opciones = [
      { texto: clave.toLowerCase(), correcta: true },
      ...distractores.map((palabra) => ({ texto: palabra, correcta: false })),
    ];
    preguntas.push({
      enunciado: `Completa el enunciado con la opcion correcta: ${frase.replace(
        new RegExp(clave, 'i'),
        '______',
      )}`,
      tipo: 'MCQ_SINGLE',
      opciones,
      explicacion: `Segun el material, la palabra que completa el enunciado es "${clave.toLowerCase()}".`,
      tema: 'Material de estudio',
      pagina,
      dificultad,
    });
  }

  return { preguntas };
}

/* ------------------------------------------------------------------ *
 * Importacion de examenes existentes
 * ------------------------------------------------------------------ */

const RE_PREGUNTA = /^\s*(?:(\d{1,3})\s*[.)\-:]|[-*•])\s*(.+)$/;
const RE_OPCION = /^\s*(?:\()?([a-hA-H]|[ivxIVX]{1,4})\s*[.)\-:]\s*(.+)$/;
const RE_ENUNCIADO_CON_PREGUNTA = /^\s*(?:\d{1,3}\s*[.)])?\s*[¿]?.*\?$/;

function limpiar(texto: string): string {
  return texto.replace(/\s+/g, ' ').trim();
}

function marcarCorrecta(texto: string): { texto: string; marcada: boolean } {
  const patrones = [/\(\s*x\s*\)/i, /\*\s*$/, /✔/, /✓/, /\[correcta\]/i, /__+/];
  let marcada = false;
  let resultado = texto;
  for (const patron of patrones) {
    if (patron.test(resultado)) {
      marcada = true;
      resultado = resultado.replace(patron, ' ');
    }
  }
  return { texto: limpiar(resultado), marcada };
}

function detectarClaveDeRespuestas(texto: string): Map<number, string> {
  const claves = new Map<number, string>();
  const lineas = texto.split('\n');
  for (const linea of lineas) {
    if (!/respuestas?|clave|answers?|solucion/i.test(linea)) continue;
    const pares = linea.matchAll(/(\d{1,3})\s*[).:\-]?\s*([a-hA-H])\b/g);
    for (const par of pares) {
      claves.set(Number(par[1]), par[2]!.toLowerCase());
    }
  }
  return claves;
}

function importar(peticion: PeticionImportacionLlm): LoteLlm {
  const claves = detectarClaveDeRespuestas(peticion.texto);
  const lineas = peticion.texto.split('\n');

  type Bloque = { enunciado: string; opciones: { texto: string; correcta: boolean | null }[] };
  const bloques: Bloque[] = [];
  let actual: Bloque | null = null;
  let numero = 0;

  for (const linea of lineas) {
    const limpia = linea.trim();
    if (limpia === '') continue;

    const comoOpcion = RE_OPCION.exec(linea);
    if (actual && comoOpcion && comoOpcion[2]) {
      const { texto, marcada } = marcarCorrecta(comoOpcion[2]);
      if (texto.length > 0) {
        actual.opciones.push({ texto, correcta: marcada ? true : null });
      }
      continue;
    }

    const comoPregunta = RE_PREGUNTA.exec(linea);
    const pareceEnunciado = RE_ENUNCIADO_CON_PREGUNTA.test(linea) && limpia.length > 15;

    if ((comoPregunta && comoPregunta[2] && comoPregunta[2].trim().length > 10) || pareceEnunciado) {
      // Si el bloque anterior no tenia opciones, se guarda igualmente.
      if (actual) bloques.push(actual);
      numero += 1;
      const enunciadoCrudo = comoPregunta?.[2] ?? limpia;
      const { texto } = marcarCorrecta(enunciadoCrudo);
      actual = { enunciado: limpiar(texto), opciones: [] };
      continue;
    }

    if (actual && actual.opciones.length === 0) {
      actual.enunciado = limpiar(`${actual.enunciado} ${limpia}`);
    }
  }
  if (actual) bloques.push(actual);

  const preguntas: LoteLlm['preguntas'] = [];

  for (const bloque of bloques) {
    if (bloque.enunciado.length < 15) continue;
    if (bloque.opciones.length < 2) continue;

    const correctasMarcadas = bloque.opciones.filter((o) => o.correcta === true);
    let opciones = bloque.opciones;

    if (correctasMarcadas.length === 0 && claves.size > 0) {
      // Intenta aplicar la hoja de respuestas detectada.
      const posicion = preguntas.length + 1;
      const letraClave = claves.get(posicion) ?? claves.get(numero);
      if (letraClave) {
        const indice = letraClave.charCodeAt(0) - 97;
        opciones = bloque.opciones.map((opcion, i) => ({
          texto: opcion.texto,
          correcta: i === indice ? true : null,
        }));
      }
    }

    const conCorrecta = opciones.filter((o) => o.correcta === true).length > 0;
    const esVerdaderoFalso =
      opciones.length === 2 &&
      opciones.every((o) => /^(verdadero|falso|true|false)$/i.test(o.texto.trim()));

    preguntas.push({
      enunciado: bloque.enunciado,
      tipo: esVerdaderoFalso ? 'TRUE_FALSE' : conCorrecta && opciones.filter((o) => o.correcta).length > 1 ? 'MCQ_MULTI' : 'MCQ_SINGLE',
      opciones: opciones.map((opcion) => ({ texto: opcion.texto, correcta: opcion.correcta })),
      explicacion: '',
      tema: 'Examen importado',
      pagina: peticion.paginaInicio,
      requiereRevision: !conCorrecta,
    });
  }

  return { preguntas };
}

export const proveedorMock: LLMProvider = {
  nombre: 'mock',
  modelo: 'generador-local-determinista',

  async generarPreguntas(peticion: PeticionGeneracionLlm): Promise<LoteLlm> {
    return generar(peticion);
  },

  async importarPreguntas(peticion: PeticionImportacionLlm): Promise<LoteLlm> {
    return importar(peticion);
  },
};

import { env, llmConfigurado } from '@/lib/env';
import { proveedorAnthropic } from '@/lib/llm/anthropic';
import { proveedorOpenai } from '@/lib/llm/openai';
import { proveedorMock } from '@/lib/llm/mock';
import {
  ErrorLlm,
  loteLlmSchema,
  normalizarPreguntas,
  type LLMProvider,
  type PeticionGeneracionLlm,
  type PeticionImportacionLlm,
  type PreguntaNormalizada,
} from '@/lib/llm/tipos';
import type { Dificultad, TipoPregunta } from '@/lib/dominio/constantes';

/** Devuelve el proveedor configurado por variables de entorno. */
export function obtenerProveedor(): LLMProvider {
  if (env.llm.proveedor === 'anthropic') return proveedorAnthropic;
  if (env.llm.proveedor === 'openai') return proveedorOpenai;
  return proveedorMock;
}

export type PeticionGeneracion = {
  texto: string;
  paginaInicio: number;
  paginaFin: number;
  cantidad: number;
  tipos: TipoPregunta[];
  dificultad: Dificultad;
  idioma: string;
  instruccionesExtra?: string;
  evitar?: string[];
};

export type ResultadoGeneracion = {
  preguntas: PreguntaNormalizada[];
  descartadas: { enunciado: string; motivo: string }[];
  proveedor: string;
  modelo: string;
};

/**
 * Genera preguntas a partir de un fragmento de material usando el proveedor
 * configurado. La salida del modelo se valida con Zod antes de usarse.
 */
export async function generarPreguntasDeFragmento(
  peticion: PeticionGeneracion,
): Promise<ResultadoGeneracion> {
  const proveedor = obtenerProveedor();
  if (!llmConfigurado()) {
    throw new ErrorLlm(
      'SIN_CREDENCIALES',
      `El proveedor "${proveedor.nombre}" no tiene credenciales configuradas. Define las claves en .env o usa LLM_PROVIDER=mock.`,
    );
  }

  const peticionLlm: PeticionGeneracionLlm = {
    texto: peticion.texto,
    paginaInicio: peticion.paginaInicio,
    paginaFin: peticion.paginaFin,
    cantidad: peticion.cantidad,
    tipos: peticion.tipos,
    dificultad: peticion.dificultad,
    idioma: peticion.idioma,
    instruccionesExtra: peticion.instruccionesExtra,
    evitar: (peticion.evitar ?? []).slice(0, 25),
  };

  const crudo = await proveedor.generarPreguntas(peticionLlm);
  // Doble validacion: aunque el proveedor valide, se valida de nuevo aqui.
  const lote = loteLlmSchema.parse(crudo);

  const { validas, descartadas } = normalizarPreguntas(
    lote,
    {
      tipoPorDefecto: peticion.tipos[0] ?? 'MCQ_SINGLE',
      dificultadPorDefecto: peticion.dificultad,
      paginaPorDefecto: peticion.paginaInicio,
    },
    false,
  );

  return {
    preguntas: validas,
    descartadas,
    proveedor: proveedor.nombre,
    modelo: proveedor.modelo,
  };
}

/** Importa preguntas de un examen o banco existente. */
export async function importarPreguntasDeFragmento(peticion: {
  texto: string;
  paginaInicio: number;
  paginaFin: number;
  idioma: string;
}): Promise<ResultadoGeneracion> {
  const proveedor = obtenerProveedor();
  const peticionLlm: PeticionImportacionLlm = peticion;
  const crudo = await proveedor.importarPreguntas(peticionLlm);
  const lote = loteLlmSchema.parse(crudo);

  const { validas, descartadas } = normalizarPreguntas(
    lote,
    {
      tipoPorDefecto: 'MCQ_SINGLE',
      dificultadPorDefecto: 'MEDIUM',
      paginaPorDefecto: peticion.paginaInicio,
    },
    true,
  );

  return {
    preguntas: validas,
    descartadas,
    proveedor: proveedor.nombre,
    modelo: proveedor.modelo,
  };
}

/**
 * Deteccion de preguntas duplicadas.
 *
 * Estrategia en dos niveles:
 *  1. Huella exacta (sha1 del enunciado normalizado) -> duplicado exacto.
 *  2. Similitud de Jaccard sobre el conjunto de palabras -> duplicado
 *     aproximado (por ejemplo, la misma pregunta redactada con ligeras
 *     variaciones o repetida en fragmentos con solape).
 */

const UMBRAL_SIMILITUD = 0.82;

export function normalizarEnunciado(texto: string): string {
  return texto
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function palabras(texto: string): Set<string> {
  return new Set(
    normalizarEnunciado(texto)
      .split(' ')
      .filter((palabra) => palabra.length > 2),
  );
}

/** Indice de Jaccard entre dos enunciados (0 a 1). */
export function similitud(a: string, b: string): number {
  const conjuntoA = palabras(a);
  const conjuntoB = palabras(b);
  if (conjuntoA.size === 0 || conjuntoB.size === 0) return 0;
  let interseccion = 0;
  for (const palabra of conjuntoA) {
    if (conjuntoB.has(palabra)) interseccion += 1;
  }
  const union = conjuntoA.size + conjuntoB.size - interseccion;
  return union === 0 ? 0 : interseccion / union;
}

export type PreguntaExistente = { enunciado: string; huella: string | null };

/** Indica si un enunciado ya existe (exacto o muy parecido). */
export function estaDuplicada(
  enunciado: string,
  huella: string,
  existentes: PreguntaExistente[],
  umbral = UMBRAL_SIMILITUD,
): boolean {
  for (const existente of existentes) {
    if (existente.huella && existente.huella === huella) return true;
    if (similitud(enunciado, existente.enunciado) >= umbral) return true;
  }
  return false;
}

import { prisma } from '@/lib/db';
import { huellaTexto } from '@/lib/auth/password';
import { estaDuplicada, type PreguntaExistente } from '@/lib/preguntas/deduplicar';
import type { PreguntaNormalizada } from '@/lib/llm/tipos';

export type ResultadoGuardado = {
  creadas: number;
  omitidas: number;
  pendientes: number;
  ids: string[];
};

/**
 * Guarda en el banco de preguntas las preguntas generadas o importadas.
 * Evita duplicados (exactos y aproximados) tanto dentro del lote como
 * respecto a lo que ya existe para ese documento o autor.
 */
export async function guardarPreguntas(datos: {
  autorId: string;
  documentoId?: string | null;
  preguntas: PreguntaNormalizada[];
  origen: 'GENERATED' | 'IMPORTED' | 'MANUAL';
  llmModel?: string | null;
  umbralSimilitud?: number;
}): Promise<ResultadoGuardado> {
  const { autorId, documentoId, preguntas, origen, llmModel } = datos;

  const existentesDb = await prisma.question.findMany({
    where: documentoId
      ? { OR: [{ documentId: documentoId }, { authorId: autorId }] }
      : { authorId: autorId },
    select: { statement: true, fingerprint: true },
    orderBy: { createdAt: 'desc' },
    take: 1000,
  });

  const existentes: PreguntaExistente[] = existentesDb.map((fila) => ({
    enunciado: fila.statement,
    huella: fila.fingerprint,
  }));

  let creadas = 0;
  let omitidas = 0;
  let pendientes = 0;
  const ids: string[] = [];

  for (const pregunta of preguntas) {
    const huella = huellaTexto(pregunta.enunciado);
    if (estaDuplicada(pregunta.enunciado, huella, existentes, datos.umbralSimilitud)) {
      omitidas += 1;
      continue;
    }

    const creada = await prisma.question.create({
      data: {
        type: pregunta.tipo,
        statement: pregunta.enunciado,
        explanation: pregunta.explicacion || null,
        topic: pregunta.tema || null,
        sourcePage: pregunta.pagina ?? null,
        difficulty: pregunta.dificultad,
        status: pregunta.respuestaPendiente ? 'PENDING_REVIEW' : 'DRAFT',
        points: 1,
        fingerprint: huella,
        origin: origen,
        llmModel: llmModel ?? null,
        answerPending: pregunta.respuestaPendiente,
        authorId: autorId,
        documentId: documentoId ?? null,
        options: {
          create: pregunta.opciones.map((opcion, indice) => ({
            label: opcion.etiqueta || String.fromCharCode(65 + indice),
            text: opcion.texto,
            isCorrect: opcion.correcta,
            position: indice,
          })),
        },
      },
      select: { id: true },
    });

    ids.push(creada.id);
    creadas += 1;
    if (pregunta.respuestaPendiente) pendientes += 1;
    // Añade al conjunto para evitar duplicados dentro del mismo lote.
    existentes.push({ enunciado: pregunta.enunciado, huella });
  }

  return { creadas, omitidas, pendientes, ids };
}

import { z } from 'zod';
import { dificultadSchema, tipoPreguntaSchema } from '@/lib/dominio/constantes';

export const esquemaGenerar = z.object({
  fragmento: z.coerce.number().int().min(0, 'Fragmento invalido.').max(5000),
  cantidad: z.coerce
    .number()
    .int('La cantidad debe ser un numero entero.')
    .min(1, 'Genera al menos una pregunta.')
    .max(20, 'Maximo 20 preguntas por fragmento.'),
  tipos: z.array(tipoPreguntaSchema).min(1, 'Selecciona al menos un tipo de pregunta.').max(4),
  dificultad: dificultadSchema,
  idioma: z.string().trim().min(2, 'Indica el idioma.').max(40).default('espanol'),
  instruccionesExtra: z.string().trim().max(600).optional().or(z.literal('')),
});

export const esquemaImportar = z.object({
  fragmento: z.coerce.number().int().min(0).max(5000),
});

export const esquemaListarDocumentos = z.object({
  buscar: z.string().trim().max(120).optional(),
});

export type DatosGenerar = z.infer<typeof esquemaGenerar>;
export type DatosImportar = z.infer<typeof esquemaImportar>;

import { z } from 'zod';
import { dificultadSchema, tipoPreguntaSchema } from '@/lib/dominio/constantes';

export const opcionEntradaSchema = z.object({
  texto: z.string().trim().min(1, 'La opcion no puede estar vacia.').max(600),
  correcta: z.boolean(),
});

const basePregunta = z.object({
  enunciado: z
    .string()
    .trim()
    .min(8, 'El enunciado debe tener al menos 8 caracteres.')
    .max(2000, 'El enunciado es demasiado largo.'),
  tipo: tipoPreguntaSchema,
  opciones: z.array(opcionEntradaSchema).max(10).default([]),
  explicacion: z.string().trim().max(1200).optional().or(z.literal('')),
  tema: z.string().trim().max(160).optional().or(z.literal('')),
  pagina: z.coerce.number().int().positive().max(100000).optional(),
  dificultad: dificultadSchema.default('MEDIUM'),
  estado: z.enum(['DRAFT', 'PENDING_REVIEW', 'APPROVED']).optional(),
  documentoId: z.string().min(1).nullable().optional(),
});

/** Reglas de coherencia entre tipo de pregunta y opciones. */
function coherente(datos: {
  tipo: string;
  opciones: { texto: string; correcta: boolean }[];
}): string | null {
  const correctas = datos.opciones.filter((o) => o.correcta).length;
  if (datos.tipo === 'SHORT_ANSWER') {
    if (datos.opciones.length > 1) return 'Una respuesta corta admite como maximo una opcion.';
    return null;
  }
  if (datos.tipo === 'TRUE_FALSE') {
    if (datos.opciones.length !== 2) return 'Verdadero/Falso requiere exactamente dos opciones.';
    if (correctas !== 1) return 'Marca exactamente una opcion correcta.';
    return null;
  }
  if (datos.tipo === 'MCQ_SINGLE') {
    if (datos.opciones.length < 2) return 'Necesitas al menos dos opciones.';
    if (correctas !== 1) return 'Marca exactamente una opcion correcta.';
    return null;
  }
  if (datos.tipo === 'MCQ_MULTI') {
    if (datos.opciones.length < 2) return 'Necesitas al menos dos opciones.';
    if (correctas < 1) return 'Marca al menos una opcion correcta.';
    return null;
  }
  return null;
}

export const esquemaCrearPregunta = basePregunta.superRefine((datos, ctx) => {
  const problema = coherente(datos);
  if (problema) ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['opciones'], message: problema });
});

export const esquemaActualizarPregunta = basePregunta
  .partial()
  .superRefine((datos, ctx) => {
    if (datos.tipo && datos.opciones) {
      const problema = coherente({ tipo: datos.tipo, opciones: datos.opciones });
      if (problema) ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['opciones'], message: problema });
    }
  });

export type DatosCrearPregunta = z.infer<typeof esquemaCrearPregunta>;
export type DatosActualizarPregunta = z.infer<typeof esquemaActualizarPregunta>;

