type Ctx = { params: Promise<{ id: string }> };

/**
 * POST /api/documentos/[id]/importar
 * Detecta preguntas de un examen existente en UN fragmento y las estructura.
 * Las que no permitan determinar la respuesta correcta quedan en estado
 * "pendiente de revision".
 */
export const POST = ruta<Ctx['params']>(async (req, ctx) => {
  const sesion = await requiereRolApi('ADMIN', 'TEACHER');
  verificarCsrf(req, sesion);
  const { ip } = infoCliente(req);
