  const documento = await obtenerDocumentoVisible(id, sesion.usuario);
  const datos = await leerCuerpo(req, esquemaImportar);

  const fragmentos = fragmentarPaginas(paginasDeDocumento(documento));
  const fragmento = fragmentos[datos.fragmento];
  if (!fragmento) {
    throw solicitudInvalida(`El fragmento ${datos.fragmento} no existe (total: ${fragmentos.length}).`);
  }

  let resultado;
  try {
    resultado = await importarPreguntasDeFragmento({
      texto: fragmento.texto,
      paginaInicio: fragmento.paginaInicio,
      paginaFin: fragmento.paginaFin,
      idioma: 'espanol',
    });
  } catch (error) {
    if (error instanceof ErrorLlm) {
      throw solicitudInvalida(`Error del proveedor de IA: ${error.message}`);
    }
    throw error;
  }

  const guardado = await guardarPreguntas({
    autorId: sesion.usuario.id,
