    actorId: sesion.usuario.id,
    tipoEntidad: 'Document',
    entidadId: id,
    meta: {
      fragmento: datos.fragmento,
      detectadas: resultado.preguntas.length,
      creadas: guardado.creadas,
      omitidas: guardado.omitidas,
      pendientes: guardado.pendientes,
    },
    ip,
  });

  return respuestaOk({
    fragmento: datos.fragmento,
    detectadas: resultado.preguntas.length,
    creadas: guardado.creadas,
    omitidas: guardado.omitidas,
    pendientes: guardado.pendientes,
    descartadas: resultado.descartadas,
  });
});

import { prisma } from '@/lib/db';
import { ruta, leerCuerpo, respuestaOk, infoCliente, solicitudInvalida } from '@/lib/http';
import { requiereRolApi, verificarCsrf } from '@/lib/auth/guard';
import { huellaTexto } from '@/lib/auth/password';
import { esquemaCrearPregunta } from '@/lib/esquemas/preguntas';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

/** GET /api/preguntas?documentoId=&tipo=&estado=&buscar=&limite= */
export const GET = ruta(async (req) => {
  const sesion = await requiereRolApi('ADMIN', 'TEACHER');
  const url = new URL(req.url);
  const documentoId = url.searchParams.get('documentoId');
  const tipo = url.searchParams.get('tipo');
  const estado = url.searchParams.get('estado');
  const buscar = url.searchParams.get('buscar')?.trim();
  const limite = Math.min(Number(url.searchParams.get('limite') ?? 200) || 200, 500);

  const preguntas = await prisma.question.findMany({
    where: {
      ...(sesion.usuario.role === 'ADMIN' ? {} : { authorId: sesion.usuario.id }),
      ...(documentoId ? { documentId: documentoId } : {}),
      ...(tipo ? { type: tipo } : {}),
      ...(estado ? { status: estado } : {}),
      ...(buscar ? { statement: { contains: buscar } } : {}),
    },
    orderBy: [{ createdAt: 'desc' }],
    take: limite,
    include: {
      options: { orderBy: { position: 'asc' } },
      document: { select: { id: true, title: true } },
      _count: { select: { quizzes: true } },
    },
  });

  return respuestaOk({
    preguntas: preguntas.map((pregunta) => ({
      id: pregunta.id,
      tipo: pregunta.type,
      enunciado: pregunta.statement,
      explicacion: pregunta.explanation,
      tema: pregunta.topic,
      pagina: pregunta.sourcePage,
      dificultad: pregunta.difficulty,
      estado: pregunta.status,
      origen: pregunta.origin,
      puntos: pregunta.points,
      respuestaPendiente: pregunta.answerPending,
      creadaEn: pregunta.createdAt,
      documento: pregunta.document,
      usadaEnQuices: pregunta._count.quizzes,
      opciones: pregunta.options.map((opcion) => ({
        id: opcion.id,
        etiqueta: opcion.label,
        texto: opcion.text,
        correcta: opcion.isCorrect,
      })),
    })),
  });
});

/** POST /api/preguntas - crea una pregunta manual. */
export const POST = ruta(async (req) => {
  const sesion = await requiereRolApi('ADMIN', 'TEACHER');
  verificarCsrf(req, sesion);
  const { ip } = infoCliente(req);
  const datos = await leerCuerpo(req, esquemaCrearPregunta);

  if (datos.documentoId) {
    const documento = await prisma.document.findUnique({
      where: { id: datos.documentoId },
      select: { uploadedById: true },
    });
    if (!documento) throw solicitudInvalida('El documento indicado no existe.');
    if (sesion.usuario.role !== 'ADMIN' && documento.uploadedById !== sesion.usuario.id) {
      throw solicitudInvalida('No puedes asociar preguntas a un documento de otro docente.');
    }
  }

  const creada = await prisma.question.create({
    data: {
      type: datos.tipo,
      statement: datos.enunciado,
      explanation: datos.explicacion || null,
      topic: datos.tema || null,
      sourcePage: datos.pagina ?? null,
      difficulty: datos.dificultad,
      status: datos.estado ?? 'DRAFT',
      points: 1,
      fingerprint: huellaTexto(datos.enunciado),
      origin: 'MANUAL',
      answerPending: false,
      authorId: sesion.usuario.id,
      documentId: datos.documentoId ?? null,
      options: {
        create: datos.opciones.map((opcion, indice) => ({
          label: String.fromCharCode(65 + indice),
          text: opcion.texto,
          isCorrect: opcion.correcta,
          position: indice,
        })),
      },
    },
    select: { id: true },
  });

  return respuestaOk({ id: creada.id }, 201);
});

import { prisma } from '@/lib/db';
import { ruta, leerCuerpo, respuestaOk, infoCliente, noEncontrado, sinPermiso } from '@/lib/http';
import { requiereRolApi, verificarCsrf } from '@/lib/auth/guard';
import { auditar } from '@/lib/audit';
import { huellaTexto } from '@/lib/auth/password';
import { esquemaActualizarPregunta } from '@/lib/esquemas/preguntas';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

type Ctx = { params: Promise<{ id: string }> };

async function obtenerPreguntaAutorizada(id: string, usuarioId: string, esAdmin: boolean) {
  const pregunta = await prisma.question.findUnique({ where: { id } });
  if (!pregunta) throw noEncontrado('Pregunta');
  if (!esAdmin && pregunta.authorId !== usuarioId) throw sinPermiso();
  return pregunta;
}

/** PATCH /api/preguntas/[id] */
export const PATCH = ruta<Ctx['params']>(async (req, ctx) => {
  const sesion = await requiereRolApi('ADMIN', 'TEACHER');
  verificarCsrf(req, sesion);
  const { ip } = infoCliente(req);
  const { id } = await ctx.params;

  const pregunta = await obtenerPreguntaAutorizada(id, sesion.usuario.id, sesion.usuario.role === 'ADMIN');
  const datos = await leerCuerpo(req, esquemaActualizarPregunta);

  await prisma.$transaction(async (tx) => {
    await tx.question.update({
      where: { id },
      data: {
        ...(datos.enunciado !== undefined
          ? { statement: datos.enunciado, fingerprint: huellaTexto(datos.enunciado) }
          : {}),
        ...(datos.tipo !== undefined ? { type: datos.tipo } : {}),
        ...(datos.explicacion !== undefined ? { explanation: datos.explicacion || null } : {}),
        ...(datos.tema !== undefined ? { topic: datos.tema || null } : {}),
        ...(datos.pagina !== undefined ? { sourcePage: datos.pagina } : {}),
        ...(datos.dificultad !== undefined ? { difficulty: datos.dificultad } : {}),
        ...(datos.estado !== undefined ? { status: datos.estado } : {}),
        ...(datos.documentoId !== undefined ? { documentId: datos.documentoId } : {}),
        // Al editar la respuesta se considera revisada.
        ...(datos.opciones !== undefined ? { answerPending: false } : {}),
      },
    });

    if (datos.opciones !== undefined) {
      await tx.questionOption.deleteMany({ where: { questionId: id } });
      if (datos.opciones.length > 0) {
        await tx.questionOption.createMany({
          data: datos.opciones.map((opcion, indice) => ({
            questionId: id,
            label: String.fromCharCode(65 + indice),
            text: opcion.texto,
            isCorrect: opcion.correcta,
            position: indice,
          })),
        });
      }
    }
  });

  await auditar({
    accion: 'PREGUNTA_ACTUALIZADA',
    actorId: sesion.usuario.id,
    tipoEntidad: 'Question',
    entidadId: id,
    meta: { campos: Object.keys(datos), enunciadoPrevio: pregunta.statement.slice(0, 120) },
    ip,
  });

  return respuestaOk({ actualizada: true });
});

/** DELETE /api/preguntas/[id] */
export const DELETE = ruta<Ctx['params']>(async (req, ctx) => {
  const sesion = await requiereRolApi('ADMIN', 'TEACHER');
  verificarCsrf(req, sesion);
  const { ip } = infoCliente(req);
  const { id } = await ctx.params;

  const pregunta = await obtenerPreguntaAutorizada(id, sesion.usuario.id, sesion.usuario.role === 'ADMIN');

  const intentos = await prisma.answer.count({ where: { questionId: id } });
  if (intentos > 0) {
    // Se conserva la pregunta para no invalidar intentos y reportes ya hechos.
    await prisma.$transaction(async (tx) => {
      await tx.quizQuestion.deleteMany({ where: { questionId: id } });
      await tx.question.update({ where: { id }, data: { status: 'DRAFT' } });
    });
    await auditar({
      accion: 'PREGUNTA_ARCHIVADA',
      actorId: sesion.usuario.id,
      tipoEntidad: 'Question',
      entidadId: id,
      meta: { motivo: 'tiene respuestas de estudiantes', intentos },
      ip,
    });
    return respuestaOk({
      eliminada: false,
      archivada: true,
      mensaje:
        'La pregunta ya fue usada en intentos de estudiantes, por eso se retire de los quices pero no se elimino.',
    });
  }

  await prisma.$transaction(async (tx) => {
    await tx.quizQuestion.deleteMany({ where: { questionId: id } });
    await tx.questionOption.deleteMany({ where: { questionId: id } });
    await tx.question.delete({ where: { id } });
  });

  await auditar({
    accion: 'PREGUNTA_ELIMINADA',
    actorId: sesion.usuario.id,
    tipoEntidad: 'Question',
    entidadId: id,
    meta: { enunciado: pregunta.statement.slice(0, 120) },
    ip,
  });

  return respuestaOk({ eliminada: true });
});

import type { PreguntaDto } from '@/lib/cliente/tipos';

type EntradaPregunta = {
  id: string;
  type: string;
  statement: string;
  explanation: string | null;
  topic: string | null;
  sourcePage: number | null;
  difficulty: string;
  status: string;
  origin: string;
  points: number;
  answerPending: boolean;
  createdAt: Date;
  document?: { id: string; title: string } | null;
  options: { id: string; label: string; text: string; isCorrect: boolean }[];
  _count?: { quizzes: number };
};

/** Convierte una pregunta de Prisma al DTO que consume la interfaz. */
export function aPreguntaDto(pregunta: EntradaPregunta): PreguntaDto {
  return {
    id: pregunta.id,
    tipo: pregunta.type,
    enunciado: pregunta.statement,
    explicacion: pregunta.explanation,
    tema: pregunta.topic,
    pagina: pregunta.sourcePage,
    dificultad: pregunta.difficulty,
    estado: pregunta.status,
    origen: pregunta.origin,
    puntos: pregunta.points,
    respuestaPendiente: pregunta.answerPending,
    creadaEn: pregunta.createdAt.toISOString(),
    documento: pregunta.document
      ? { id: pregunta.document.id, titulo: pregunta.document.title }
      : null,
    usadaEnQuices: pregunta._count?.quizzes ?? 0,
    opciones: pregunta.options
      .slice()
      .sort((a, b) => a.label.localeCompare(b.label))
      .map((opcion) => ({
        id: opcion.id,
        etiqueta: opcion.label,
        texto: opcion.text,
        correcta: opcion.isCorrect,
      })),
  };
}

/** Consulta reutilizable con las relaciones necesarias para el DTO. */
export const INCLUDE_PREGUNTA_DTO = {
  options: { orderBy: { position: 'asc' } },
  document: { select: { id: true, title: true } },
  _count: { select: { quizzes: true } },
} as const;

