import { prisma } from '@/lib/db';
import { requiereRol } from '@/lib/auth/guard';
import { env } from '@/lib/env';
import { obtenerAjusteNumero } from '@/lib/settings';
import type { DocumentoDto } from '@/lib/cliente/tipos';
import { SubidorDocumentos } from './SubidorDocumentos';
import { ListaDocumentos } from './ListaDocumentos';

export const dynamic = 'force-dynamic';

export default async function PaginaDocumentos() {
  const { usuario } = await requiereRol('ADMIN', 'TEACHER');
  const maxMb = await obtenerAjusteNumero('archivos.maxMB', env.maxUploadMb);

  const documentos = await prisma.document.findMany({
    where: usuario.role === 'ADMIN' ? {} : { uploadedById: usuario.id },
    orderBy: { createdAt: 'desc' },
    include: {
      uploadedBy: { select: { name: true } },
      _count: { select: { questions: true } },
    },
  });

  const lista: DocumentoDto[] = documentos.map((documento) => ({
    id: documento.id,
    titulo: documento.title,
    nombreArchivo: documento.originalName,
    bytes: documento.sizeBytes,
    paginas: documento.pageCount,
    caracteres: documento.charCount,
    fragmentos: documento.chunkCount,
    estado: documento.status,
    error: documento.errorMessage,
    usoOcr: documento.usedOcr,
    subidoPor: documento.uploadedBy.name,
    preguntas: documento._count.questions,
    creadoEn: documento.createdAt.toISOString(),
  }));

  return (
    <div className="flex flex-col gap-6">
      <div>
        <h1 className="text-2xl font-bold text-slate-900">Documentos</h1>
        <p className="mt-1 text-sm text-slate-600">
          Sube el material de estudio, un examen existente o un banco de preguntas en PDF. El sistema
          extrae el texto y lo divide en fragmentos para generar o importar preguntas.
        </p>
      </div>

      <SubidorDocumentos maxMb={maxMb} />
      <ListaDocumentos documentos={lista} />
    </div>
  );
}

'use client';

import { useState } from 'react';
import { api, ErrorPeticion } from '@/lib/cliente/api';
import {
  Alerta,
  Boton,
  Campo,
  Entrada,
  Insignia,
  Selector,
  Tarjeta,
} from '@/components/ui';
import {
  DIFICULTADES,
  ETIQUETA_DIFICULTAD,
  ETIQUETA_TIPO_PREGUNTA,
  TIPOS_PREGUNTA,
  type Dificultad,
  type TipoPregunta,
} from '@/lib/dominio/constantes';

export type ValoresPregunta = {
  id: string | null;
  enunciado: string;
  tipo: TipoPregunta;
  dificultad: Dificultad;
  tema: string;
  pagina: string;
  explicacion: string;
  estado: 'DRAFT' | 'PENDING_REVIEW' | 'APPROVED';
  documentoId: string | null;
  opciones: { texto: string; correcta: boolean }[];
};

export function valoresVacios(documentoId: string | null = null): ValoresPregunta {
  return {
    id: null,
    enunciado: '',
    tipo: 'MCQ_SINGLE',
    dificultad: 'MEDIUM',
    tema: '',
    pagina: '',
    explicacion: '',
    estado: 'DRAFT',
    documentoId,
    opciones: [
      { texto: '', correcta: true },
      { texto: '', correcta: false },
      { texto: '', correcta: false },
      { texto: '', correcta: false },
    ],
  };
}

export function ajustarOpciones(valores: ValoresPregunta, tipo: TipoPregunta): ValoresPregunta {
  if (tipo === 'TRUE_FALSE') {
    return {
      ...valores,
      tipo,
      opciones: [
        { texto: 'Verdadero', correcta: true },
        { texto: 'Falso', correcta: false },
      ],
    };
  }
  if (tipo === 'SHORT_ANSWER') {
    return {
      ...valores,
      tipo,
      opciones: [valores.opciones[0] ?? { texto: '', correcta: true }].map((opcion) => ({
        texto: opcion.texto,
        correcta: true,
      })),
    };
  }

  const marcadas = valores.opciones.filter((opcion) => opcion.correcta);
  if (tipo === 'MCQ_SINGLE' && marcadas.length > 1) {
    return {
      ...valores,
      tipo,
      opciones: valores.opciones.map((opcion, indice) => ({
        texto: opcion.texto,
        correcta: indice === valores.opciones.findIndex((o) => o.correcta),
      })),
    };
  }

  if (valores.opciones.length >= 2) return { ...valores, tipo };

  return {
    ...valores,
    tipo,
    opciones: [
      ...valores.opciones,
      { texto: '', correcta: false },
      { texto: '', correcta: false },
    ].slice(0, 4),
  };
}

export function EditorPregunta({
  inicial,
  documentos,
  documentoFijo,
  onGuardado,
  onCancelar,
}: {
  inicial: ValoresPregunta;
  documentos: { id: string; titulo: string }[];
  documentoFijo?: string | null;
  onGuardado: () => void | Promise<void>;
  onCancelar: () => void;
}) {
  const [valores, setValores] = useState<ValoresPregunta>(inicial);
  const [errores, setErrores] = useState<Record<string, string>>({});
  const [error, setError] = useState<string | null>(null);
  const [guardando, setGuardando] = useState(false);

  function cambioTipo(tipo: TipoPregunta) {
    setValores((actual) => ajustarOpciones(actual, tipo));
  }

  function cambiarOpcion(indice: number, cambios: Partial<{ texto: string; correcta: boolean }>) {
    setValores((actual) => ({
      ...actual,
      opciones: actual.opciones.map((opcion, i) => {
        if (i !== indice) {
          // En opcion multiple de una sola respuesta, solo una puede estar marcada.
          if (cambios.correcta && actual.tipo === 'MCQ_SINGLE') return { ...opcion, correcta: false };
          if (cambios.correcta && actual.tipo === 'TRUE_FALSE') return { ...opcion, correcta: false };
          return opcion;
        }
        return { ...opcion, ...cambios };
      }),
    }));
  }

  function agregarOpcion() {
    setValores((actual) => ({ ...actual, opciones: [...actual.opciones, { texto: '', correcta: false }] }));
  }

  function quitarOpcion(indice: number) {
    setValores((actual) => ({
      ...actual,
      opciones: actual.opciones.filter((_, i) => i !== indice),
    }));
  }

  async function guardar() {
    setGuardando(true);
    setError(null);
    setErrores({});
    try {
      const cuerpo = {
        enunciado: valores.enunciado,
        tipo: valores.tipo,
        dificultad: valores.dificultad,
        tema: valores.tema,
        explicacion: valores.explicacion,
        ...(valores.pagina ? { pagina: Number(valores.pagina) } : {}),
        estado: valores.estado,
        documentoId: documentoFijo ?? valores.documentoId,
        opciones: valores.opciones
          .filter((opcion) => opcion.texto.trim() !== '')
          .map((opcion) => ({ texto: opcion.texto, correcta: opcion.correcta })),
      };

      if (valores.id) await api.patch(`/api/preguntas/${valores.id}`, cuerpo);
      else await api.post('/api/preguntas', cuerpo);

      await onGuardado();
    } catch (e) {
      if (e instanceof ErrorPeticion) {
        setError(e.message);
        setErrores(e.campos ?? {});
      } else {
        setError('No se pudo guardar la pregunta.');
      }
    } finally {
      setGuardando(false);
    }
  }

  const esVerdaderoFalso = valores.tipo === 'TRUE_FALSE';

  return (
    <Tarjeta
      titulo={valores.id ? 'Editar pregunta' : 'Nueva pregunta'}
      descripcion={
        valores.tipo === 'SHORT_ANSWER'
          ? 'En respuestas cortas, la opcion es la respuesta esperada.'
          : 'Marca con la casilla las opciones correctas.'
      }
      acciones={
        <Boton variante="secundario" tamano="sm" onClick={onCancelar}>
          Cancelar
        </Boton>
      }
    >
      <form
        className="flex flex-col gap-4"
        onSubmit={(evento) => {
          evento.preventDefault();
          void guardar();
        }}
      >
        {error && <Alerta tipo="error">{error}</Alerta>}

        <Campo etiqueta="Enunciado" requerido error={errores.enunciado}>
          <textarea
            className="min-h-[90px] w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"
            value={valores.enunciado}
            onChange={(evento) => setValores({ ...valores, enunciado: evento.target.value })}
            required
            minLength={8}
          />
        </Campo>

        <div className="grid gap-4 md:grid-cols-4">
          <Campo etiqueta="Tipo" requerido error={errores.tipo}>
            <Selector
              value={valores.tipo}
              onChange={(evento) => cambioTipo(evento.target.value as TipoPregunta)}
            >
              {TIPOS_PREGUNTA.map((tipo) => (
                <option key={tipo} value={tipo}>
                  {ETIQUETA_TIPO_PREGUNTA[tipo]}
                </option>
              ))}
            </Selector>
          </Campo>
          <Campo etiqueta="Dificultad">
            <Selector
              value={valores.dificultad}
              onChange={(evento) => setValores({ ...valores, dificultad: evento.target.value as Dificultad })}
            >
              {DIFICULTADES.map((dificultad) => (
                <option key={dificultad} value={dificultad}>
                  {ETIQUETA_DIFICULTAD[dificultad]}
                </option>
              ))}
            </Selector>
          </Campo>
          <Campo etiqueta="Tema" ayuda="Opcional">
            <Entrada value={valores.tema} onChange={(evento) => setValores({ ...valores, tema: evento.target.value })} />
          </Campo>
          <Campo etiqueta="Pagina de origen" ayuda="Opcional">
            <Entrada
              type="number"
              min={1}
              value={valores.pagina}
              onChange={(evento) => setValores({ ...valores, pagina: evento.target.value })}
            />
          </Campo>
        </div>

        <div>
          <p className="mb-2 text-sm font-medium text-slate-700">
            Opciones {esVerdaderoFalso && <Insignia tono="gris">Verdadero / Falso</Insignia>}
          </p>
          <div className="flex flex-col gap-2">
            {valores.opciones.map((opcion, indice) => (
              <div key={indice} className="flex items-center gap-2">
                <label className="flex items-center gap-2">
                  <input
                    type={valores.tipo === 'MCQ_MULTI' ? 'checkbox' : 'radio'}
                    name="opcion-correcta"
                    className="h-4 w-4 border-slate-300 text-brand-600"
                    checked={opcion.correcta}
                    onChange={(evento) => cambiarOpcion(indice, { correcta: evento.target.checked })}
                    aria-label={`Marcar la opcion ${indice + 1} como correcta`}
                  />
                  <span className="w-5 text-sm font-semibold text-slate-500">
                    {String.fromCharCode(65 + indice)}
                  </span>
                </label>
                <Entrada
                  value={opcion.texto}
                  readOnly={esVerdaderoFalso}
                  onChange={(evento) => cambiarOpcion(indice, { texto: evento.target.value })}
                  placeholder={esVerdaderoFalso ? '' : 'Texto de la opcion'}
                />
                {!esVerdaderoFalso && valores.tipo !== 'SHORT_ANSWER' && valores.opciones.length > 2 && (
                  <Boton variante="secundario" tamano="sm" type="button" onClick={() => quitarOpcion(indice)}>
                    Quitar
                  </Boton>
                )}
              </div>
            ))}
          </div>
          {errores.opciones && (
            <p role="alert" className="mt-1 text-xs font-medium text-red-600">
              {errores.opciones}
            </p>
          )}
          {!esVerdaderoFalso && valores.tipo !== 'SHORT_ANSWER' && valores.opciones.length < 8 && (
            <div className="mt-2">
              <Boton variante="secundario" tamano="sm" type="button" onClick={agregarOpcion}>
                + Agregar opcion
              </Boton>
            </div>
          )}
        </div>

        <Campo etiqueta="Explicacion de la respuesta" ayuda="Se muestra al estudiante si el quiz lo permite.">
          <textarea
            className="min-h-[70px] w-full rounded-lg border border-slate-300 px-3 py-2 text-sm"
            value={valores.explicacion}
            onChange={(evento) => setValores({ ...valores, explicacion: evento.target.value })}
          />
        </Campo>

        {!documentoFijo && (
          <Campo etiqueta="Documento de origen" ayuda="Opcional">
            <Selector
              value={valores.documentoId ?? ''}
              onChange={(evento) => setValores({ ...valores, documentoId: evento.target.value || null })}
            >
              <option value="">Sin documento asociado</option>
              {documentos.map((documento) => (
                <option key={documento.id} value={documento.id}>
                  {documento.titulo}
                </option>
              ))}
            </Selector>
          </Campo>
        )}

        <Campo etiqueta="Estado" ayuda="Solo las preguntas aprobadas se podran publicar en un quiz.">
          <Selector
            value={valores.estado}
            onChange={(evento) =>
              setValores({ ...valores, estado: evento.target.value as ValoresPregunta['estado'] })
            }
          >
            <option value="DRAFT">Borrador</option>
            <option value="PENDING_REVIEW">Pendiente de revision</option>
            <option value="APPROVED">Aprobada</option>
          </Selector>
        </Campo>

        <div className="flex gap-2">
          <Boton type="submit" disabled={guardando}>
            {guardando ? 'Guardando...' : valores.id ? 'Guardar cambios' : 'Crear pregunta'}
          </Boton>
          <Boton type="button" variante="secundario" onClick={onCancelar}>
            Cancelar
          </Boton>
        </div>
      </form>
    </Tarjeta>
  );
}

export function preguntaAValores(pregunta: {
  id: string;
  enunciado: string;
  tipo: string;
  dificultad: string;
  tema: string | null;
  pagina: number | null;
  explicacion: string | null;
  estado: string;
  documento: { id: string } | null;
  opciones: { texto: string; correcta: boolean }[];
}): ValoresPregunta {
  return {
    id: pregunta.id,
    enunciado: pregunta.enunciado,
    tipo: pregunta.tipo as TipoPregunta,
    dificultad: pregunta.dificultad as Dificultad,
    tema: pregunta.tema ?? '',
    pagina: pregunta.pagina ? String(pregunta.pagina) : '',
    explicacion: pregunta.explicacion ?? '',
    estado: pregunta.estado as ValoresPregunta['estado'],
    documentoId: pregunta.documento?.id ?? null,
    opciones: pregunta.opciones.map((opcion) => ({ texto: opcion.texto, correcta: opcion.correcta })),
  };
}

'use client';

import { useMemo, useState } from 'react';
import { api, ErrorPeticion } from '@/lib/cliente/api';
import type { PreguntaDto } from '@/lib/cliente/tipos';
import {
  Alerta,
  Boton,
  Campo,
  Entrada,
  Insignia,
  Selector,
  Tarjeta,
  Vacio,
} from '@/components/ui';
import {
  DIFICULTADES,
  ETIQUETA_DIFICULTAD,
  ETIQUETA_ORIGEN_PREGUNTA,
  ETIQUETA_TIPO_PREGUNTA,
  TIPOS_PREGUNTA,
  type Dificultad,
  type OrigenPregunta,
  type TipoPregunta,
} from '@/lib/dominio/constantes';
import { EditorPregunta, preguntaAValores, valoresVacios, type ValoresPregunta } from './EditorPregunta';

const ETIQUETA_ESTADO_PREGUNTA: Record<string, string> = {
  DRAFT: 'Borrador',
  PENDING_REVIEW: 'Pendiente de revision',
  APPROVED: 'Aprobada',
};

function tonoEstado(estado: string): 'gris' | 'ambar' | 'verde' {
  if (estado === 'APPROVED') return 'verde';
  if (estado === 'PENDING_REVIEW') return 'ambar';
  return 'gris';
}

export function BancoPreguntas({
  iniciales,
  documentos,
  documentoFijo = null,
  titulo = 'Banco de preguntas',
  descripcion,
}: {
  iniciales: PreguntaDto[];
  documentos: { id: string; titulo: string }[];
  documentoFijo?: string | null;
  titulo?: string;
  descripcion?: string;
}) {
  const [preguntas, setPreguntas] = useState(iniciales);
  const [editando, setEditando] = useState<ValoresPregunta | null>(null);
  const [buscar, setBuscar] = useState('');
  const [filtroTipo, setFiltroTipo] = useState<'TODOS' | TipoPregunta>('TODOS');
  const [filtroEstado, setFiltroEstado] = useState<'TODOS' | 'DRAFT' | 'PENDING_REVIEW' | 'APPROVED'>('TODOS');
  const [filtroDificultad, setFiltroDificultad] = useState<'TODAS' | Dificultad>('TODAS');
  const [mensaje, setMensaje] = useState<{ tipo: 'exito' | 'error' | 'aviso'; texto: string } | null>(null);
  const [expandida, setExpandida] = useState<string | null>(null);
  const [ocupada, setOcupada] = useState<string | null>(null);
  const [recargando, setRecargando] = useState(false);

  const filtradas = useMemo(() => {
    const termino = buscar.trim().toLowerCase();
    return preguntas.filter((pregunta) => {
      if (filtroTipo !== 'TODOS' && pregunta.tipo !== filtroTipo) return false;
      if (filtroEstado !== 'TODOS' && pregunta.estado !== filtroEstado) return false;
      if (filtroDificultad !== 'TODAS' && pregunta.dificultad !== filtroDificultad) return false;
      if (termino && !pregunta.enunciado.toLowerCase().includes(termino)) return false;
      return true;
    });
  }, [preguntas, buscar, filtroTipo, filtroEstado, filtroDificultad]);

  const resumen = useMemo(() => {
    const pendientes = preguntas.filter((pregunta) => pregunta.estado === 'PENDING_REVIEW').length;
    const aprobadas = preguntas.filter((pregunta) => pregunta.estado === 'APPROVED').length;
    return { total: preguntas.length, pendientes, aprobadas };
  }, [preguntas]);

  async function recargar() {
    setRecargando(true);
    try {
      const url = documentoFijo ? `/api/preguntas?documentoId=${documentoFijo}` : '/api/preguntas';
      const datos = await api.get<{ preguntas: PreguntaDto[] }>(url);
      setPreguntas(datos.preguntas);
    } catch {
      setMensaje({ tipo: 'error', texto: 'No se pudo recargar el listado de preguntas.' });
    } finally {
      setRecargando(false);
    }
  }

  async function eliminar(pregunta: PreguntaDto) {
    if (!window.confirm('¿Eliminar esta pregunta? Si ya fue usada en un quiz, se retirara pero se conservara.')) {
      return;
    }
    setOcupada(pregunta.id);
    setMensaje(null);
    try {
      const resultado = await api.del<{ eliminada: boolean; archivada?: boolean; mensaje?: string }>(
        `/api/preguntas/${pregunta.id}`,
      );
      setMensaje({
        tipo: resultado.archivada ? 'aviso' : 'exito',
        texto: resultado.archivada
          ? resultado.mensaje ?? 'La pregunta fue retirada de los quices pero se conserva.'
          : 'Pregunta eliminada.',
      });
      await recargar();
    } catch (error) {
      setMensaje({
        tipo: 'error',
        texto: error instanceof ErrorPeticion ? error.message : 'No se pudo eliminar la pregunta.',
      });
    } finally {
      setOcupada(null);
    }
  }

  async function cambiarEstado(pregunta: PreguntaDto, estado: 'DRAFT' | 'PENDING_REVIEW' | 'APPROVED') {
    setOcupada(pregunta.id);
    setMensaje(null);
    try {
      await api.patch(`/api/preguntas/${pregunta.id}`, { estado });
      await recargar();
    } catch (error) {
      setMensaje({
        tipo: 'error',
        texto: error instanceof ErrorPeticion ? error.message : 'No se pudo cambiar el estado.',
      });
    } finally {
      setOcupada(null);
    }
  }

  return (
    <div className="flex flex-col gap-4">
      {mensaje && <Alerta tipo={mensaje.tipo}>{mensaje.texto}</Alerta>}

      {editando ? (
        <EditorPregunta
          inicial={editando}
          documentos={documentos}
          documentoFijo={documentoFijo}
          onCancelar={() => setEditando(null)}
          onGuardado={async () => {
            setEditando(null);
            setMensaje({ tipo: 'exito', texto: 'Pregunta guardada correctamente.' });
            await recargar();
          }}
        />
      ) : (
        <Tarjeta
          titulo={titulo}
          descripcion={descripcion ?? `${resumen.total} pregunta(s) · ${resumen.aprobadas} aprobada(s) · ${resumen.pendientes} pendiente(s) de revision`}
          acciones={
            <div className="flex gap-2">
              <Boton variante="secundario" tamano="sm" onClick={() => void recargar()} disabled={recargando}>
                {recargando ? 'Recargando...' : 'Recargar'}
              </Boton>
              <Boton onClick={() => setEditando(valoresVacios(documentoFijo))}>+ Nueva pregunta</Boton>
            </div>
          }
        >
          <div className="mb-4 grid gap-3 md:grid-cols-4">
            <Campo etiqueta="Buscar en el enunciado">
              <Entrada
                type="search"
                value={buscar}
                onChange={(evento) => setBuscar(evento.target.value)}
                placeholder="Texto a buscar"
              />
            </Campo>
            <Campo etiqueta="Tipo">
              <Selector value={filtroTipo} onChange={(evento) => setFiltroTipo(evento.target.value as typeof filtroTipo)}>
                <option value="TODOS">Todos</option>
                {TIPOS_PREGUNTA.map((tipo) => (
                  <option key={tipo} value={tipo}>
                    {ETIQUETA_TIPO_PREGUNTA[tipo]}
                  </option>
                ))}
              </Selector>
            </Campo>
            <Campo etiqueta="Estado">
              <Selector
                value={filtroEstado}
                onChange={(evento) => setFiltroEstado(evento.target.value as typeof filtroEstado)}
              >
                <option value="TODOS">Todos</option>
                <option value="DRAFT">Borrador</option>
                <option value="PENDING_REVIEW">Pendiente de revision</option>
                <option value="APPROVED">Aprobada</option>
              </Selector>
            </Campo>
            <Campo etiqueta="Dificultad">
              <Selector
                value={filtroDificultad}
                onChange={(evento) => setFiltroDificultad(evento.target.value as typeof filtroDificultad)}
              >
                <option value="TODAS">Todas</option>
                {DIFICULTADES.map((dificultad) => (
                  <option key={dificultad} value={dificultad}>
                    {ETIQUETA_DIFICULTAD[dificultad]}
                  </option>
                ))}
              </Selector>
            </Campo>
          </div>

          {filtradas.length === 0 ? (
            <Vacio
              mensaje={
                preguntas.length === 0
                  ? 'Todavia no hay preguntas. Genera preguntas desde un documento o crea una manualmente.'
                  : 'Ninguna pregunta coincide con los filtros seleccionados.'
              }
            />
          ) : (
            <ul className="flex flex-col gap-2">
              {filtradas.map((pregunta) => {
                const abierta = expandida === pregunta.id;
                return (
                  <li key={pregunta.id} className="rounded-lg border border-slate-200">
                    <div className="flex flex-wrap items-start justify-between gap-3 px-4 py-3">
                      <div className="min-w-0 flex-1">
                        <div className="mb-1 flex flex-wrap items-center gap-2">
                          <Insignia tono="azul">{ETIQUETA_TIPO_PREGUNTA[pregunta.tipo as TipoPregunta]}</Insignia>
                          <Insignia tono={tonoEstado(pregunta.estado)}>
                            {ETIQUETA_ESTADO_PREGUNTA[pregunta.estado] ?? pregunta.estado}
                          </Insignia>
                          <Insignia tono="gris">{ETIQUETA_DIFICULTAD[pregunta.dificultad as Dificultad]}</Insignia>
                          <Insignia tono="gris">
                            {ETIQUETA_ORIGEN_PREGUNTA[pregunta.origen as OrigenPregunta] ?? pregunta.origen}
                          </Insignia>
                          {pregunta.pagina && <Insignia tono="gris">pag. {pregunta.pagina}</Insignia>}
                          {pregunta.respuestaPendiente && <Insignia tono="ambar">respuesta por confirmar</Insignia>}
                          {pregunta.usadaEnQuices > 0 && (
                            <Insignia tono="violeta">en {pregunta.usadaEnQuices} quiz(es)</Insignia>
                          )}
                        </div>
                        <p className="text-sm text-slate-800">{pregunta.enunciado}</p>
                      </div>
                      <div className="flex flex-wrap gap-2">
                        <Boton
                          variante="secundario"
                          tamano="sm"
                          onClick={() => setExpandida(abierta ? null : pregunta.id)}
                        >
                          {abierta ? 'Ocultar' : 'Ver opciones'}
                        </Boton>
                        <Boton variante="secundario" tamano="sm" onClick={() => setEditando(preguntaAValores(pregunta))}>
                          Editar
                        </Boton>
                        {pregunta.estado !== 'APPROVED' && (
                          <Boton
                            variante="exito"
                            tamano="sm"
                            disabled={ocupada === pregunta.id}
                            onClick={() => void cambiarEstado(pregunta, 'APPROVED')}
                          >
                            Aprobar
                          </Boton>
                        )}
                        <Boton
                          variante="peligro"
                          tamano="sm"
                          disabled={ocupada === pregunta.id}
                          onClick={() => void eliminar(pregunta)}
                        >
                          Eliminar
                        </Boton>
                      </div>
                    </div>

                    {abierta && (
                      <div className="border-t border-slate-100 px-4 py-3">
                        <ul className="flex flex-col gap-1">
                          {pregunta.opciones.map((opcion) => (
                            <li
                              key={opcion.id}
                              className={`flex items-start gap-2 rounded-md px-2 py-1 text-sm ${
                                opcion.correcta ? 'bg-emerald-50 text-emerald-900' : 'text-slate-700'
                              }`}
                            >
                              <span className="font-semibold">{opcion.etiqueta}.</span>
                              <span>{opcion.texto}</span>
                              {opcion.correcta && <span className="text-xs font-semibold">(correcta)</span>}
                            </li>
                          ))}
                        </ul>
                        {pregunta.explicacion && (
                          <p className="mt-2 text-xs text-slate-600">
                            <span className="font-semibold">Explicacion: </span>
                            {pregunta.explicacion}
                          </p>
                        )}
                        {pregunta.documento && (
                          <p className="mt-1 text-xs text-slate-500">
                            Documento: {pregunta.documento.titulo}
                            {pregunta.tema ? ` · Tema: ${pregunta.tema}` : ''}
                          </p>
                        )}
                      </div>
                    )}
                  </li>
                );
              })}
            </ul>
          )}
        </Tarjeta>
      )}
    </div>
  );
}

'use client';

import { useRef, useState } from 'react';
import { useRouter } from 'next/navigation';
import { api, ErrorPeticion } from '@/lib/cliente/api';
import type { FragmentoDto, ResultadoGeneracionDto } from '@/lib/cliente/tipos';
import {
  Alerta,
  Boton,
  Campo,
  Casilla,
  Entrada,
  Insignia,
  Selector,
  Tarjeta,
} from '@/components/ui';
import {
  DIFICULTADES,
  ETIQUETA_DIFICULTAD,
  ETIQUETA_TIPO_PREGUNTA,
  TIPOS_PREGUNTA,
  type Dificultad,
  type TipoPregunta,
} from '@/lib/dominio/constantes';

type Modo = 'generar' | 'importar';

type Linea = {
  indice: number;
  paginas: string;
  creadas: number;
  omitidas: number;
  pendientes: number;
  mensaje?: string;
};

export function PanelGeneracion({
  documentoId,
  fragmentos,
  tieneTexto,
  proveedor,
}: {
  documentoId: string;
  fragmentos: FragmentoDto[];
  tieneTexto: boolean;
  proveedor: string;
}) {
  const router = useRouter();
  const [modo, setModo] = useState<Modo>('generar');
  const [cantidad, setCantidad] = useState(3);
  const [tipos, setTipos] = useState<TipoPregunta[]>(['MCQ_SINGLE', 'TRUE_FALSE']);
  const [dificultad, setDificultad] = useState<Dificultad>('MEDIUM');
  const [idioma, setIdioma] = useState('espanol');
  const [instrucciones, setInstrucciones] = useState('');
  const [enProceso, setEnProceso] = useState(false);
  const [progreso, setProgreso] = useState({ actual: 0, total: 0 });
  const [lineas, setLineas] = useState<Linea[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [resumen, setResumen] = useState({ creadas: 0, omitidas: 0, pendientes: 0 });
  const cancelar = useRef(false);

  function alternarTipo(tipo: TipoPregunta) {
    setTipos((actual) =>
      actual.includes(tipo) ? actual.filter((t) => t !== tipo) : [...actual, tipo],
    );
  }

  async function ejecutar() {
    if (!tieneTexto) {
      setError('El documento no tiene texto utilizable. Revisa el estado de la extraccion.');
      return;
    }
    if (fragmentos.length === 0) {
      setError('No hay fragmentos que procesar.');
      return;
    }
    if (modo === 'generar' && tipos.length === 0) {
      setError('Selecciona al menos un tipo de pregunta.');
      return;
    }

    cancelar.current = false;
    setEnProceso(true);
    setError(null);
    setLineas([]);
    setResumen({ creadas: 0, omitidas: 0, pendientes: 0 });
    setProgreso({ actual: 0, total: fragmentos.length });

    const acumulado = { creadas: 0, omitidas: 0, pendientes: 0 };
    const nuevasLineas: Linea[] = [];

    try {
      for (let indice = 0; indice < fragmentos.length; indice += 1) {
        if (cancelar.current) break;
        const fragmento = fragmentos[indice]!;
        const etiquetaPaginas = `pag. ${fragmento.paginaInicio}-${fragmento.paginaFin}`;

        const respuesta =
          modo === 'generar'
            ? await api.post<ResultadoGeneracionDto>(`/api/documentos/${documentoId}/generar`, {
                fragmento: indice,
                cantidad,
                tipos,
                dificultad,
                idioma,
                instruccionesExtra: instrucciones,
              })
            : await api.post<ResultadoGeneracionDto & { detectadas?: number }>(
                `/api/documentos/${documentoId}/importar`,
                { fragmento: indice },
              );

        acumulado.creadas += respuesta.creadas;
        acumulado.omitidas += respuesta.omitidas;
        acumulado.pendientes += respuesta.pendientes;

        nuevasLineas.push({
          indice,
          paginas: etiquetaPaginas,
          creadas: respuesta.creadas,
          omitidas: respuesta.omitidas,
          pendientes: respuesta.pendientes,
          mensaje:
            modo === 'importar' && respuesta.creadas === 0
              ? 'No se detectaron preguntas en este fragmento.'
              : undefined,
        });

        setLineas([...nuevasLineas]);
        setResumen({ ...acumulado });
        setProgreso({ actual: indice + 1, total: fragmentos.length });
      }
    } catch (e) {
      setError(
        e instanceof ErrorPeticion
          ? e.message
          : 'Ocurrio un error inesperado durante el procesamiento.',
      );
    } finally {
      setEnProceso(false);
      router.refresh();
    }
  }

  const porcentaje = progreso.total === 0 ? 0 : Math.round((progreso.actual / progreso.total) * 100);

  return (
    <Tarjeta
      titulo="Crear preguntas a partir de este documento"
      descripcion={`Proveedor de IA activo: ${proveedor}. El documento se procesa por fragmentos para mostrar el progreso y evitar preguntas repetidas.`}
    >
      <div className="flex flex-col gap-5">
        {error && <Alerta tipo="error">{error}</Alerta>}

        <div className="flex flex-wrap gap-2" role="tablist" aria-label="Modo de creacion">
          <Boton
            variante={modo === 'generar' ? 'primario' : 'secundario'}
            onClick={() => setModo('generar')}
            disabled={enProceso}
            role="tab"
            aria-selected={modo === 'generar'}
          >
            Generar desde material
          </Boton>
          <Boton
            variante={modo === 'importar' ? 'primario' : 'secundario'}
            onClick={() => setModo('importar')}
            disabled={enProceso}
            role="tab"
            aria-selected={modo === 'importar'}
          >
            Importar examen / banco existente
          </Boton>
        </div>

        <p className="text-sm text-slate-600">
          {modo === 'generar'
            ? 'La IA redacta preguntas nuevas a partir del contenido del documento.'
            : 'El sistema detecta las preguntas y opciones ya presentes en el PDF. Si no puede determinar la respuesta correcta, la marca como pendiente de revision.'}
        </p>

        {modo === 'generar' && (
          <div className="grid gap-4 md:grid-cols-3">
            <Campo etiqueta="Preguntas por fragmento" requerido ayuda={`${fragmentos.length} fragmentos en total`}>
              <Entrada
                type="number"
                min={1}
                max={20}
                value={cantidad}
                onChange={(evento) => setCantidad(Number(evento.target.value))}
                disabled={enProceso}
              />
            </Campo>
            <Campo etiqueta="Dificultad">
              <Selector
                value={dificultad}
                onChange={(evento) => setDificultad(evento.target.value as Dificultad)}
                disabled={enProceso}
              >
                {DIFICULTADES.map((valor) => (
                  <option key={valor} value={valor}>
                    {ETIQUETA_DIFICULTAD[valor]}
                  </option>
                ))}
              </Selector>
            </Campo>
            <Campo etiqueta="Idioma">
              <Entrada
                value={idioma}
                onChange={(evento) => setIdioma(evento.target.value)}
                disabled={enProceso}
                placeholder="espanol"
              />
            </Campo>

            <div className="md:col-span-3">
              <p className="mb-2 text-sm font-medium text-slate-700">Tipos de pregunta</p>
              <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-4">
                {TIPOS_PREGUNTA.map((tipo) => (
                  <Casilla
                    key={tipo}
                    etiqueta={ETIQUETA_TIPO_PREGUNTA[tipo]}
                    checked={tipos.includes(tipo)}
                    onChange={() => alternarTipo(tipo)}
                    disabled={enProceso}
                  />
                ))}
              </div>
            </div>

            <div className="md:col-span-3">
              <Campo etiqueta="Instrucciones adicionales" ayuda="Opcional: enfoque, temas a cubrir o evitar.">
                <Entrada
                  value={instrucciones}
                  onChange={(evento) => setInstrucciones(evento.target.value)}
                  disabled={enProceso}
                  placeholder="Ej: enfatizar los planetas interiores y evitar preguntas de fechas"
                />
              </Campo>
            </div>
          </div>
        )}

        <div className="flex flex-wrap gap-2">
          <Boton onClick={() => void ejecutar()} disabled={enProceso}>
            {enProceso
              ? 'Procesando...'
              : modo === 'generar'
                ? 'Generar preguntas'
                : 'Importar preguntas'}
          </Boton>
          {enProceso && (
            <Boton variante="secundario" onClick={() => (cancelar.current = true)}>
              Detener
            </Boton>
          )}
        </div>

        {(enProceso || lineas.length > 0) && (
          <div className="flex flex-col gap-2">
            <div className="flex justify-between text-xs text-slate-600">
              <span>
                Fragmento {progreso.actual} de {progreso.total}
              </span>
              <span>{porcentaje}%</span>
            </div>
            <div
              className="h-2 w-full overflow-hidden rounded-full bg-slate-200"
              role="progressbar"
              aria-valuenow={porcentaje}
              aria-valuemin={0}
              aria-valuemax={100}
            >
              <div className="h-full bg-brand-600 transition-all" style={{ width: `${porcentaje}%` }} />
            </div>
          </div>
        )}

        {lineas.length > 0 && (
          <div className="rounded-lg border border-slate-200 bg-slate-50 px-4 py-3">
            <p className="mb-2 text-sm font-semibold text-slate-800">Resumen</p>
            <div className="mb-3 flex flex-wrap gap-2">
              <Insignia tono="verde">{resumen.creadas} pregunta(s) creada(s)</Insignia>
              <Insignia tono="gris">{resumen.omitidas} duplicada(s) omitida(s)</Insignia>
              <Insignia tono="ambar">{resumen.pendientes} pendiente(s) de revision</Insignia>
            </div>
            <ul className="max-h-56 overflow-y-auto text-xs text-slate-600">
              {lineas.map((linea) => (
                <li key={linea.indice} className="flex flex-wrap items-center gap-2 border-b border-slate-200 py-1">
                  <span className="font-medium text-slate-700">
                    Fragmento {linea.indice + 1} ({linea.paginas})
                  </span>
                  <span>{linea.creadas} creadas</span>
                  <span>{linea.omitidas} omitidas</span>
                  {linea.pendientes > 0 && <span>{linea.pendientes} pendientes</span>}
                  {linea.mensaje && <span className="text-amber-700">{linea.mensaje}</span>}
                </li>
              ))}
            </ul>
          </div>
        )}
      </div>
    </Tarjeta>
  );
}

import { notFound } from 'next/navigation';
import Link from 'next/link';
import { prisma } from '@/lib/db';
import { requiereRol } from '@/lib/auth/guard';
import { env } from '@/lib/env';
import { fragmentarPaginas, vistaPreviaFragmento } from '@/lib/pdf/chunking';
import { obtenerDocumentoVisible, paginasDeDocumento } from '@/lib/documentos/servicio';
import { aPreguntaDto, INCLUDE_PREGUNTA_DTO } from '@/lib/preguntas/dto';
import type { FragmentoDto, PreguntaDto } from '@/lib/cliente/tipos';
import { formatearBytes } from '@/lib/cliente/formato';
import { ETIQUETA_ESTADO_DOCUMENTO } from '@/lib/dominio/constantes';
import { Alerta, Estadistica, Insignia, Tarjeta } from '@/components/ui';
import { BancoPreguntas } from '@/components/preguntas/BancoPreguntas';
import { PanelGeneracion } from './PanelGeneracion';

export const dynamic = 'force-dynamic';

export default async function PaginaDocumento({ params }: { params: Promise<{ id: string }> }) {
  const { usuario } = await requiereRol('ADMIN', 'TEACHER');
  const { id } = await params;

  let documento;
  try {
    documento = await obtenerDocumentoVisible(id, usuario);
  } catch {
    notFound();
  }

  const fragmentos = fragmentarPaginas(paginasDeDocumento(documento));
  const preguntasDb = await prisma.question.findMany({
    where: { documentId: id },
    orderBy: { createdAt: 'desc' },
    include: INCLUDE_PREGUNTA_DTO,
  });

  const fragmentosDto: FragmentoDto[] = fragmentos.map((fragmento, indice) => ({
    indice,
    paginaInicio: fragmento.paginaInicio,
    paginaFin: fragmento.paginaFin,
    caracteres: fragmento.caracteres,
    vistaPrevia: vistaPreviaFragmento(fragmento, 240),
  }));

  const preguntas: PreguntaDto[] = preguntasDb.map((pregunta) => aPreguntaDto(pregunta));
  const tieneTexto = documento.extractedText.trim().length >= 40;

  return (
    <div className="flex flex-col gap-6">
      <nav aria-label="Ruta de navegacion" className="text-sm text-slate-500">
        <Link href="/docentes/documentos" className="text-brand-700 hover:underline">
          Documentos
        </Link>
        <span aria-hidden="true"> / </span>
        <span className="text-slate-700">{documento.title}</span>
      </nav>

      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">{documento.title}</h1>
          <p className="mt-1 text-sm text-slate-600">
            {documento.originalName} · {formatearBytes(documento.sizeBytes)} ·{' '}
            {new Date(documento.createdAt).toLocaleString('es-CO')}
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <Insignia tono={documento.status === 'EXTRACTED' ? 'verde' : 'ambar'}>
            {ETIQUETA_ESTADO_DOCUMENTO[documento.status as keyof typeof ETIQUETA_ESTADO_DOCUMENTO] ??
              documento.status}
          </Insignia>
          {documento.usedOcr && <Insignia tono="violeta">OCR</Insignia>}
        </div>
      </div>

      {documento.errorMessage && <Alerta tipo="aviso" titulo="Aviso del procesamiento">{documento.errorMessage}</Alerta>}

      <div className="grid grid-cols-2 gap-3 md:grid-cols-4">
        <Estadistica etiqueta="Paginas" valor={documento.pageCount} />
        <Estadistica etiqueta="Fragmentos" valor={fragmentos.length} tono="violeta" />
        <Estadistica etiqueta="Caracteres" valor={documento.charCount.toLocaleString('es-CO')} tono="ambar" />
        <Estadistica etiqueta="Preguntas" valor={preguntas.length} tono="verde" />
      </div>

      {!tieneTexto && (
        <Alerta tipo="error" titulo="No se pudo extraer texto">
          Este PDF no tiene una capa de texto utilizable (probablemente es un documento escaneado). Activa
          el OCR con <code className="font-mono">OCR_ENABLED=true</code> en el archivo{' '}
          <code className="font-mono">.env</code> y vuelve a subirlo, o sube una version digital del
          documento.
        </Alerta>
      )}

      <PanelGeneracion
        documentoId={documento.id}
        fragmentos={fragmentosDto}
        tieneTexto={tieneTexto}
        proveedor={env.llm.proveedor}
      />

      {fragmentosDto.length > 0 && (
        <Tarjeta
          titulo="Fragmentos detectados"
          descripcion={`El documento se dividio en ${fragmentosDto.length} fragmento(s) de hasta ${env.pdf.chunkSize} caracteres con solape de ${env.pdf.chunkSolape}.`}
        >
          <ul className="flex flex-col gap-2">
            {fragmentosDto.slice(0, 12).map((fragmento) => (
              <li key={fragmento.indice} className="rounded-lg border border-slate-200 px-3 py-2">
                <p className="text-xs font-semibold text-slate-700">
                  Fragmento {fragmento.indice + 1} · paginas {fragmento.paginaInicio}-{fragmento.paginaFin} ·{' '}
                  {fragmento.caracteres.toLocaleString('es-CO')} caracteres
                </p>
                <p className="mt-1 text-xs text-slate-600">{fragmento.vistaPrevia}…</p>
              </li>
            ))}
          </ul>
          {fragmentosDto.length > 12 && (
            <p className="mt-2 text-xs text-slate-500">
              Se muestran los primeros 12 fragmentos de {fragmentosDto.length}.
            </p>
          )}
        </Tarjeta>
      )}

      <details className="rounded-xl border border-slate-200 bg-white px-5 py-4">
        <summary className="cursor-pointer text-sm font-semibold text-slate-800">
          Ver texto extraido (primeras 2000 letras)
        </summary>
        <pre className="mt-3 max-h-80 overflow-auto whitespace-pre-wrap rounded-lg bg-slate-50 p-3 text-xs text-slate-700">
          {documento.extractedText.slice(0, 2000) || '(sin texto)'}
        </pre>
      </details>

