1: /**
2:  * Generador de PDF minimo (sin dependencias) usado para crear documentos de
3:  * demostracion y para las pruebas automatizadas.
4:  *
5:  * Produce un PDF 1.4 valido con texto usando la fuente base Helvetica, con
6:  * tabla xref correcta, de forma que pdfjs-dist pueda extraer el texto.
7:  */
8: 
9: function escaparTexto(texto: string): string {
10:   return texto
11:     .replace(/\\/g, '\\\\')
12:     .replace(/\(/g, '\\(')
13:     .replace(/\)/g, '\\)')
14:     .replace(/[^\x20-\x7E]/g, '?');
15: }
16: 
17: function escaparCadenaPdf(texto: string): string {
18:   return texto.replace(/\\/g, '\\\\').replace(/\(/g, '\\(').replace(/\)/g, '\\)');
19: }
20: 
21: type Objeto = { numero: number; contenido: string };
22: 
23: export function crearPdfSimple(paginas: string[][], titulo = 'Documento de demostracion'): Buffer {
24:   const FUENTE = 12;
25:   const ANCHO = 612;
26:   const ALTO = 792;
27:   const MARGEN_X = 56;
28:   const MARGEN_Y = 60;
29:   const INTERLINEADO = 16;
30:   const lineasPorPagina = Math.floor((ALTO - MARGEN_Y * 2) / INTERLINEADO);
31: 
32:   // Divide el contenido en lineas fisicas respetando el ancho aproximado.
33:   const lineasFisicas: string[] = [];
34:   for (const pagina of paginas) {
35:     if (lineasFisicas.length > 0) lineasFisicas.push('\f');
36:     for (const parrafo of pagina) {
37:       const maxCaracteres = Math.floor((ANCHO - MARGEN_X * 2) / (FUENTE * 0.5));
38:       let resto = parrafo.trim();
39:       if (resto === '') {
40:         lineasFisicas.push('');
41:         continue;
42:       }
43:       while (resto.length > maxCaracteres) {
44:         let corte = resto.lastIndexOf(' ', maxCaracteres);
45:         if (corte < maxCaracteres * 0.5) corte = maxCaracteres;
46:         lineasFisicas.push(resto.slice(0, corte));
47:         resto = resto.slice(corte).trim();
48:       }
49:       lineasFisicas.push(resto);
50:     }
51:   }
52: 
53:   // Reparte las lineas en paginas reales.
54:   const paginasFinales: string[][] = [];
55:   let actual: string[] = [];
56:   for (const linea of lineasFisicas) {
57:     if (linea === '\f' || actual.length >= lineasPorPagina) {
58:       if (actual.length > 0) paginasFinales.push(actual);
59:       actual = [];
60:       if (linea === '\f') continue;
61:     }
62:     actual.push(linea);
63:   }
64:   if (actual.length > 0) paginasFinales.push(actual);
65:   if (paginasFinales.length === 0) paginasFinales.push(['(documento vacio)']);
66: 
67:   const objetos: Objeto[] = [];
68:   const totalPaginas = paginasFinales.length;
69:   const idPaginas = 2;
70:   const idFuente = 3;
71:   const primerContenido = 4;
72: 
73:   objetos.push({ numero: 1, contenido: `<< /Type /Catalog /Pages ${idPaginas} 0 R >>` });
74: 
75:   const idsPaginas: number[] = [];
76:   const idsContenido: number[] = [];
77:   for (let i = 0; i < totalPaginas; i += 1) {
78:     idsPaginas.push(primerContenido + i * 2);
79:     idsContenido.push(primerContenido + i * 2 + 1);
80:   }
81: 
82:   objetos.push({
83:     numero: idPaginas,
84:     contenido: `<< /Type /Pages /Kids [${idsPaginas
85:       .map((id) => `${id} 0 R`)
86:       .join(' ')}] /Count ${totalPaginas} >>`,
87:   });
88: 
89:   objetos.push({
90:     numero: idFuente,
91:     contenido: '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>',
92:   });
93: 
94:   for (let i = 0; i < totalPaginas; i += 1) {
95:     const numeroPagina = idsPaginas[i]!;
96:     const numeroContenido = idsContenido[i]!;
97: 
98:     objetos.push({
99:       numero: numeroPagina,
100:       contenido:
101:         `<< /Type /Page /Parent ${idPaginas} 0 R /MediaBox [0 0 ${ANCHO} ${ALTO}] ` +
102:         `/Resources << /Font << /F1 ${idFuente} 0 R >> >> /Contents ${numeroContenido} 0 R >>`,
103:     });
104: 
105:     const lineas = paginasFinales[i]!;
106:     let flujo = 'BT\n';
107:     lineas.forEach((linea, indice) => {
108:       const y = ALTO - MARGEN_Y - indice * INTERLINEADO;
109:       flujo += `/F1 ${FUENTE} Tf 1 0 0 1 ${MARGEN_X} ${y} Tm (${escaparTexto(linea)}) Tj\n`;
110:     });
111:     flujo += 'ET';
112: 
113:     objetos.push({
114:       numero: numeroContenido,
115:       contenido: `<< /Length ${Buffer.byteLength(flujo, 'latin1')} >>\nstream\n${flujo}\nendstream`,
116:     });
117:   }
118: 
119:   objetos.push({
120:     numero: idFuente + totalPaginas * 2 + 1,
121:     contenido: `<< /Title (${escaparCadenaPdf(titulo)}) /Producer (QuizColegio) >>`,
122:   });
123: 
124:   objetos.sort((a, b) => a.numero - b.numero);
125: 
126:   let pdf = '%PDF-1.4\n';
127:   const offsets: number[] = [];
128:   for (const objeto of objetos) {
129:     offsets[objeto.numero] = Buffer.byteLength(pdf, 'latin1');
130:     pdf += `${objeto.numero} 0 obj\n${objeto.contenido}\nendobj\n`;
131:   }
132: 
133:   const maxObjeto = Math.max(...objetos.map((o) => o.numero));
134:   const inicioXref = Buffer.byteLength(pdf, 'latin1');
