180: const RE_PREGUNTA = /^\s*(?:(\d{1,3})\s*[.)\-:]|[-*•])\s*(.+)$/;
181: const RE_OPCION = /^\s*(?:\()?([a-hA-H]|[ivxIVX]{1,4})\s*[.)\-:]\s*(.+)$/;
182: const RE_ENUNCIADO_CON_PREGUNTA = /^\s*(?:\d{1,3}\s*[.)])?\s*[¿]?.*\?$/;
183: 
184: function limpiar(texto: string): string {
185:   return texto.replace(/\s+/g, ' ').trim();
186: }
187: 
188: function marcarCorrecta(texto: string): { texto: string; marcada: boolean } {
189:   const patrones = [/\(\s*x\s*\)/i, /\*\s*$/, /✔/, /✓/, /\[correcta\]/i, /__+/];
190:   let marcada = false;
191:   let resultado = texto;
192:   for (const patron of patrones) {
193:     if (patron.test(resultado)) {
194:       marcada = true;
195:       resultado = resultado.replace(patron, ' ');
196:     }
197:   }
198:   return { texto: limpiar(resultado), marcada };
199: }
200: 
201: function detectarClaveDeRespuestas(texto: string): Map<number, string> {
202:   const claves = new Map<number, string>();
203:   const lineas = texto.split('\n');
204:   for (const linea of lineas) {
205:     if (!/respuestas?|clave|answers?|solucion/i.test(linea)) continue;
206:     const pares = linea.matchAll(/(\d{1,3})\s*[).:\-]?\s*([a-hA-H])\b/g);
207:     for (const par of pares) {
208:       claves.set(Number(par[1]), par[2]!.toLowerCase());
209:     }
210:   }
211:   return claves;
212: }
213: 
214: function importar(peticion: PeticionImportacionLlm): LoteLlm {
215:   const claves = detectarClaveDeRespuestas(peticion.texto);
216:   const lineas = peticion.texto.split('\n');
217: 
218:   type Bloque = { enunciado: string; opciones: { texto: string; correcta: boolean | null }[] };
219:   const bloques: Bloque[] = [];
220:   let actual: Bloque | null = null;
221:   let numero = 0;
222: 
223:   for (const linea of lineas) {
224:     const limpia = linea.trim();
225:     if (limpia === '') continue;
226: 
227:     const comoOpcion = RE_OPCION.exec(linea);
228:     if (actual && comoOpcion && comoOpcion[2]) {
229:       const { texto, marcada } = marcarCorrecta(comoOpcion[2]);
230:       if (texto.length > 0) {
231:         actual.opciones.push({ texto, correcta: marcada ? true : null });
232:       }
233:       continue;
234:     }
235: 
236:     const comoPregunta = RE_PREGUNTA.exec(linea);
237:     const pareceEnunciado = RE_ENUNCIADO_CON_PREGUNTA.test(linea) && limpia.length > 15;
238: 
239:     if ((comoPregunta && comoPregunta[2] && comoPregunta[2].trim().length > 10) || pareceEnunciado) {
240:       // Si el bloque anterior no tenia opciones, se guarda igualmente.
241:       if (actual) bloques.push(actual);
242:       numero += 1;
243:       const enunciadoCrudo = comoPregunta?.[2] ?? limpia;
244:       const { texto } = marcarCorrecta(enunciadoCrudo);
245:       actual = { enunciado: limpiar(texto), opciones: [] };
246:       continue;
247:     }
248: 
249:     if (actual && actual.opciones.length === 0) {
250:       actual.enunciado = limpiar(`${actual.enunciado} ${limpia}`);
251:     }
252:   }
253:   if (actual) bloques.push(actual);
254: 
255:   const preguntas: LoteLlm['preguntas'] = [];
256: 
257:   for (const bloque of bloques) {
258:     if (bloque.enunciado.length < 15) continue;
259:     if (bloque.opciones.length < 2) continue;
260: 
261:     const correctasMarcadas = bloque.opciones.filter((o) => o.correcta === true);
262:     let opciones = bloque.opciones;
263: 
264:     if (correctasMarcadas.length === 0 && claves.size > 0) {
265:       // Intenta aplicar la hoja de respuestas detectada.
266:       const posicion = preguntas.length + 1;
267:       const letraClave = claves.get(posicion) ?? claves.get(numero);
268:       if (letraClave) {
269:         const indice = letraClave.charCodeAt(0) - 97;
270:         opciones = bloque.opciones.map((opcion, i) => ({
271:           texto: opcion.texto,
272:           correcta: i === indice ? true : null,
273:         }));
274:       }
275:     }
276: 
277:     const conCorrecta = opciones.filter((o) => o.correcta === true).length > 0;
278:     const esVerdaderoFalso =
279:       opciones.length === 2 &&
280:       opciones.every((o) => /^(verdadero|falso|true|false)$/i.test(o.texto.trim()));
281: 
282:     preguntas.push({
283:       enunciado: bloque.enunciado,
284:       tipo: esVerdaderoFalso ? 'TRUE_FALSE' : conCorrecta && opciones.filter((o) => o.correcta).length > 1 ? 'MCQ_MULTI' : 'MCQ_SINGLE',
285:       opciones: opciones.map((opcion) => ({ texto: opcion.texto, correcta: opcion.correcta })),
286:       explicacion: '',
287:       tema: 'Examen importado',
288:       pagina: peticion.paginaInicio,
289:       requiereRevision: !conCorrecta,
290:     });
291:   }
292: 
293:   return { preguntas };
294: }
295: 
296: export const proveedorMock: LLMProvider = {
297:   nombre: 'mock',
298:   modelo: 'generador-local-determinista',
299: 
300:   async generarPreguntas(peticion: PeticionGeneracionLlm): Promise<LoteLlm> {
301:     return generar(peticion);
302:   },
303: 
304:   async importarPreguntas(peticion: PeticionImportacionLlm): Promise<LoteLlm> {
305:     return importar(peticion);
306:   },
307: };

