112:     .string()
113:     .trim()
114:     .refine((v) => v !== '' && Number.isFinite(Number(v)), 'Debe ser un numero.');
115:   return num
116:     .refine((v) => def.min === undefined || Number(v) >= def.min, `Minimo ${def.min}.`)
117:     .refine((v) => def.max === undefined || Number(v) <= def.max, `Maximo ${def.max}.`)
118:     .refine(
