import { prisma } from '@/lib/db';
import { ruta, leerCuerpo, respuestaOk, infoCliente } from '@/lib/http';
import { requiereRolApi, verificarCsrf } from '@/lib/auth/guard';
import { auditar, ACCIONES } from '@/lib/audit';
import { esquemaCrearQuiz } from '@/lib/esquemas/quices';
import { INCLUDE_QUIZ, aQuizResumenDto } from '@/lib/quices/servicio';
import { obtenerAjusteBooleano, obtenerAjusteNumero } from '@/lib/settings';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

/** GET /api/quices?estado=&buscar= */
export const GET = ruta(async (req) => {
  const sesion = await requiereRolApi('ADMIN', 'TEACHER');
  const url = new URL(req.url);
  const estado = url.searchParams.get('estado');
  const buscar = url.searchParams.get('buscar')?.trim();

  const quices = await prisma.quiz.findMany({
    where: {
      ...(sesion.usuario.role === 'ADMIN' ? {} : { authorId: sesion.usuario.id }),
      ...(estado ? { status: estado } : {}),
      ...(buscar ? { title: { contains: buscar } } : {}),
    },
    orderBy: [{ updatedAt: 'desc' }],
    include: INCLUDE_QUIZ,
  });

  return respuestaOk({ quices: quices.map(aQuizResumenDto) });
});

/** POST /api/quices - crea un borrador de quiz con la configuracion global. */
export const POST = ruta(async (req) => {
  const sesion = await requiereRolApi('ADMIN', 'TEACHER');
  verificarCsrf(req, sesion);
  const { ip } = infoCliente(req);
  const datos = await leerCuerpo(req, esquemaCrearQuiz);

  const [notaMinima, notaMaxima, intentos, umbral, modoSeguro] = await Promise.all([
    obtenerAjusteNumero('academico.notaMinima', 3),
    obtenerAjusteNumero('academico.notaMaxima', 5),
    obtenerAjusteNumero('quiz.intentosMaximos', 1),
    obtenerAjusteNumero('quiz.umbralInfracciones', 3),
    obtenerAjusteBooleano('quiz.modoSeguroPorDefecto', false),
  ]);

  const quiz = await prisma.quiz.create({
    data: {
      title: datos.titulo,
      description: datos.descripcion?.trim() || null,
      authorId: sesion.usuario.id,
      status: 'DRAFT',
      navigationMode: 'FREE',
      maxAttempts: Math.max(1, Math.min(10, Math.round(intentos))),
      defaultPoints: 1,
      passingScore: notaMinima,
      maxGrade: Math.max(1, notaMaxima),
      showResults: 'SCORE',
      allowReview: true,
      secureMode: modoSeguro,
      infractionThreshold: Math.max(1, Math.round(umbral)),
      infractionAction: 'AUTO_SUBMIT',
      blockWithoutFullscreen: true,
    },
    include: INCLUDE_QUIZ,
  });

  await auditar({
    accion: ACCIONES.QUIZ_CREADO,
    actorId: sesion.usuario.id,
    tipoEntidad: 'Quiz',
    entidadId: quiz.id,
    meta: { titulo: quiz.title },
    ip,
  });

  return respuestaOk({ quiz: aQuizResumenDto(quiz) }, 201);
});

import { prisma } from '@/lib/db';
import {
  ruta,
  leerCuerpo,
  respuestaOk,
  infoCliente,
  conflicto,
  solicitudInvalida,
  noEncontrado,
} from '@/lib/http';
import { requiereRolApi, verificarCsrf } from '@/lib/auth/guard';
import { auditar, ACCIONES } from '@/lib/audit';
import { esquemaActualizarQuiz, fechaDesdeTexto } from '@/lib/esquemas/quices';
import {
  INCLUDE_QUIZ,
  aQuizDetalleDto,
  obtenerQuizAutorizado,
  validarPublicacion,
} from '@/lib/quices/servicio';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

type Ctx = { params: Promise<{ id: string }> };

/** GET /api/quices/[id] - ficha completa para el editor y la revision. */
export const GET = ruta<Ctx['params']>(async (_req, ctx) => {
  const sesion = await requiereRolApi('ADMIN', 'TEACHER');
  const { id } = await ctx.params;
  const quiz = await obtenerQuizAutorizado(id, sesion.usuario);

  return respuestaOk({
    quiz: aQuizDetalleDto(quiz),
    revision: validarPublicacion(quiz),
  });
});

/** PATCH /api/quices/[id] - guarda la configuracion del quiz. */
export const PATCH = ruta<Ctx['params']>(async (req, ctx) => {
  const sesion = await requiereRolApi('ADMIN', 'TEACHER');
  verificarCsrf(req, sesion);
  const { ip } = infoCliente(req);
  const { id } = await ctx.params;

  const quiz = await obtenerQuizAutorizado(id, sesion.usuario);
  if (quiz.status === 'CLOSED') {
    throw conflicto('Un quiz cerrado no se puede editar. Crea uno nuevo si necesitas reutilizarlo.');
  }

  const datos = await leerCuerpo(req, esquemaActualizarQuiz);

  // Validacion de negocio con los valores ya combinados (PATCH parcial).
  const notaAprobacion = datos.notaAprobacion ?? quiz.passingScore;
  const notaMaxima = datos.notaMaxima ?? quiz.maxGrade;
  if (notaAprobacion > notaMaxima) {
    throw solicitudInvalida('La nota minima de aprobacion no puede superar la nota maxima.', {
      notaAprobacion: 'Debe ser menor o igual que la nota maxima.',
    });
  }

  const desde =
    datos.fechaDisponibleDesde !== undefined
      ? fechaDesdeTexto(datos.fechaDisponibleDesde)
      : quiz.availableFrom;
  const hasta =
    datos.fechaDisponibleHasta !== undefined
      ? fechaDesdeTexto(datos.fechaDisponibleHasta)
      : quiz.availableTo;

  if (datos.fechaDisponibleDesde && !desde) {
    throw solicitudInvalida('La fecha de apertura no es valida.', {
      fechaDisponibleDesde: 'Usa una fecha valida.',
    });
  }
  if (datos.fechaDisponibleHasta && !hasta) {
    throw solicitudInvalida('La fecha de cierre no es valida.', {
      fechaDisponibleHasta: 'Usa una fecha valida.',
    });
  }
  if (desde && hasta && hasta <= desde) {
    throw solicitudInvalida('La fecha de cierre debe ser posterior a la fecha de apertura.', {
      fechaDisponibleHasta: 'Debe ser posterior a la fecha de apertura.',
    });
  }

  let grupos: { id: string }[] | null = null;
  if (datos.grupoIds) {
    grupos = await prisma.group.findMany({
      where: { id: { in: datos.grupoIds } },
      select: { id: true },
    });
    if (grupos.length !== datos.grupoIds.length) {
      throw solicitudInvalida('Uno o mas grupos seleccionados no existen.');
    }
  }

  const actualizado = await prisma.$transaction(async (tx) => {
    if (datos.grupoIds) {
      await tx.quizAssignment.deleteMany({ where: { quizId: id } });
      if (datos.grupoIds.length > 0) {
        await tx.quizAssignment.createMany({
          data: datos.grupoIds.map((groupId) => ({ quizId: id, groupId })),
        });
      }
    }

    await tx.quiz.update({
      where: { id },
      data: {
        ...(datos.titulo !== undefined ? { title: datos.titulo } : {}),
        ...(datos.descripcion !== undefined
          ? { description: datos.descripcion?.trim() || null }
          : {}),
        ...(datos.fechaDisponibleDesde !== undefined ? { availableFrom: desde } : {}),
        ...(datos.fechaDisponibleHasta !== undefined ? { availableTo: hasta } : {}),
        ...(datos.navegacion !== undefined ? { navigationMode: datos.navegacion } : {}),
        ...(datos.tiempoTotalSeg !== undefined ? { timeLimitSec: datos.tiempoTotalSeg } : {}),
        ...(datos.tiempoPorPreguntaSeg !== undefined
          ? { perQuestionTimeSec: datos.tiempoPorPreguntaSeg }
          : {}),
        ...(datos.mezclarPreguntas !== undefined
          ? { shuffleQuestions: datos.mezclarPreguntas }
          : {}),
        ...(datos.mezclarOpciones !== undefined ? { shuffleOptions: datos.mezclarOpciones } : {}),
        ...(datos.intentosMaximos !== undefined ? { maxAttempts: datos.intentosMaximos } : {}),
        ...(datos.cantidadPreguntas !== undefined
          ? { questionCount: datos.cantidadPreguntas }
          : {}),
        ...(datos.puntosPorDefecto !== undefined
          ? { defaultPoints: datos.puntosPorDefecto }
          : {}),
        ...(datos.notaAprobacion !== undefined ? { passingScore: datos.notaAprobacion } : {}),
        ...(datos.notaMaxima !== undefined ? { maxGrade: datos.notaMaxima } : {}),
        ...(datos.mostrarResultados !== undefined
          ? { showResults: datos.mostrarResultados }
          : {}),
        ...(datos.permitirRevision !== undefined
          ? { allowReview: datos.permitirRevision }
          : {}),
        ...(datos.modoSeguro !== undefined ? { secureMode: datos.modoSeguro } : {}),
        ...(datos.umbralInfracciones !== undefined
          ? { infractionThreshold: datos.umbralInfracciones }
          : {}),
        ...(datos.accionInfraccion !== undefined
          ? { infractionAction: datos.accionInfraccion }
          : {}),
        ...(datos.bloquearSinPantallaCompleta !== undefined
          ? { blockWithoutFullscreen: datos.bloquearSinPantallaCompleta }
          : {}),
      },
    });

    return tx.quiz.findUnique({ where: { id }, include: INCLUDE_QUIZ });
  });

  if (!actualizado) throw noEncontrado('Quiz');

  await auditar({
    accion: ACCIONES.QUIZ_ACTUALIZADO,
    actorId: sesion.usuario.id,
    tipoEntidad: 'Quiz',
    entidadId: id,
    meta: { campos: Object.keys(datos) },
    ip,
  });

  return respuestaOk({
    quiz: aQuizDetalleDto(actualizado),
    revision: validarPublicacion(actualizado),
  });
});

/** DELETE /api/quices/[id] - solo borradores sin intentos. */
export const DELETE = ruta<Ctx['params']>(async (req, ctx) => {
  const sesion = await requiereRolApi('ADMIN', 'TEACHER');
  verificarCsrf(req, sesion);
  const { ip } = infoCliente(req);
  const { id } = await ctx.params;

  const quiz = await obtenerQuizAutorizado(id, sesion.usuario);
  if (quiz.status !== 'DRAFT') {
    throw conflicto('Solo se pueden eliminar borradores. Cierra el quiz en lugar de borrarlo.');
  }
  if (quiz._count.attempts > 0) {
    throw conflicto('El quiz ya tiene intentos registrados y no se puede eliminar.');
  }

  await prisma.quiz.delete({ where: { id } });

  await auditar({
    accion: ACCIONES.QUIZ_ELIMINADO,
    actorId: sesion.usuario.id,
    tipoEntidad: 'Quiz',
    entidadId: id,
    meta: { titulo: quiz.title },
    ip,
  });

  return respuestaOk({ eliminado: true });
});

import { prisma } from '@/lib/db';
import {
  ruta,
  leerCuerpo,
  respuestaOk,
  infoCliente,
  conflicto,
  solicitudInvalida,
  noEncontrado,
} from '@/lib/http';
import { requiereRolApi, verificarCsrf } from '@/lib/auth/guard';
import { auditar, ACCIONES } from '@/lib/audit';
import { esquemaPreguntasQuiz } from '@/lib/esquemas/quices';
import {
  INCLUDE_QUIZ,
  aQuizDetalleDto,
  obtenerQuizAutorizado,
  validarPublicacion,
} from '@/lib/quices/servicio';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

type Ctx = { params: Promise<{ id: string }> };

/**
 * PUT /api/quices/[id]/preguntas
 * Reemplaza la lista ordenada de preguntas del quiz. Se envia el arreglo
 * completo para que reordenar, agregar y quitar sea una sola operacion.
 */
export const PUT = ruta<Ctx['params']>(async (req, ctx) => {
  const sesion = await requiereRolApi('ADMIN', 'TEACHER');
  verificarCsrf(req, sesion);
  const { ip } = infoCliente(req);
  const { id } = await ctx.params;

  const quiz = await obtenerQuizAutorizado(id, sesion.usuario);
  if (quiz.status === 'CLOSED') {
    throw conflicto('Un quiz cerrado no se puede editar.');
  }
  if (quiz._count.attempts > 0) {
    throw conflicto(
      'El quiz ya tiene intentos de estudiantes: no se pueden cambiar sus preguntas.',
    );
  }

  const datos = await leerCuerpo(req, esquemaPreguntasQuiz);
  const ids = datos.preguntas.map((pregunta) => pregunta.id);

  const disponibles = await prisma.question.findMany({
    where: {
      id: { in: ids },
      ...(sesion.usuario.role === 'ADMIN' ? {} : { authorId: sesion.usuario.id }),
    },
    select: { id: true },
  });
  if (disponibles.length !== ids.length) {
    throw solicitudInvalida(
      'Alguna de las preguntas seleccionadas no existe o no pertenece a tu banco.',
    );
  }

  const actualizado = await prisma.$transaction(async (tx) => {
    await tx.quizQuestion.deleteMany({ where: { quizId: id } });
    if (datos.preguntas.length > 0) {
      await tx.quizQuestion.createMany({
        data: datos.preguntas.map((pregunta, indice) => ({
          quizId: id,
          questionId: pregunta.id,
          position: indice,
          points: pregunta.puntos ?? quiz.defaultPoints,
        })),
      });
    }
    return tx.quiz.findUnique({ where: { id }, include: INCLUDE_QUIZ });
  });

  if (!actualizado) throw noEncontrado('Quiz');

  await auditar({
    accion: ACCIONES.QUIZ_ACTUALIZADO,
    actorId: sesion.usuario.id,
    tipoEntidad: 'Quiz',
    entidadId: id,
    meta: { preguntas: datos.preguntas.length },
    ip,
  });

  return respuestaOk({
    quiz: aQuizDetalleDto(actualizado),
    revision: validarPublicacion(actualizado),
  });
});

import { prisma } from '@/lib/db';
import {
  ruta,
  leerCuerpo,
  respuestaOk,
  infoCliente,
  conflicto,
  ErrorApi,
  noEncontrado,
} from '@/lib/http';
import { requiereRolApi, verificarCsrf } from '@/lib/auth/guard';
import { auditar, ACCIONES } from '@/lib/audit';
import { esquemaPublicarQuiz } from '@/lib/esquemas/quices';
import {
  INCLUDE_QUIZ,
  aQuizDetalleDto,
  obtenerQuizAutorizado,
  validarPublicacion,
} from '@/lib/quices/servicio';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

type Ctx = { params: Promise<{ id: string }> };

/**
 * POST /api/quices/[id]/publicar
 * Publica el quiz solo tras una revision explicita del docente
 * (`confirmoRevision: true`). Valida preguntas, respuestas, grupos y fechas.
 */
export const POST = ruta<Ctx['params']>(async (req, ctx) => {
  const sesion = await requiereRolApi('ADMIN', 'TEACHER');
  verificarCsrf(req, sesion);
  const { ip } = infoCliente(req);
  const { id } = await ctx.params;
  await leerCuerpo(req, esquemaPublicarQuiz);

  const quiz = await obtenerQuizAutorizado(id, sesion.usuario);
  if (quiz.status === 'PUBLISHED') {
    throw conflicto('Este quiz ya esta publicado.');
  }
  if (quiz.status === 'CLOSED') {
    throw conflicto('Un quiz cerrado no se puede volver a publicar. Crea uno nuevo.');
  }

  const revision = validarPublicacion(quiz);
  if (revision.errores.length > 0) {
    throw new ErrorApi(
      409,
      'QUIZ_NO_LISTO',
      'El quiz todavia no cumple los requisitos para publicarse.',
      { errores: revision.errores, advertencias: revision.advertencias },
    );
  }

  const publicado = await prisma.$transaction(async (tx) => {
    // La revision explicita convierte las preguntas incluidas en aprobadas.
    await tx.question.updateMany({
      where: { id: { in: quiz.questions.map((entrada) => entrada.questionId) } },
      data: { status: 'APPROVED', answerPending: false },
    });

    return tx.quiz.update({
      where: { id },
      data: { status: 'PUBLISHED', publishedAt: new Date() },
      include: INCLUDE_QUIZ,
    });
  });

  if (!publicado) throw noEncontrado('Quiz');

  await auditar({
    accion: ACCIONES.QUIZ_PUBLICADO,
    actorId: sesion.usuario.id,
    tipoEntidad: 'Quiz',
    entidadId: id,
    meta: {
      titulo: quiz.title,
      preguntas: quiz.questions.length,
      grupos: quiz.assignments.length,
      advertencias: revision.advertencias,
    },
    ip,
  });

  return respuestaOk({
    quiz: aQuizDetalleDto(publicado),
    revision: validarPublicacion(publicado),
  });
});

import { prisma } from '@/lib/db';
import { ruta, respuestaOk, infoCliente, conflicto } from '@/lib/http';
import { requiereRolApi, verificarCsrf } from '@/lib/auth/guard';
import { auditar, ACCIONES } from '@/lib/audit';
import {
  INCLUDE_QUIZ,
  aQuizDetalleDto,
  obtenerQuizAutorizado,
  validarPublicacion,
} from '@/lib/quices/servicio';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

type Ctx = { params: Promise<{ id: string }> };

/** POST /api/quices/[id]/cerrar - cierra un quiz publicado. */
export const POST = ruta<Ctx['params']>(async (req, ctx) => {
  const sesion = await requiereRolApi('ADMIN', 'TEACHER');
  verificarCsrf(req, sesion);
  const { ip } = infoCliente(req);
  const { id } = await ctx.params;

  const quiz = await obtenerQuizAutorizado(id, sesion.usuario);
  if (quiz.status !== 'PUBLISHED') {
    throw conflicto('Solo se puede cerrar un quiz publicado.');
  }

  const cerrado = await prisma.quiz.update({
    where: { id },
    data: { status: 'CLOSED', availableTo: quiz.availableTo ?? new Date() },
    include: INCLUDE_QUIZ,
  });

  await auditar({
    accion: ACCIONES.QUIZ_CERRADO,
    actorId: sesion.usuario.id,
    tipoEntidad: 'Quiz',
    entidadId: id,
    meta: { titulo: quiz.title, intentos: quiz._count.attempts },
    ip,
  });

  return respuestaOk({
    quiz: aQuizDetalleDto(cerrado),
    revision: validarPublicacion(cerrado),
  });
});

