 expiraEn: string|null; preguntaExpiraEn: string|null; ahora: string;
 segundosRestantes: number|null; segundosPreguntaRestantes: number|null;
 permitirRevision: boolean; mostrarResultados: string;
 modoSeguro: boolean;
