58:  * Utilidades
59:  * ------------------------------------------------------------------ */
60: 
61: export function leerLista(texto: string): string[] {
62:   try {
63:     const valor = JSON.parse(texto || '[]');
64:     return Array.isArray(valor) ? valor.filter((item): item is string => typeof item === 'string') : [];
65:   } catch {
66:     return [];
67:   }
68: }
69: 
70: export function leerMapa(texto: string): Record<string, string[]> {
71:   try {
72:     const valor = JSON.parse(texto || '{}');
73:     if (!valor || typeof valor !== 'object' || Array.isArray(valor)) return {};
74:     const mapa: Record<string, string[]> = {};
75:     for (const [clave, lista] of Object.entries(valor)) {
76:       if (Array.isArray(lista)) {
77:         mapa[clave] = lista.filter((item): item is string => typeof item === 'string');
78:       }
79:     }
80:     return mapa;
81:   } catch {
82:     return {};
83:   }
84: }
85: 
86: function barajar<T>(lista: T[]): T[] {
87:   const copia = [...lista];
88:   for (let i = copia.length - 1; i > 0; i -= 1) {
89:     const j = Math.floor(Math.random() * (i + 1));
90:     [copia[i], copia[j]] = [copia[j]!, copia[i]!];
91:   }
92:   return copia;
93: }
94: 
95: function segundosHasta(fecha: Date | null, ahora: Date): number | null {
96:   if (!fecha) return null;
97:   return Math.max(0, Math.ceil((fecha.getTime() - ahora.getTime()) / 1000));
98: }
99: 
100: function normalizarTexto(valor: string): string {
101:   return valor
102:     .toLowerCase()
103:     .normalize('NFD')
104:     .replace(/[\u0300-\u036f]/g, '')
105:     .replace(/[^\p{L}\p{N}\s]/gu, ' ')
106:     .replace(/\s+/g, ' ')
107:     .trim();
108: }
