114: /** Busca un intento y verifica que pertenezca al estudiante autenticado. */
115: export async function obtenerIntentoAutorizado(id: string, estudianteId: string) {
116:   const intento = await buscarIntento(id);
117:   if (!intento) throw noEncontrado('Intento');
118:   if (intento.studentId !== estudianteId) throw sinPermiso();
119:   return intento;
120: }
121: 
122: export function entradasDelIntento(intento: IntentoCompleto): EntradaIntento[] {
123:   const orden = leerLista(intento.questionOrder);
124:   const mapa = new Map(intento.quiz.questions.map((entrada) => [entrada.questionId, entrada]));
125:   return orden
126:     .map((id) => mapa.get(id))
127:     .filter((entrada): entrada is EntradaIntento => Boolean(entrada));
128: }
129: 
130: function entradaActual(intento: IntentoCompleto, entradas: EntradaIntento[]) {
131:   if (entradas.length === 0) return null;
132:   const posicion = Math.min(Math.max(intento.currentPosition, 0), entradas.length - 1);
133:   return entradas[posicion] ?? null;
134: }
135: 
136: function opcionesEnOrden(intento: IntentoCompleto, entrada: EntradaIntento) {
137:   const mapa = leerMapa(intento.optionOrder);
138:   const orden = mapa[entrada.questionId];
139:   const opciones = [...entrada.question.options];
140:   if (orden && orden.length > 0) {
141:     opciones.sort((a, b) => {
142:       const ia = orden.indexOf(a.id);
143:       const ib = orden.indexOf(b.id);
144:       return (ia === -1 ? 999 : ia) - (ib === -1 ? 999 : ib);
145:     });
146:   }
147:   return opciones;
148: }
149: 
150: function respuestaDe(intento: IntentoCompleto, preguntaId: string) {
151:   const respuesta = intento.answers.find((fila) => fila.questionId === preguntaId);
152:   const opciones = respuesta ? leerLista(respuesta.selectedOptions) : [];
153:   return {
154:     opciones,
155:     texto: respuesta?.textAnswer ?? '',
156:     existe: Boolean(respuesta),
157:   };
158: }
159: 
160: function tieneRespuesta(intento: IntentoCompleto, entrada: EntradaIntento): boolean {
161:   const respuesta = respuestaDe(intento, entrada.questionId);
162:   return respuesta.opciones.length > 0 || respuesta.texto.trim().length > 0;
163: }
164: 
165: function expiracionPregunta(intento: IntentoCompleto): Date | null {
166:   const limite = intento.quiz.perQuestionTimeSec;
167:   if (!limite || intento.status !== 'IN_PROGRESS') return null;
168:   const inicio = intento.questionStartedAt ?? intento.startedAt;
169:   return new Date(inicio.getTime() + limite * 1000);
170: }
