172: /* ------------------------------------------------------------------ *
173:  * DTO de estado (solo la pregunta actual, nunca la clave)
174:  * ------------------------------------------------------------------ */
175: 
176: export function estadoIntentoDto(intento: IntentoCompleto): EstadoIntentoDto {
177:   const entradas = entradasDelIntento(intento);
178:   const total = entradas.length;
179:   const posicion = total === 0 ? 0 : Math.min(Math.max(intento.currentPosition, 0), total - 1);
180:   const entrada = entradaActual(intento, entradas);
181:   const ahora = new Date();
182:   const expiraPregunta = expiracionPregunta(intento);
183:   const respuesta = entrada ? respuestaDe(intento, entrada.questionId) : { opciones: [], texto: '' };
184:   const soloTexto = entrada?.question.type === 'SHORT_ANSWER';
185: 
186:   let pregunta: PreguntaEnCursoDto | null = null;
187:   if (entrada) {
188:     const opciones = soloTexto ? [] : opcionesEnOrden(intento, entrada);
189:     pregunta = {
190:       id: entrada.questionId,
191:       tipo: entrada.question.type,
192:       enunciado: entrada.question.statement,
193:       dificultad: entrada.question.difficulty,
194:       tema: entrada.question.topic,
195:       puntos: entrada.points,
196:       opciones: opciones.map((opcion, indice) => ({
197:         id: opcion.id,
198:         etiqueta: String.fromCharCode(65 + indice),
199:         texto: opcion.text,
200:       })),
201:       ayuda:
202:         entrada.question.type === 'MCQ_MULTI'
203:           ? 'Selecciona todas las opciones que correspondan.'
204:           : entrada.question.type === 'SHORT_ANSWER'
205:             ? 'Escribe tu respuesta con tus propias palabras.'
206:             : entrada.question.type === 'TRUE_FALSE'
207:               ? 'Selecciona verdadero o falso.'
208:               : 'Selecciona una sola opcion.',
209:       respuesta: {
210:         opciones: respuesta.opciones,
211:         texto: respuesta.texto ?? '',
212:       },
213:     };
214:   }
215: 
216:   return {
217:     id: intento.id,
218:     quizId: intento.quizId,
219:     tituloQuiz: intento.quiz.title,
220:     descripcionQuiz: intento.quiz.description,
221:     estado: intento.status,
222:     posicion,
223:     total,
224:     esUltima: total > 0 && posicion === total - 1,
225:     navegacion: intento.quiz.navigationMode,
226:     puedeRetroceder: intento.quiz.navigationMode === 'FREE' && posicion > 0,
227:     pregunta,
228:     expiraEn: intento.expiresAt?.toISOString() ?? null,
229:     preguntaExpiraEn: expiraPregunta?.toISOString() ?? null,
230:     ahora: ahora.toISOString(),
231:     segundosRestantes: segundosHasta(intento.expiresAt, ahora),
232:     segundosPreguntaRestantes: segundosHasta(expiraPregunta, ahora),
233:     permitirRevision: intento.quiz.allowReview,
234:     mostrarResultados: intento.quiz.showResults,
235:     modoSeguro: intento.quiz.secureMode,
236:     umbralInfracciones: intento.quiz.infractionThreshold,
237:     accionInfraccion: intento.quiz.infractionAction,
238:     bloquearSinPantallaCompleta: intento.quiz.blockWithoutFullscreen,
239:     respondidas: entradas.filter((entrada) => tieneRespuesta(intento, entrada)).length,
240:   };
241: }
