243: /* ------------------------------------------------------------------ *
244:  * Resultado y revision posterior al envio
245:  * ------------------------------------------------------------------ */
246: 
247: export function resultadoIntentoDto(intento: IntentoCompleto): ResultadoIntentoDto {
248:   const mostrar = intento.quiz.showResults;
249:   const base = {
250:     id: intento.id,
251:     quizId: intento.quizId,
252:     tituloQuiz: intento.quiz.title,
253:     estado: intento.status,
254:     motivo: intento.submitReason,
255:     enviadoEn: intento.submittedAt?.toISOString() ?? null,
256:     mostrar,
257:   };
258: 
259:   if (mostrar === 'NONE' || intento.status !== 'SUBMITTED') {
260:     return {
261:       ...base,
262:       puntaje: null,
263:       puntajeMaximo: null,
264:       nota: null,
265:       aprobada: null,
266:       preguntas: [],
267:     };
268:   }
269: 
270:   const preguntas: ResultadoPreguntaDto[] = [];
271:   if (mostrar === 'SCORE_AND_ANSWERS') {
272:     const entradas = entradasDelIntento(intento);
273:     entradas.forEach((entrada, indice) => {
274:       const respuesta = respuestaDe(intento, entrada.questionId);
275:       const opciones = opcionesEnOrden(intento, entrada);
276:       const mapa = new Map(opciones.map((opcion) => [opcion.id, opcion]));
277:       const respondida = respuesta.opciones.length > 0 || respuesta.texto.trim().length > 0;
278:       const correctas = entrada.question.options.filter((opcion) => opcion.isCorrect);
279:       preguntas.push({
280:         posicion: indice + 1,
281:         preguntaId: entrada.questionId,
282:         enunciado: entrada.question.statement,
283:         tipo: entrada.question.type,
284:         puntos: entrada.points,
285:         puntosObtenidos: intento.answers.find((fila) => fila.questionId === entrada.questionId)
286:           ?.pointsAwarded ?? 0,
287:         correcta:
288:           intento.answers.find((fila) => fila.questionId === entrada.questionId)?.isCorrect ?? false,
289:         respondida,
290:         seleccion: respuesta.opciones.map((id) => {
291:           const opcion = mapa.get(id);
292:           return {
293:             id,
294:             etiqueta: opcion?.label ?? '',
295:             texto: opcion?.text ?? '(opcion eliminada)',
296:           };
297:         }),
298:         textoRespuesta: respuesta.texto || null,
299:         correctas: correctas.map((opcion) => ({
300:           id: opcion.id,
301:           etiqueta: opcion.label,
302:           texto: opcion.text,
303:         })),
304:         explicacion: entrada.question.explanation,
305:       });
306:     });
307:   }
308: 
309:   return {
310:     ...base,
311:     puntaje: intento.score ?? 0,
312:     puntajeMaximo: intento.maxScore,
313:     nota: intento.grade ?? 0,
314:     aprobada: intento.passed ?? false,
315:     preguntas,
316:   };
317: }
318: 
319: export function resumenIntentoDto(intento: IntentoCompleto): ResumenIntentoDto {
320:   const entradas = entradasDelIntento(intento);
321:   return {
322:     total: entradas.length,
323:     respondidas: entradas.filter((entrada) => tieneRespuesta(intento, entrada)).length,
324:     preguntas: entradas.map((entrada, indice) => ({
325:       posicion: indice + 1,
326:       enunciado: entrada.question.statement,
327:       respondida: tieneRespuesta(intento, entrada),
328:     })),
329:   };
330: }
