332: /* ------------------------------------------------------------------ *
333:  * Calificacion (siempre en el servidor)
334:  * ------------------------------------------------------------------ */
335: 
336: function calcularResultado(
337:   entrada: EntradaIntento,
338:   seleccion: string[],
339:   texto: string,
340: ): { correcta: boolean } {
341:   if (entrada.question.type === 'SHORT_ANSWER') {
342:     const normalizada = normalizarTexto(texto);
343:     if (!normalizada) return { correcta: false };
344:     const aceptadas = entrada.question.options
345:       .filter((opcion) => opcion.isCorrect)
346:       .map((opcion) => normalizarTexto(opcion.text));
347:     return { correcta: aceptadas.includes(normalizada) };
348:   }
349: 
350:   const esperadas = entrada.question.options
351:     .filter((opcion) => opcion.isCorrect)
352:     .map((opcion) => opcion.id);
353:   const seleccionadas = new Set(seleccion);
354:   const correcta =
355:     esperadas.length > 0 &&
356:     esperadas.length === seleccionadas.size &&
357:     esperadas.every((id) => seleccionadas.has(id));
358:   return { correcta };
359: }
