361: /** Califica y marca el intento como enviado. Es idempotente si ya estaba enviado. */
362: export async function calificarYEnviar(
363:   intento: IntentoCompleto,
364:   motivo: 'MANUAL' | 'TIME_UP' | 'INFRACTIONS' | 'FORCED',
365: ): Promise<IntentoCompleto> {
366:   if (intento.status === 'SUBMITTED') return intento;
367:   if (intento.status === 'VOIDED') {
368:     throw conflicto('Este intento fue anulado y no se puede enviar.');
369:   }
370: 
371:   const entradas = entradasDelIntento(intento);
372:   const respuestas = new Map(intento.answers.map((fila) => [fila.questionId, fila]));
373:   const ahora = new Date();
374: 
375:   let puntaje = 0;
376:   let maximo = 0;
377:   const calculos = entradas.map((entrada) => {
378:     const respuesta = respuestas.get(entrada.questionId);
379:     const seleccion = respuesta ? leerLista(respuesta.selectedOptions) : [];
380:     const texto = respuesta?.textAnswer ?? '';
381:     const { correcta } = calcularResultado(entrada, seleccion, texto);
382:     const puntos = correcta ? entrada.points : 0;
383:     puntaje += puntos;
384:     maximo += entrada.points;
385:     return { entrada, respuesta, seleccion, texto, correcta, puntos };
386:   });
387: 
388:   const nota =
389:     maximo > 0 ? Math.round((puntaje / maximo) * intento.quiz.maxGrade * 100) / 100 : 0;
390:   const aprobada = nota >= intento.quiz.passingScore;
391: 
392:   await prisma.$transaction(async (tx) => {
393:     for (const calculo of calculos) {
394:       if (calculo.respuesta) {
395:         await tx.answer.update({
396:           where: { id: calculo.respuesta.id },
397:           data: {
398:             selectedOptions: JSON.stringify(calculo.seleccion),
399:             textAnswer: calculo.texto || null,
400:             isCorrect: calculo.correcta,
401:             pointsAwarded: calculo.puntos,
402:             isFinal: true,
403:           },
404:         });
405:       } else {
406:         await tx.answer.create({
407:           data: {
408:             attemptId: intento.id,
409:             questionId: calculo.entrada.questionId,
410:             selectedOptions: '[]',
411:             textAnswer: null,
412:             isCorrect: false,
413:             pointsAwarded: 0,
414:             isFinal: true,
415:           },
416:         });
417:       }
418:     }
419: 
420:     await tx.attempt.update({
421:       where: { id: intento.id },
422:       data: {
423:         status: 'SUBMITTED',
424:         submittedAt: ahora,
425:         submitReason: motivo,
426:         lastSeenAt: ahora,
427:         score: puntaje,
428:         maxScore: maximo,
429:         grade: nota,
430:         passed: aprobada,
431:       },
432:     });
433:   });
434: 
435:   const actualizado = await buscarIntento(intento.id);
436:   if (!actualizado) throw noEncontrado('Intento');
437: 
438:   await auditar({
439:     accion: ACCIONES.INTENTO_ENVIADO,
440:     actorId: intento.studentId,
441:     tipoEntidad: 'Attempt',
442:     entidadId: intento.id,
443:     meta: {
444:       quizId: intento.quizId,
445:       motivo,
446:       puntaje,
447:       maximo,
448:       nota,
449:       aprobada,
450:     },
451:   });
452: 
453:   return actualizado;
454: }
455: 
456: /**
457:  * Aplica los limites de tiempo del lado del servidor:
458:  *  - tiempo total agotado -> envia el intento automaticamente;
459:  *  - tiempo por pregunta agotado -> avanza sola hasta la pregunta vigente;
460:  *  - si se agota el tiempo de la ultima pregunta -> envia el intento.
461:  */
462: export async function resolverTiempos(intento: IntentoCompleto): Promise<IntentoCompleto> {
463:   if (intento.status !== 'IN_PROGRESS') return intento;
464: 
465:   const ahora = new Date();
466:   if (intento.expiresAt && intento.expiresAt.getTime() <= ahora.getTime()) {
467:     return calificarYEnviar(intento, 'TIME_UP');
468:   }
469: 
470:   const limite = intento.quiz.perQuestionTimeSec;
471:   if (!limite) return intento;
472: 
473:   const entradas = entradasDelIntento(intento);
474:   const inicio = intento.questionStartedAt ?? intento.startedAt;
475:   const transcurrido = (ahora.getTime() - inicio.getTime()) / 1000;
476:   if (transcurrido < limite) return intento;
477: 
478:   const pasos = Math.floor(transcurrido / limite);
479:   const nuevaPosicion = intento.currentPosition + pasos;
480:   if (nuevaPosicion >= entradas.length) {
481:     return calificarYEnviar(intento, 'TIME_UP');
482:   }
483: 
484:   const nuevoInicio = new Date(inicio.getTime() + pasos * limite * 1000);
485:   const actualizado = await prisma.attempt.update({
486:     where: { id: intento.id },
487:     data: {
488:       currentPosition: nuevaPosicion,
489:       questionStartedAt: nuevoInicio,
490:       lastSeenAt: ahora,
491:     },
492:     include: INCLUDE_INTENTO,
493:   });
494:   return actualizado;
495: }
496: 
497: /* ------------------------------------------------------------------ *
498:  * Inicio del intento
499:  * ------------------------------------------------------------------ */
500: 
501: export type ResultadoInicio = {
502:   intento: IntentoCompleto;
503:   reanudado: boolean;
504: };
505: 
506: /**
507:  * Crea el intento (o reanuda el que ya esta en progreso). Congela en el
508:  * servidor el orden de preguntas y de opciones, y calcula la expiracion.
509:  */
510: export async function iniciarIntento(
511:   quiz: QuizParaIntento,
512:   estudianteId: string,
513:   ip: string | null,
514:   userAgent: string | null,
515: ): Promise<ResultadoInicio> {
516:   const activo = await prisma.attempt.findFirst({
517:     where: { quizId: quiz.id, studentId: estudianteId, status: 'IN_PROGRESS' },
518:     orderBy: { startedAt: 'desc' },
519:     include: INCLUDE_INTENTO,
520:   });
521:   if (activo) {
522:     const procesado = await resolverTiempos(activo);
523:     if (procesado.status === 'IN_PROGRESS') {
524:       await prisma.attempt.update({
525:         where: { id: procesado.id },
526:         data: { lastSeenAt: new Date() },
527:       });
528:       return { intento: procesado, reanudado: true };
529:     }
530:   }
531: 
532:   const usados = await prisma.attempt.count({
533:     where: {
534:       quizId: quiz.id,
535:       studentId: estudianteId,
536:       status: { in: ['SUBMITTED', 'VOIDED'] },
537:     },
538:   });
539:   if (usados >= quiz.maxAttempts) {
540:     throw new ErrorApi(
541:       409,
542:       'SIN_INTENTOS',
543:       'Ya usaste todos los intentos permitidos para este quiz.',
544:     );
545:   }
546: 
547:   const ultimo = await prisma.attempt.findFirst({
548:     where: { quizId: quiz.id, studentId: estudianteId },
549:     orderBy: { attemptNumber: 'desc' },
550:     select: { attemptNumber: true },
551:   });
552: 
553:   let orden = [...quiz.questions];
554:   if (quiz.questionCount && quiz.questionCount < orden.length) {
555:     orden = barajar(orden).slice(0, quiz.questionCount);
556:   }
557:   if (quiz.shuffleQuestions) {
558:     orden = barajar(orden);
559:   } else {
560:     orden.sort((a, b) => a.position - b.position);
561:   }
562: 
563:   const optionOrder: Record<string, string[]> = {};
564:   for (const entrada of orden) {
565:     const ids = entrada.question.options
566:       .slice()
567:       .sort((a, b) => a.position - b.position)
568:       .map((opcion) => opcion.id);
569:     optionOrder[entrada.questionId] = quiz.shuffleOptions ? barajar(ids) : ids;
570:   }
571: 
572:   const ahora = new Date();
573:   let expira: Date | null = quiz.timeLimitSec
574:     ? new Date(ahora.getTime() + quiz.timeLimitSec * 1000)
575:     : null;
576:   if (quiz.availableTo && (!expira || quiz.availableTo.getTime() < expira.getTime())) {
577:     expira = new Date(quiz.availableTo);
578:   }
579: 
580:   const maxScore = orden.reduce((suma, entrada) => suma + entrada.points, 0);
581: 
582:   const creado = await prisma.attempt.create({
583:     data: {
584:       quizId: quiz.id,
585:       studentId: estudianteId,
586:       attemptNumber: (ultimo?.attemptNumber ?? 0) + 1,
587:       status: 'IN_PROGRESS',
588:       startedAt: ahora,
589:       lastSeenAt: ahora,
590:       questionStartedAt: ahora,
