1: /**
2:  * Rate limiting en memoria (ventana deslizante por cubos).
3:  *
4:  * Limitacion honesta: es un limiter por proceso. Con varias instancias de
5:  * Next.js o serverless cada instancia tiene su propio contador. Para
6:  * produccion en varias instancias se debe usar Redis/Upstash. Se documenta
7:  * en el README.
8:  */
9: 
10: type Cubo = { conteo: number; expira: number };
11: 
12: const cubos = new Map<string, Cubo>();
13: let ultimaLimpieza = Date.now();
14: 
15: function limpiar(): void {
16:   const ahora = Date.now();
17:   if (ahora - ultimaLimpieza < 60_000) return;
18:   ultimaLimpieza = ahora;
19:   for (const [clave, cubo] of cubos) {
20:     if (cubo.expira <= ahora) cubos.delete(clave);
21:   }
22: }
23: 
24: export type ResultadoLimite = {
25:   permitido: boolean;
26:   restantes: number;
27:   reintentarEn: number;
28: };
29: 
30: export function limitar(clave: string, max: number, ventanaSeg: number): ResultadoLimite {
31:   limpiar();
32:   const ahora = Date.now();
33:   const actual = cubos.get(clave);
34: 
35:   if (!actual || actual.expira <= ahora) {
36:     cubos.set(clave, { conteo: 1, expira: ahora + ventanaSeg * 1000 });
37:     return { permitido: true, restantes: Math.max(max - 1, 0), reintentarEn: 0 };
38:   }
39: 
40:   actual.conteo += 1;
41:   if (actual.conteo > max) {
42:     return {
43:       permitido: false,
44:       restantes: 0,
45:       reintentarEn: Math.ceil((actual.expira - ahora) / 1000),
46:     };
47:   }
48:   return { permitido: true, restantes: max - actual.conteo, reintentarEn: 0 };
49: }
50: 
51: /** Reinicia un contador (por ejemplo tras un login correcto). */
52: export function reiniciarLimite(clave: string): void {
53:   cubos.delete(clave);
54: }
55: 
56: /** Solo para pruebas. */
57: export function _reiniciarTodo(): void {
58:   cubos.clear();
59: }

