6: export class ErrorPeticion extends Error {
7:   readonly codigo: string;
8:   readonly estado: number;
9:   readonly campos?: Record<string, string>;
10: 
11:   constructor(estado: number, codigo: string, mensaje: string, campos?: Record<string, string>) {
12:     super(mensaje);
13:     this.name = 'ErrorPeticion';
14:     this.estado = estado;
15:     this.codigo = codigo;
16:     this.campos = campos;
17:   }
18: }
19: 
20: /** Token CSRF de la cookie, necesario para subidas con XMLHttpRequest. */
21: export function leerTokenCsrf(): string | null {
22:   return leerCookie('qc_csrf');
23: }
24: 
25: function leerCookie(nombre: string): string | null {
26:   if (typeof document === 'undefined') return null;
27:   const partes = document.cookie.split(';').map((p) => p.trim());
28:   for (const parte of partes) {
29:     const [clave, ...resto] = parte.split('=');
30:     if (clave === nombre) return decodeURIComponent(resto.join('='));
31:   }
32:   return null;
33: }
34: 
35: type Opciones = Omit<RequestInit, 'body'> & { cuerpo?: unknown; cuerpoCrudo?: BodyInit };
36: 
37: export async function peticion<T>(url: string, opciones: Opciones = {}): Promise<T> {
38:   const { cuerpo, cuerpoCrudo, headers, ...resto } = opciones;
39:   const metodo = (opciones.method ?? 'GET').toUpperCase();
40:   const cabeceras = new Headers(headers);
41: 
42:   if (cuerpo !== undefined && !cabeceras.has('content-type')) {
43:     cabeceras.set('content-type', 'application/json');
44:   }
45:   if (metodo !== 'GET' && metodo !== 'HEAD') {
46:     const csrf = leerCookie('qc_csrf');
47:     if (csrf) cabeceras.set('x-csrf-token', csrf);
48:   }
49: 
50:   const respuesta = await fetch(url, {
51:     ...resto,
52:     method: metodo,
53:     headers: cabeceras,
54:     credentials: 'same-origin',
55:     body: cuerpoCrudo ?? (cuerpo !== undefined ? JSON.stringify(cuerpo) : undefined),
56:   });
57: 
58:   const tipo = respuesta.headers.get('content-type') ?? '';
59:   const esJson = tipo.includes('application/json');
60:   const payload = esJson ? await respuesta.json() : await respuesta.text();
61: 
62:   if (!respuesta.ok) {
63:     if (esJson && payload && typeof payload === 'object' && 'error' in payload) {
64:       const error = (payload as { error: { codigo: string; mensaje: string; campos?: Record<string, string> } }).error;
65:       throw new ErrorPeticion(respuesta.status, error.codigo, error.mensaje, error.campos);
66:     }
67:     throw new ErrorPeticion(respuesta.status, 'ERROR_DESCONOCIDO', 'Ocurrio un error inesperado.');
68:   }
69: 
70:   if (esJson && payload && typeof payload === 'object' && 'datos' in payload) {
71:     return (payload as { datos: T }).datos;
72:   }
73:   return payload as T;
74: }
75: 
76: export const api = {
77:   get: <T>(url: string) => peticion<T>(url, { method: 'GET' }),
78:   post: <T>(url: string, cuerpo?: unknown) => peticion<T>(url, { method: 'POST', cuerpo }),
79:   patch: <T>(url: string, cuerpo?: unknown) => peticion<T>(url, { method: 'PATCH', cuerpo }),
80:   put: <T>(url: string, cuerpo?: unknown) => peticion<T>(url, { method: 'PUT', cuerpo }),
81:   del: <T>(url: string, cuerpo?: unknown) => peticion<T>(url, { method: 'DELETE', cuerpo }),
82: };

