export async function guardarRespuesta(
  intento: IntentoCompleto,
  datos: { preguntaId: string; opciones: string[]; texto?: string | null },
): Promise<IntentoCompleto> {
  if (intento.status !== 'IN_PROGRESS') throw conflicto('El intento ya no esta en progreso.');
  const entradas = entradasDelIntento(intento);
  if (entradas.length === 0) throw conflicto('El intento no tiene preguntas.');
  const posicion = Math.min(Math.max(intento.currentPosition, 0), entradas.length - 1);
  const entrada = entradas[posicion];
  if (!entrada || entrada.questionId !== datos.preguntaId) {
    throw new ErrorApi(409, 'PREGUNTA_FUERA_DE_TURNO', 'Solo puedes responder la pregunta que estas viendo.');
  }

  let opciones: string[] = [];
  let texto: string | null = null;

  if (entrada.question.type === 'SHORT_ANSWER') {
    texto = (datos.texto ?? '').trim().slice(0, 1000) || null;
    if (datos.opciones.length > 0) opciones = [];
  } else {
    const validas = new Set(entrada.question.options.map((o) => o.id));
    opciones = [...new Set(datos.opciones)].filter((id) => validas.has(id));
    if (opciones.length === 0) texto = null;
    const maxSel = entrada.question.type === 'MCQ_MULTI' ? validas.size : 1;
    opciones = opciones.slice(0, maxSel);
  }

  await prisma.answer.upsert({
    where: { attemptId_questionId: { attemptId: intento.id, questionId: entrada.questionId } },
    create: { attemptId: intento.id, questionId: entrada.questionId, selectedOptions: JSON.stringify(opciones), textAnswer: texto, isFinal: false },
    update: { selectedOptions: JSON.stringify(opciones), textAnswer: texto, isFinal: false },
  });
  await prisma.attempt.update({ where: { id: intento.id }, data: { lastSeenAt: new Date() } });
  return (await buscarIntento(intento.id))!;
}
```

