        </p>
      </div>

      {quices.length === 0 ? (
        <Vacio mensaje="Todavia no tienes quices asignados. Cuando tu docente publique uno para tu grupo, aparecera aqui." />
      ) : (
        <>
          <Seccion
            titulo="En progreso"
            descripcion="Tienes un intento sin terminar. Reanudalo para continuar donde lo dejaste."
            quices={enProgreso}
          />
          <Seccion
            titulo="Disponibles ahora"
            descripcion="Puedes presentarlos en este momento."
            quices={disponibles}
          />
          <Seccion
            titulo="Proximos"
            descripcion="Se habilitaran en la fecha indicada."
            quices={proximos}
          />
          <Seccion
            titulo="Completados"
            descripcion="Ya usaste todos los intentos permitidos."
            quices={completados}
          />
          <Seccion
            titulo="Cerrados"
            descripcion="Su ventana de disponibilidad termino."
            quices={cerrados}
          />
        </>
      )}

      <p className="text-xs text-slate-500">
        La navegacion del quiz la define tu docente:{' '}
        {ETIQUETA_MODO_NAVEGACION.FORWARD_ONLY} o {ETIQUETA_MODO_NAVEGACION.FREE}. Resultados:{' '}
        {ETIQUETA_MODO_RESULTADO.SCORE} / {ETIQUETA_MODO_RESULTADO.SCORE_AND_ANSWERS} segun la
        configuracion.{' '}
        <Link href="/panel" className="font-medium text-brand-700 underline">
          Volver al panel
        </Link>
      </p>
      {/* Tipos usados para claridad del modo de navegacion y resultado. */}
      <span className="sr-only">
        {([ 'FORWARD_ONLY', 'FREE' ] as ModoNavegacion[]).join(' ')}
        {' '}
        {([ 'NONE', 'SCORE', 'SCORE_AND_ANSWERS' ] as ModoResultado[]).join(' ')}
      </span>
    </div>
  );
}

