const tab = await tools.browser.tabs.open({ url: 'http://127.0.0.1:3000/login', focus: true });
const login = await tools.browser.evaluate({
  tabID: tab.id,
  script: `(async () => {
    const r = await fetch('/api/auth/login', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ correo: 'estudiante1@colegio.edu', contrasena: 'Estudiante123!' }) });
    const html = await (await fetch('/estudiante/quices')).text();
    const m = html.match(/\\/estudiante\\/quices\\/([a-z0-9]+)"/);
    const csrf = document.cookie.split(';').map(s => s.trim()).find(s => s.startsWith('qc_csrf='));
    return { ok: r.ok, quizId: m ? m[1] : null, csrf: Boolean(csrf) };
  })()`
});
return { tabID: tab.id, login: login.value };

const tab = await tools.browser.tabs.open({ url: 'http://127.0.0.1:3000/api/auth/me', focus: true });
const antes = await tools.browser.evaluate({ tabID: tab.id, script: `document.cookie` });
const limpio = await tools.browser.evaluate({
  tabID: tab.id,
  script: `(() => { document.cookie.split(';').forEach(c => { const n = c.split('=')[0].trim(); document.cookie = n + '=; expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/'; }); return document.cookie; })()`
});
const lista = await tools.browser.tabs.list();
return { tabID: tab.id, antes: antes.value, limpio: limpio.value, tabs: lista.tabs.map(t => t.url) };

