      setIniciado(true);
      setEnPantallaCompleta(true);
      setPausado(false);
      setMensajePausa(null);
      emitir('FULLSCREEN_ENTER');
    } catch {
      setMensajePausa('No se pudo activar la pantalla completa. Vuelve a intentarlo.');
    }
  }, [emitir]);
