183:   banco: PreguntaDto[];
184:   grupos: GrupoQuizDto[];
185: }) {
186:   const [quiz, setQuiz] = useState(inicial);
187:   const [form, setForm] = useState<Formulario>(() => formularioDesde(inicial));
188:   const [seleccionadas, setSeleccionadas] = useState<Seleccion[]>(() => seleccionDesde(inicial));
189:   const [tab, setTab] = useState<'configuracion' | 'preguntas' | 'revision'>('configuracion');
190:   const [sucio, setSucio] = useState(false);
191:   const [preguntasSucias, setPreguntasSucias] = useState(false);
192:   const [guardando, setGuardando] = useState(false);
193:   const [publicando, setPublicando] = useState(false);
194:   const [cerrando, setCerrando] = useState(false);
195:   const [mensaje, setMensaje] = useState<{ tipo: 'exito' | 'error' | 'aviso'; texto: string } | null>(
196:     null,
197:   );
198:   const [confirmoRevision, setConfirmoRevision] = useState(false);
199:   const [mostrarBanco, setMostrarBanco] = useState(false);
200:   const [buscarBanco, setBuscarBanco] = useState('');
201:   const [tipoBanco, setTipoBanco] = useState<'TODOS' | TipoPregunta>('TODOS');
202:   const [expandida, setExpandida] = useState<string | null>(null);
203: 
204:   const bloqueado = quiz.estado === 'CLOSED';
205:   const intentosRegistrados = quiz.intentos > 0;
206: 
207:   const mapaPreguntas = useMemo(() => {
208:     const mapa = new Map<string, PreguntaVista>();
209:     for (const pregunta of banco) mapa.set(pregunta.id, preguntaDesdeDto(pregunta));
210:     for (const pregunta of quiz.preguntas) mapa.set(pregunta.preguntaId, preguntaDesdeQuiz(pregunta));
211:     return mapa;
212:   }, [banco, quiz.preguntas]);
213: 
214:   const seleccionDetalle = useMemo(
215:     () =>
216:       seleccionadas.map((seleccion, indice) => ({
217:         ...seleccion,
218:         posicion: indice + 1,
219:         datos: mapaPreguntas.get(seleccion.id),
220:       })),
221:     [seleccionadas, mapaPreguntas],
222:   );
223: 
224:   const totalPuntos = useMemo(
225:     () => seleccionadas.reduce((suma, pregunta) => suma + (Number(pregunta.puntos) || 0), 0),
226:     [seleccionadas],
227:   );
228: 
229:   const bancoFiltrado = useMemo(() => {
230:     const termino = buscarBanco.trim().toLowerCase();
231:     return banco
232:       .map(preguntaDesdeDto)
233:       .filter((pregunta) => {
234:         if (tipoBanco !== 'TODOS' && pregunta.tipo !== tipoBanco) return false;
235:         if (termino && !pregunta.enunciado.toLowerCase().includes(termino)) return false;
236:         return true;
237:       })
238:       .sort((a, b) => a.enunciado.localeCompare(b.enunciado, 'es'));
239:   }, [banco, buscarBanco, tipoBanco]);
240: 
241:   const revisionLocal = useMemo(() => {
242:     const errores: string[] = [];
243:     const advertencias: string[] = [];
244: 
245:     if (form.titulo.trim().length < 5) {
246:       errores.push('El titulo debe tener al menos 5 caracteres.');
247:     }
248:     if (form.grupoIds.length === 0) {
249:       errores.push('Asigna el quiz a por lo menos un grupo.');
250:     }
251:     if (seleccionadas.length === 0) {
252:       errores.push('Agrega al menos una pregunta.');
253:     }
254: 
255:     const sinRespuesta = seleccionadas.filter((seleccion) => {
256:       const pregunta = mapaPreguntas.get(seleccion.id);
257:       if (!pregunta) return true;
258:       return pregunta.respuestaPendiente || !pregunta.opciones.some((opcion) => opcion.correcta);
259:     });
260:     if (sinRespuesta.length > 0) {
261:       errores.push(
262:         `${sinRespuesta.length} pregunta(s) no tienen una respuesta correcta confirmada.`,
263:       );
264:     }
265: 
266:     if (Number(form.notaAprobacion) > Number(form.notaMaxima)) {
267:       errores.push('La nota minima de aprobacion no puede superar la nota maxima.');
268:     }
269: 
270:     if (form.fechaDesde && form.fechaHasta) {
271:       const desde = new Date(form.fechaDesde);
272:       const hasta = new Date(form.fechaHasta);
273:       if (hasta <= desde) {
274:         errores.push('La fecha de cierre debe ser posterior a la fecha de apertura.');
275:       }
276:       if (hasta.getTime() <= Date.now()) {
277:         errores.push('La fecha de cierre ya paso.');
278:       }
279:     }
280: 
281:     if (form.cantidadPreguntas && Number(form.cantidadPreguntas) > seleccionadas.length) {
282:       errores.push(
283:         `Se piden ${form.cantidadPreguntas} preguntas por intento pero solo hay ${seleccionadas.length}.`,
284:       );
285:     }
286: 
287:     const pendientes = seleccionadas.filter(
288:       (seleccion) => mapaPreguntas.get(seleccion.id)?.estado === 'PENDING_REVIEW',
289:     ).length;
290:     if (pendientes > 0) {
291:       advertencias.push(
292:         `${pendientes} pregunta(s) estan pendientes de revision. Al publicar quedaran aprobadas.`,
293:       );
294:     }
295: 
296:     return { errores, advertencias };
297:   }, [form, seleccionadas, mapaPreguntas]);
298: 
299:   function actualizar<K extends keyof Formulario>(campo: K, valor: Formulario[K]) {
300:     setForm((actual) => ({ ...actual, [campo]: valor }));
301:     setSucio(true);
302:   }
303: 
304:   function alternarGrupo(id: string, activo: boolean) {
305:     actualizar(
306:       'grupoIds',
307:       activo ? Array.from(new Set([...form.grupoIds, id])) : form.grupoIds.filter((g) => g !== id),
308:     );
309:   }
310: 
311:   function agregarPregunta(id: string) {
312:     if (seleccionadas.some((seleccion) => seleccion.id === id)) return;
313:     setSeleccionadas((actual) => [...actual, { id, puntos: Number(form.puntosPorDefecto) || 1 }]);
314:     setPreguntasSucias(true);
315:     setSucio(true);
316:   }
317: 
318:   function quitarPregunta(id: string) {
319:     setSeleccionadas((actual) => actual.filter((seleccion) => seleccion.id !== id));
320:     setPreguntasSucias(true);
321:     setSucio(true);
322:   }
323: 
324:   function moverPregunta(indice: number, direccion: -1 | 1) {
325:     const destino = indice + direccion;
326:     if (destino < 0 || destino >= seleccionadas.length) return;
327:     const copia = [...seleccionadas];
328:     const [movida] = copia.splice(indice, 1);
329:     copia.splice(destino, 0, movida!);
330:     setSeleccionadas(copia);
331:     setPreguntasSucias(true);
332:     setSucio(true);
333:   }
334: 
335:   function cambiarPuntos(id: string, valor: number) {
336:     setSeleccionadas((actual) =>
337:       actual.map((seleccion) =>
338:         seleccion.id === id ? { ...seleccion, puntos: Math.max(0.1, Number(valor) || 0.1) } : seleccion,
339:       ),
340:     );
341:     setPreguntasSucias(true);
342:     setSucio(true);
343:   }
344: 
345:   function construirPayload() {
346:     return {
347:       titulo: form.titulo.trim(),
348:       descripcion: form.descripcion.trim() || null,
349:       grupoIds: form.grupoIds,
350:       fechaDisponibleDesde: form.fechaDesde ? new Date(form.fechaDesde).toISOString() : null,
351:       fechaDisponibleHasta: form.fechaHasta ? new Date(form.fechaHasta).toISOString() : null,
352:       navegacion: form.navegacion,
353:       tiempoTotalSeg: form.tiempoTotalMin ? Math.round(Number(form.tiempoTotalMin) * 60) : null,
354:       tiempoPorPreguntaSeg: form.tiempoPorPregunta ? Math.round(Number(form.tiempoPorPregunta)) : null,
355:       mezclarPreguntas: form.mezclarPreguntas,
356:       mezclarOpciones: form.mezclarOpciones,
357:       intentosMaximos: Number(form.intentosMaximos),
358:       cantidadPreguntas: form.cantidadPreguntas ? Number(form.cantidadPreguntas) : null,
359:       puntosPorDefecto: Number(form.puntosPorDefecto),
360:       notaAprobacion: Number(form.notaAprobacion),
361:       notaMaxima: Number(form.notaMaxima),
362:       mostrarResultados: form.mostrarResultados,
363:       permitirRevision: form.permitirRevision,
364:       modoSeguro: form.modoSeguro,
365:       umbralInfracciones: Number(form.umbralInfracciones),
366:       accionInfraccion: form.accionInfraccion,
367:       bloquearSinPantallaCompleta: form.bloquearSinPantallaCompleta,
368:     };
369:   }
370: 
371:   function aplicarRespuesta(actualizado: QuizDetalleDto) {
372:     setQuiz(actualizado);
373:     setForm(formularioDesde(actualizado));
374:     setSeleccionadas(seleccionDesde(actualizado));
375:     setSucio(false);
376:     setPreguntasSucias(false);
377:   }
378: 
379:   async function guardar(mostrarMensaje = true): Promise<boolean> {
380:     setGuardando(true);
381:     setMensaje(null);
382:     try {
383:       let respuesta = await api.patch<{ quiz: QuizDetalleDto }>(
384:         `/api/quices/${quiz.id}`,
385:         construirPayload(),
386:       );
387: 
388:       if (preguntasSucias) {
389:         respuesta = await api.put<{ quiz: QuizDetalleDto }>(`/api/quices/${quiz.id}/preguntas`, {
390:           preguntas: seleccionadas.map((seleccion) => ({
391:             id: seleccion.id,
392:             puntos: Number(seleccion.puntos),
393:           })),
394:         });
395:       }
396: 
397:       aplicarRespuesta(respuesta.quiz);
398:       if (mostrarMensaje) {
399:         setMensaje({ tipo: 'exito', texto: 'Cambios guardados correctamente.' });
400:       }
401:       return true;
402:     } catch (fallo) {
403:       const detalle = fallo instanceof ErrorPeticion ? fallo.campos : null;
404:       const campos = detalle && typeof detalle === 'object' ? Object.values(detalle).flat() : [];
405:       setMensaje({
406:         tipo: 'error',
407:         texto:
408:           fallo instanceof ErrorPeticion
409:             ? [fallo.message, ...campos.filter((valor) => typeof valor === 'string')].join(' ')
410:             : 'No se pudieron guardar los cambios.',
411:       });
412:       return false;
413:     } finally {
414:       setGuardando(false);
415:     }
416:   }
417: 
418:   async function publicar() {
419:     setPublicando(true);
420:     setMensaje(null);
421:     try {
422:       if (sucio || preguntasSucias) {
423:         const guardado = await guardar(false);
424:         if (!guardado) return;
425:       }
426:       const respuesta = await api.post<{ quiz: QuizDetalleDto }>(
427:         `/api/quices/${quiz.id}/publicar`,
428:         { confirmoRevision: true },
