466:     } catch (fallo) {
467:       setMensaje({
468:         tipo: 'error',
469:         texto: fallo instanceof ErrorPeticion ? fallo.message : 'No se pudo cerrar el quiz.',
470:       });
471:     } finally {
472:       setCerrando(false);
473:     }
474:   }
