58: type ContextoRuta<P> = { params: Promise<P> };
59: 
60: /**
61:  * Envuelve un handler de route de Next para capturar errores y
62:  * validar automaticamente.
63:  */
64: export function ruta<P = Record<string, never>>(
65:   fn: (req: NextRequest, ctx: ContextoRuta<P>) => Promise<NextResponse> | NextResponse,
66: ) {
67:   return async (req: NextRequest, ctx: ContextoRuta<P>): Promise<NextResponse> => {
68:     try {
69:       return await fn(req, ctx);
70:     } catch (error) {
71:       return respuestaError(error);
72:     }
73:   };
74: }
