123: /**
124:  * Reglas de negocio para publicar. Devuelve errores (bloquean) y
125:  * advertencias (se muestran pero permiten publicar).
126:  */
127: export function validarPublicacion(quiz: QuizConRelaciones): {
128:   errores: string[];
129:   advertencias: string[];
130: } {
131:   const errores: string[] = [];
132:   const advertencias: string[] = [];
133: 
134:   if (quiz.questions.length === 0) {
135:     errores.push('El quiz debe tener al menos una pregunta.');
136:   }
137:   if (quiz.assignments.length === 0) {
138:     errores.push('Asigna el quiz a por lo menos un grupo antes de publicarlo.');
139:   }
140:   if (quiz.passingScore > quiz.maxGrade) {
141:     errores.push('La nota minima de aprobacion no puede superar la nota maxima.');
142:   }
143:   if (quiz.availableFrom && quiz.availableTo && quiz.availableTo <= quiz.availableFrom) {
144:     errores.push('La fecha de cierre debe ser posterior a la fecha de apertura.');
145:   }
146:   if (quiz.availableTo && quiz.availableTo.getTime() <= Date.now()) {
147:     errores.push('La fecha de cierre ya paso: actualiza la ventana de disponibilidad.');
148:   }
149:   if (quiz.questionCount && quiz.questionCount > quiz.questions.length) {
150:     errores.push(
151:       `Se piden ${quiz.questionCount} preguntas por intento pero el quiz solo tiene ${quiz.questions.length}.`,
152:     );
153:   }
154: 
155:   const sinRespuesta = quiz.questions.filter((entrada) => {
156:     if (entrada.question.answerPending) return true;
157:     return !entrada.question.options.some((opcion) => opcion.isCorrect);
158:   });
159:   if (sinRespuesta.length > 0) {
160:     errores.push(
161:       `${sinRespuesta.length} pregunta(s) no tienen una respuesta correcta confirmada. Editalas antes de publicar.`,
162:     );
163:   }
164: 
165:   const pendientes = quiz.questions.filter(
166:     (entrada) => entrada.question.status === 'PENDING_REVIEW',
167:   ).length;
168:   if (pendientes > 0) {
169:     advertencias.push(
170:       `${pendientes} pregunta(s) estaban pendientes de revision. Al publicar quedaran marcadas como aprobadas.`,
171:     );
172:   }
173: 
174:   if (quiz.secureMode && !quiz.blockWithoutFullscreen) {
175:     advertencias.push(
176:       'El modo seguro esta activo pero no bloquea navegadores sin pantalla completa: la proteccion sera menor.',
177:     );
178:   }
179: 
180:   return { errores, advertencias };
181: }

