```ts
import { NextResponse } from 'next/server';
import { ruta, noEncontrado, infoCliente, solicitudInvalida } from '@/lib/http';
import { requiereRolApi } from '@/lib/auth/guard';
import { obtenerQuizAutorizado } from '@/lib/quices/servicio';
import { obtenerReporteQuiz } from '@/lib/reportes/servicio';
import {
  construirCsv, construirExcel, filasResumen, filasEstudiantes, filasPreguntas, filasOpciones, nombreArchivo,
} from '@/lib/reportes/exportar';
import { auditar, ACCIONES } from '@/lib/audit';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

type Ctx = { params: Promise<{ id: string }> };

export const GET = ruta<Ctx['params']>(async (req, ctx) => {
  const sesion = await requiereRolApi('ADMIN', 'TEACHER');
  const { id } = await ctx.params;
  const quiz = await obtenerQuizAutorizado(id, sesion.usuario);
  const reporte = await obtenerReporteQuiz(quiz.id);
  if (!reporte) throw noEncontrado('Quiz');

  const url = new URL(req.url);
  const formato = url.searchParams.get('formato') === 'excel' ? 'excel' : 'csv';
  const tabla = url.searchParams.get('tabla') ?? 'estudiantes';
  const { ip } = infoCliente(req);

  await auditar({ accion: ACCIONES.REPORTE_EXPORTADO, actorId: sesion.usuario.id, tipoEntidad: 'Quiz', entidadId: quiz.id, meta: { formato, tabla }, ip });

  const cabeceras = (nombre, tipo) => ({
    'Content-Type': tipo,
    'Content-Disposition': `attachment; filename="${nombre}"`,
    'Cache-Control': 'no-store',
  });

  if (formato === 'excel') {
    const contenido = construirExcel([
      { nombre: 'Resumen', filas: filasResumen(reporte) },
      { nombre: 'Estudiantes', filas: filasEstudiantes(reporte) },
      { nombre: 'Preguntas', filas: filasPreguntas(reporte) },
      { nombre: 'Opciones', filas: filasOpciones(reporte) },
    ]);
    return new NextResponse(contenido, { headers: cabeceras(nombreArchivo(reporte.titulo, 'reporte', 'xls'), 'application/vnd.ms-excel; charset=utf-8') });
  }

  const mapa = {
    estudiantes: { filas: filasEstudiantes(reporte), sufijo: 'estudiantes' },
    preguntas: { filas: filasPreguntas(reporte), sufijo: 'preguntas' },
    opciones: { filas: filasOpciones(reporte), sufijo: 'opciones' },
    resumen: { filas: filasResumen(reporte), sufijo: 'resumen' },
  } as const;
  const seleccion = mapa[tabla as keyof typeof mapa];
  if (!seleccion) throw solicitudInvalida('La tabla solicitada no es valida.');

  const contenido = construirCsv(seleccion.filas);
  return new NextResponse(contenido, { headers: cabeceras(nombreArchivo(reporte.titulo, seleccion.sufijo, 'csv'), 'text/csv; charset=utf-8') });
});
```

