input.content:
# Pruebas de humo de la Fase 6: reportes y exportacion
$ErrorActionPreference = 'Stop'
$base = 'http://127.0.0.1:3000'
$tmp = $env:TEMP
$jarAdmin = Join-Path $tmp 'qc-f6-admin.txt'
$jarDocente = Join-Path $tmp 'qc-f6-docente.txt'
$jarDocente2 = Join-Path $tmp 'qc-f6-docente2.txt'
$jarEst1 = Join-Path $tmp 'qc-f6-est1.txt'
$jarEst2 = Join-Path $tmp 'qc-f6-est2.txt'
Remove-Item $jarAdmin, $jarDocente, $jarDocente2, $jarEst1, $jarEst2 -ErrorAction SilentlyContinue

$resultados = @()
function Anota($nombre, $ok, $detalle) {
  $script:resultados += [pscustomobject]@{ Prueba = $nombre; Ok = [bool]$ok; Detalle = $detalle }
}
function EscribeJson($ruta, $texto) {
  [System.IO.File]::WriteAllText($ruta, $texto, (New-Object System.Text.UTF8Encoding($false)))
}
function LeerCookie($jar, $nombre) {
  if (-not (Test-Path $jar)) { return $null }
  foreach ($linea in Get-Content $jar) {
    $limpia = $linea -replace '^#HttpOnly_', ''
    if ($limpia.StartsWith('#') -or $limpia.Trim() -eq '') { continue }
    $partes = $limpia -split "`t"
    if ($partes.Count -ge 7 -and $partes[5] -eq $nombre) { return $partes[6] }
  }
  return $null
}
function Login($correo, $clave, $jar) {
  $cuerpo = Join-Path $tmp ('qc-f6-login-' + ($correo -replace '[^a-z0-9]', '') + '.json')
  EscribeJson $cuerpo ("{""correo"":""$correo"",""contrasena"":""$clave""}")
  $salida = (& curl.exe -s -c $jar -w "|%{http_code}" -X POST "$base/api/auth/login" -H "Content-Type: application/json" --data-binary "@$cuerpo") -join "`n"
  $i = $salida.LastIndexOf('|')
  return @{ estado = $salida.Substring($i + 1); cuerpo = $salida.Substring(0, $i) }
}
function Llamar($metodo, $url, $jar, $csrf, $cuerpo) {
  $argumentos = @('-s', '-b', $jar, '-w', '|%{http_code}', '-X', $metodo, $url)
  if ($csrf) { $argumentos += @('-H', "x-csrf-token: $csrf") }
  if ($cuerpo) { $argumentos += @('-H', 'Content-Type: application/json', '--data-binary', "@$cuerpo") }
  $salida = (& curl.exe @argumentos) -join "`n"
  $i = $salida.LastIndexOf('|')
  return @{ estado = $salida.Substring($i + 1); cuerpo = $salida.Substring(0, $i) }
}
function Descargar($url, $jar, $archivo) {
  $cabeceras = Join-Path $tmp 'qc-f6-cabeceras.txt'
  $codigo = (& curl.exe -s -b $jar -D $cabeceras -o $archivo -w "%{http_code}" $url)
  $tipo = ''
  foreach ($linea in (Get-Content $cabeceras -ErrorAction SilentlyContinue)) {
    if ($linea -match '(?i)^content-type:\s*(.+)$') { $tipo = $Matches[1].Trim() }
  }
  $contenido = if (Test-Path $archivo) { [System.IO.File]::ReadAllText($archivo) } else { '' }
  return @{ estado = $codigo; tipo = $tipo; contenido = $contenido }
}
function Cuerpo($json) {
  $ruta = Join-Path $tmp 'qc-f6-cuerpo.json'
  EscribeJson $ruta $json
  return $ruta
}
function Datos($cuerpo) { return ($cuerpo | ConvertFrom-Json).datos }

# --- Sesiones --------------------------------------------------------------
$r = Login 'admin@colegio.edu' 'Admin123!' $jarAdmin
$csrfAdmin = LeerCookie $jarAdmin 'qc_csrf'
Anota 'Login del administrador' ($r.estado -eq '200' -and $csrfAdmin) "status=$($r.estado)"
$r = Login 'docente@colegio.edu' 'Docente123!' $jarDocente
$csrfDoc = LeerCookie $jarDocente 'qc_csrf'
Anota 'Login del docente autor' ($r.estado -eq '200' -and $csrfDoc) "status=$($r.estado)"
Login 'estudiante1@colegio.edu' 'Estudiante123!' $jarEst1 | Out-Null
$csrf1 = LeerCookie $jarEst1 'qc_csrf'
Login 'estudiante2@colegio.edu' 'Estudiante123!' $jarEst2 | Out-Null
$csrf2 = LeerCookie $jarEst2 'qc_csrf'
Anota 'Sesiones de estudiantes iniciadas' ($csrf1 -and $csrf2)

# --- Docente auxiliar (no autor) -------------------------------------------
$marca = Get-Date -Format 'HHmmss'
$r = Llamar 'POST' "$base/api/admin/usuarios" $jarAdmin $csrfAdmin (Cuerpo (ConvertTo-Json @{
  nombre = 'Docente Auxiliar 6'; correo = "auxiliar6-$marca@colegio.edu"; contrasena = 'Auxiliar123!'; rol = 'TEACHER'; activo = $true; grupos = @()
}))
Anota 'Crear docente auxiliar para la prueba de autorizacion' ($r.estado -eq '201') "status=$($r.estado)"
Login "auxiliar6-$marca@colegio.edu" 'Auxiliar123!' $jarDocente2 | Out-Null
$csrfDoc2 = LeerCookie $jarDocente2 'qc_csrf'

# --- Quiz demo y mapa de respuestas ----------------------------------------
$r = Llamar 'GET' "$base/api/quices" $jarDocente $null $null
$demo = (Datos $r.cuerpo).quices | Where-Object { $_.titulo -like '*sistema solar*' } | Select-Object -First 1
$demoId = $demo.id
Anota 'Quiz demo localizado' ([bool]$demoId) "id=$demoId"
$r = Llamar 'GET' "$base/api/quices/$demoId" $jarDocente $null $null
$detalle = (Datos $r.cuerpo).quiz
$mapa = @{}
foreach ($p in $detalle.preguntas) {
  $mapa[$p.preguntaId] = @($p.opciones | Where-Object { $_.correcta } | ForEach-Object { $_.id })
}
Anota 'Mapa de respuestas correctas (5 preguntas)' ($mapa.Count -eq 5) "count=$($mapa.Count)"

function ResolverIntento($jar, $csrf, $acertar) {
  $r = Llamar 'POST' "$base/api/intentos" $jar $csrf (Cuerpo ("{""quizId"":""$demoId""}"))
  $estado = (Datos $r.cuerpo).estado
  $id = $estado.id
  for ($paso = 0; $paso -lt 5; $paso++) {
    $p = $estado.pregunta
    if (-not $p) { break }
    if ($p.tipo -eq 'SHORT_ANSWER') {
      $texto = if ($acertar) { 'Sol' } else { 'respuesta incorrecta' }
      $cuerpoResp = @{ preguntaId = $p.id; opciones = @(); texto = $texto } | ConvertTo-Json
    } elseif ($acertar) {
      $cuerpoResp = @{ preguntaId = $p.id; opciones = @($mapa[$p.id]); texto = $null } | ConvertTo-Json -Depth 5
    } else {
      $incorrecta = @($p.opciones | Where-Object { $_.id -notin $mapa[$p.id] } | Select-Object -First 1)
      if ($incorrecta.Count -eq 0) { $incorrecta = @($p.opciones | Select-Object -First 1) }
      $cuerpoResp = @{ preguntaId = $p.id; opciones = @($incorrecta[0].id); texto = $null } | ConvertTo-Json -Depth 5
    }
    $r = Llamar 'POST' "$base/api/intentos/$id/respuesta" $jar $csrf (Cuerpo $cuerpoResp)
    $estado = (Datos $r.cuerpo).estado
    if (-not $estado.esUltima) {
      $r = Llamar 'POST' "$base/api/intentos/$id/avanzar" $jar $csrf $null
      $estado = (Datos $r.cuerpo).estado
    }
  }
  $r = Llamar 'POST' "$base/api/intentos/$id/entregar" $jar $csrf (Cuerpo '{"confirmado":true}')
  return Datos $r.cuerpo
}

$finalBien = ResolverIntento $jarEst1 $csrf1 $true
Anota 'Estudiante 1 envia un intento perfecto (5/5)' ($finalBien.resultado.puntaje -eq 5 -and $finalBien.resultado.nota -eq 5) "nota=$($finalBien.resultado.nota)"
$finalMal = ResolverIntento $jarEst2 $csrf2 $false
Anota 'Estudiante 2 envia un intento con respuestas incorrectas (0/5)' ($finalMal.resultado.puntaje -eq 0) "puntaje=$($finalMal.resultado.puntaje)"

# --- Paginas de reportes ---------------------------------------------------
$r = Llamar 'GET' "$base/reportes" $jarDocente $null $null
Anota 'Pagina indice de reportes (200)' ($r.estado -eq '200' -and $r.cuerpo -match 'sistema solar') "status=$($r.estado)"

$r = Llamar 'GET' "$base/reportes/quices/$demoId" $jarDocente $null $null
Anota 'Pagina de reporte del quiz (200)' ($r.estado -eq '200' -and $r.cuerpo -match 'Analisis por pregunta' -and $r.cuerpo -match 'Detalle por estudiante') "status=$($r.estado)"
Anota 'El reporte lista a los dos estudiantes' ($r.cuerpo -match 'Elena Estudiante' -and $r.cuerpo -match 'Esteban Estudiante')
Anota 'El reporte muestra la tasa de aprobacion 50%' ($r.cuerpo -match '50%')

$r = Llamar 'GET' "$base/reportes" $jarEst1 $null $null
Anota 'Un estudiante no accede a reportes (redirige, 307)' ($r.estado -eq '307') "status=$($r.estado)"

# --- Exportacion CSV -------------------------------------------------------
$csvEst = Descargar "$base/api/reportes/quices/$demoId/exportar?formato=csv&tabla=estudiantes" $jarDocente (Join-Path $tmp 'qc-f6-estudiantes.csv')
Anota 'CSV de estudiantes (200, text/csv)' ($csvEst.estado -eq '200' -and $csvEst.tipo -like 'text/csv*') "status=$($csvEst.estado) tipo=$($csvEst.tipo)"
Anota 'CSV de estudiantes con encabezado correcto' ($csvEst.contenido -match 'Estudiante;Correo;Grupos')
Anota 'CSV: estudiante 1 aprobado con nota 5' ($csvEst.contenido -match 'estudiante1@colegio\.edu;Decimo A;\d+;1;5;5;Si;')
Anota 'CSV: estudiante 2 no aprobado con nota 0' ($csvEst.contenido -match 'estudiante2@colegio\.edu;Decimo A;\d+;1;0;0;No;')

$csvPre = Descargar "$base/api/reportes/quices/$demoId/exportar?formato=csv&tabla=preguntas" $jarDocente (Join-Path $tmp 'qc-f6-preguntas.csv')
Anota 'CSV de preguntas (200)' ($csvPre.estado -eq '200' -and $csvPre.contenido -match 'Enunciado;Tipo')
$lineas50 = ([regex]::Matches($csvPre.contenido, ';2;2;1;0;50;')).Count
Anota 'Cada pregunta con 2 presentadas, 2 respondidas, 1 correcta (50%)' ($lineas50 -eq 5) "lineas=$lineas50"

$csvRes = Descargar "$base/api/reportes/quices/$demoId/exportar?formato=csv&tabla=resumen" $jarDocente (Join-Path $tmp 'qc-f6-resumen.csv')
Anota 'CSV de resumen (200)' ($csvRes.estado -eq '200' -and $csvRes.contenido -match 'Reporte del quiz')

# --- Exportacion Excel -----------------------------------------------------
$xls = Descargar "$base/api/reportes/quices/$demoId/exportar?formato=excel" $jarDocente (Join-Path $tmp 'qc-f6-reporte.xls')
