58:   // Las rutas de API responden JSON; no se redirigen, cada handler autentica.
59:   if (pathname.startsWith('/api')) {
60:     return cabecerasSeguridad(NextResponse.next(), esDesarrollo);
61:   }
62: 
63:   const esPublica = RUTAS_PUBLICAS.some((ruta) => pathname === ruta || pathname.startsWith(`${ruta}/`));
64: 
65:   if (tieneSesion && pathname === '/login') {
66:     return cabecerasSeguridad(NextResponse.redirect(new URL('/panel', req.url)), esDesarrollo);
