180: const RE_PREGUNTA = /^\s*(?:(\d{1,3})\s*[.)\-:]|[-*•])\s*(.+)$/;
181: const RE_OPCION = /^\s*(?:\()?([a-hA-H]|[ivxIVX]{1,4})\s*[.)\-:]\s*(.+)$/;
182: const RE_ENUNCIADO_CON_PREGUNTA = /^\s*(?:\d{1,3}\s*[.)])?\s*[¿]?.*\?$/;
