188: function marcarCorrecta(texto: string): { texto: string; marcada: boolean } {
189:   const patrones = [/\(\s*x\s*\)/i, /\*\s*$/, /✔/, /✓/, /\[correcta\]/i, /__+/];
190:   let marcada = false;
191:   let resultado = texto;
192:   for (const patron of patrones) {
193:     if (patron.test(resultado)) {
194:       marcada = true;
195:       resultado = resultado.replace(patron, ' ');
196:     }
197:   }
198:   return { texto: limpiar(resultado), marcada };
199: }
