282:     preguntas.push({
283:       enunciado: bloque.enunciado,
284:       tipo: esVerdaderoFalso ? 'TRUE_FALSE' : conCorrecta && opciones.filter((o) => o.correcta).length > 1 ? 'MCQ_MULTI' : 'MCQ_SINGLE',
285:       opciones: opciones.map((opcion) => ({ texto: opcion.texto, correcta: opcion.correcta })),
286:       explicacion: '',
287:       tema: 'Examen importado',
288:       pagina: peticion.paginaInicio,
289:       requiereRevision: !conCorrecta,
290:     });
291:   }
292: 
293:   return { preguntas };
294: }
