426:       const respuesta = await api.post<{ quiz: QuizDetalleDto }>(
427:         `/api/quices/${quiz.id}/publicar`,
428:         { confirmoRevision: true },
429:       );
430:       aplicarRespuesta(respuesta.quiz);
431:       setConfirmoRevision(false);
432:       setMensaje({
433:         tipo: 'exito',
434:         texto: 'Quiz publicado. Ya esta disponible para los grupos asignados.',
435:       });
436:     } catch (fallo) {
437:       const detalle =
438:         fallo instanceof ErrorPeticion
439:           ? (fallo.campos as unknown as { errores?: string[]; advertencias?: string[] } | undefined)
440:           : undefined;
441:       const errores = detalle?.errores ?? [];
442:       setMensaje({
443:         tipo: 'error',
444:         texto:
445:           errores.length > 0
446:             ? `${fallo instanceof ErrorPeticion ? fallo.message : 'No se pudo publicar.'} ${errores.join(' ')}`
447:             : fallo instanceof ErrorPeticion
448:               ? fallo.message
449:               : 'No se pudo publicar el quiz.',
450:       });
451:     } finally {
452:       setPublicando(false);
453:     }
454:   }
