```ts
export const DELETE = ruta(async (req) => {
  const sesion = await requiereRolApi('ADMIN', 'TEACHER');
  verificarCsrf(req, sesion);
  const { ip } = infoCliente(req);
  const datos = await leerCuerpo(req, esquemaEliminarBanco); // { documentoId: string | null }

  // Verifica visibilidad del documento si aplica
  if (datos.documentoId) {
    const documento = await prisma.document.findUnique({ where: { id: datos.documentoId }, select: { id: true, uploadedById: true, title: true } });
    if (!documento) throw noEncontrado('Documento');
    if (sesion.usuario.role !== 'ADMIN' && documento.uploadedById !== sesion.usuario.id) throw sinPermiso();
  }

  const where = {
    ...(sesion.usuario.role === 'ADMIN' ? {} : { authorId: sesion.usuario.id }),
    documentId: datos.documentoId ?? null,
  };

  const preguntas = await prisma.question.findMany({
    where,
    select: { id: true, _count: { select: { answers: true } }, statement: true },
  });
  if (preguntas.length === 0) {
    return respuestaOk({ eliminadas: 0, archivadas: 0, total: 0 });
  }

  const conRespuestas = preguntas.filter(p => p._count.answers > 0).map(p => p.id);
  const sinRespuestas = preguntas.filter(p => p._count.answers === 0).map(p => p.id);

  await prisma.$transaction(async (tx) => {
    if (conRespuestas.length) {
      await tx.quizQuestion.deleteMany({ where: { questionId: { in: conRespuestas } } });
      await tx.question.updateMany({ where: { id: { in: conRespuestas } }, data: { status: 'DRAFT' } });
    }
    if (sinRespuestas.length) {
      await tx.quizQuestion.deleteMany({ where: { questionId: { in: sinRespuestas } } });
      await tx.questionOption.deleteMany({ where: { questionId: { in: sinRespuestas } } });
      await tx.question.deleteMany({ where: { id: { in: sinRespuestas } } });
    }
  });

  await auditar({ accion: 'BANCO_ELIMINADO', actorId, tipoEntidad: 'Document'|'Question', entidadId: datos.documentoId ?? 'GENERAL', meta: {...}, ip });

  return respuestaOk({ eliminadas: sinRespuestas.length, archivadas: conRespuestas.length, total: preguntas.length });
});
```

