        await tx.question.updateMany({
          where: { id: { in: conRespuestas } },
          data: { status: 'DRAFT' },
        });
      }
    });
  }

  await auditar({
    accion: ACCIONES.BANCO_PREGUNTAS_ELIMINADO,
