Now the UI for deleting a quiz. First create a client component `BotonEliminarQuiz.tsx` in the quices folder.

It needs: quizId, titulo, intentos (blocked flag), and optionally a redirect target. Let me make it flexible:

```tsx
'use client';

import { useRouter } from 'next/navigation';
import { useState } from 'react';
import { api, ErrorPeticion } from '@/lib/cliente/api';
import { Alerta, Boton } from '@/components/ui';

export function BotonEliminarQuiz({
  quizId,
  titulo,
  intentos,
  alEliminar,
}: {
  quizId: string;
  titulo: string;
  intentos: number;
  alEliminar?: () => void;
}) {
  const router = useRouter();
  const [eliminando, setEliminando] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const bloqueado = intentos > 0;

  async function eliminar() {
    if (
      !window.confirm(
        `¿Eliminar el quiz "${titulo}"? Esta accion no se puede deshacer.`,
      )
    ) {
      return;
    }
    setEliminando(true);
    setError(null);
    try {
      await api.del(`/api/quices/${quizId}`);
      if (alEliminar) alEliminar();
      else router.refresh();
    } catch (fallo) {
      setError(fallo instanceof ErrorPeticion ? fallo.message : 'No se pudo eliminar el quiz.');
    } finally {
      setEliminando(false);
    }
  }

  return (
    <div className="flex flex-col gap-1">
      <Boton
        variante="peligro"
        tamano="sm"
        disabled={bloqueado || eliminando}
        title={bloqueado ? 'Ya tiene intentos registrados: no se puede eliminar.' : 'Eliminar el quiz'}
        onClick={() => void eliminar()}
      >
        {eliminando ? 'Eliminando...' : 'Eliminar'}
      </Boton>
      {error && <Alerta tipo="error">{error}</Alerta>}
    </div>
  );
}
```

