const bancoActivo = useMemo(() => {
  if (documentoFijo) return { clave: documentoFijo, documentoId: documentoFijo as string | null, titulo: 'este documento' };
  if (filtroBanco === 'TODOS') return null;
  return {
    clave: filtroBanco,
    documentoId: filtroBanco === 'GENERAL' ? null : filtroBanco,
    titulo: bancos.find((b) => b.clave === filtroBanco)?.titulo ?? 'este banco',
  };
}, [documentoFijo, filtroBanco, bancos]);

const totalBancoActivo = useMemo(() => {
  if (!bancoActivo) return 0;
  return preguntas.filter((p) => (p.documento?.id ?? 'GENERAL') === bancoActivo.clave).length;
}, [bancoActivo, preguntas]);
```

Function:
```ts
async function eliminarBanco() {
  if (!bancoActivo || totalBancoActivo === 0) return;
  const nombre = documentoFijo ? 'este documento' : bancoActivo.titulo;
  if (
    !window.confirm(
      `¿Eliminar TODO el banco de ${nombre} (${totalBancoActivo} pregunta(s))? ` +
        'Se borraran definitivamente. Las preguntas ya respondidas en algun intento se conservaran archivadas.',
    )
  ) return;
  setOcupada('__banco__');
  setMensaje(null);
  try {
    const resultado = await api.del<{ total: number; eliminadas: number; archivadas: number }>(
      '/api/preguntas/banco',
      { documentoId: bancoActivo.documentoId },
    );
    setMensaje({
      tipo: resultado.archivadas > 0 ? 'aviso' : 'exito',
      texto:
        `Banco vaciado: ${resultado.eliminadas} pregunta(s) eliminada(s)` +
        (resultado.archivadas > 0 ? ` y ${resultado.archivadas} archivada(s) (ya tenian respuestas).` : '.'),
    });
    setExpandida(null);
    await recargar();
  } catch (error) {
    setMensaje({
      tipo: 'error',
      texto: error instanceof ErrorPeticion ? error.message : 'No se pudo eliminar el banco de preguntas.',
    });
  } finally {
    setOcupada(null);
  }
}
```

