24: /**
25:  * Construye un CSV con separador `;` (el que Excel abre de forma nativa en
26:  * espanol) y BOM UTF-8 para que las tildes se vean correctamente.
27:  */
28: export function construirCsv(filas: Fila[], separador = ';'): string {
29:   const lineas = filas.map((fila) =>
30:     fila
31:       .map((celda) => {
32:         const texto = aTexto(celda);
33:         if (texto.includes(separador) || texto.includes('"') || texto.includes('\n') || texto.includes('\r')) {
34:           return `"${texto.replace(/"/g, '""')}"`;
35:         }
36:         return texto;
37:       })
38:       .join(separador),
39:   );
40:   return `\uFEFF${lineas.join('\r\n')}\r\n`;
41: }
