43: function escaparXml(texto: string): string {
44:   return texto
45:     .replace(/&/g, '&amp;')
46:     .replace(/</g, '&lt;')
47:     .replace(/>/g, '&gt;')
48:     .replace(/"/g, '&quot;')
49:     .replace(/'/g, '&apos;');
50: }
51: 
52: function celdaXml(valor: string | number | null): string {
53:   if (typeof valor === 'number' && Number.isFinite(valor)) {
54:     return `<Cell><Data ss:Type="Number">${valor}</Data></Cell>`;
55:   }
56:   const texto = aTexto(valor);
57:   if (texto === '') return '<Cell/>';
58:   return `<Cell><Data ss:Type="String">${escaparXml(texto)}</Data></Cell>`;
59: }
60: 
61: function nombreHojaSeguro(nombre: string): string {
62:   return nombre.replace(/[:\\/?*[\]]/g, ' ').slice(0, 31) || 'Hoja';
63: }
