65: /**
66:  * Genera un libro Excel en formato SpreadsheetML 2003 (`.xls`), que Excel
67:  * abre sin dependencias externas y admite varias hojas.
68:  */
69: export function construirExcel(hojas: HojaExcel[]): string {
70:   const cuerpo = hojas
71:     .map((hoja) => {
72:       const filas = hoja.filas
73:         .map((fila) => `<Row>${fila.map(celdaXml).join('')}</Row>`)
74:         .join('');
75:       return `<Worksheet ss:Name="${escaparXml(nombreHojaSeguro(hoja.nombre))}"><Table>${filas}</Table></Worksheet>`;
76:     })
77:     .join('');
78: 
79:   return (
80:     '<?xml version="1.0" encoding="UTF-8"?>\n' +
81:     '<?mso-application progid="Excel.Sheet"?>\n' +
82:     '<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet"' +
83:     ' xmlns:o="urn:schemas-microsoft-com:office:office"' +
84:     ' xmlns:x="urn:schemas-microsoft-com:office:excel"' +
85:     ' xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">' +
86:     '<Styles><Style ss:ID="encabezado"><Font ss:Bold="1"/></Style></Styles>' +
87:     cuerpo +
88:     '</Workbook>'
89:   );
90: }
