/**
 * Tipos y error de la importacion de estudiantes y grupos desde un archivo
 * (plantilla de Excel / CSV).
 */

export class ErrorImportacion extends Error {
  constructor(mensaje: string) {
    super(mensaje);
    this.name = 'ErrorImportacion';
  }
}

export const COLUMNAS_IMPORTACION = [
  'tipo',
  'nombre',
  'correo',
  'contrasena',
  'grupo',
  'grado',
  'anio',
] as const;

export type ColumnaImportacion = (typeof COLUMNAS_IMPORTACION)[number];

/** Una fila leida del archivo, ya mapeada a columnas conocidas. */
export type FilaCruda = {
  /** Numero de fila dentro de la hoja (1 = encabezado). */
  fila: number;
  valores: Partial<Record<ColumnaImportacion, string>>;
};

export type EstadoFila = 'LISTO' | 'ERROR' | 'DUPLICADO';

/** Resultado de validar una fila, tal como se le muestra al administrador. */
export type ResultadoFila = {
  fila: number;
  tipo: string;
  nombre: string;
  correo: string;
  grupo: string;
  estado: EstadoFila;
  mensajes: string[];
};

/** Fila validada lista para importarse. */
export type FilaLista =
  | {
      tipo: 'ESTUDIANTE';
      fila: number;
      nombre: string;
      correo: string;
      contrasena: string;
      grupo: string | null;
      grado: string;
      anio: number;
    }
  | {
      tipo: 'GRUPO';
      fila: number;
      nombre: string;
      grado: string;
      anio: number;
    };

export type ResumenImportacion = {
  total: number;
  listas: number;
  errores: number;
  duplicadas: number;
  estudiantes: number;
  grupos: number;
};

export type Analisis = {
  filas: ResultadoFila[];
  listas: FilaLista[];
  resumen: ResumenImportacion;
};

import { construirCsv, construirExcel, type Fila } from '@/lib/reportes/exportar';

/**
 * Plantilla descargable para importar estudiantes y grupos.
 *
 * Se genera en dos formatos:
 *  - Excel (SpreadsheetML 2003, `.xls`): libro con las hojas "Datos" e
 *    "Instrucciones". Excel lo abre y lo guarda conservando el formato.
 *  - CSV (`.csv`, separador `;` y BOM UTF-8): una sola tabla "Datos".
 *
 * En ambos casos el importador acepta tambien el formato del otro, ademas de
 * XML Spreadsheet 2003 (`.xml`).
 */

const ENCABEZADO: Fila = ['tipo', 'nombre', 'correo', 'contrasena', 'grupo', 'grado', 'anio'];

/** Nombre de archivo y tipo MIME por formato. */
export const FORMATOS_PLANTILLA = {
  excel: {
    extension: 'xls',
    mime: 'application/vnd.ms-excel; charset=utf-8',
    nombre: 'plantilla-importacion-estudiantes-grupos.xls',
  },
  csv: {
    extension: 'csv',
    mime: 'text/csv; charset=utf-8',
    nombre: 'plantilla-importacion-estudiantes-grupos.csv',
  },
} as const;

export type FormatoPlantilla = keyof typeof FORMATOS_PLANTILLA;

function ejemplos(anio: number): Fila[] {
  return [
    ['ESTUDIANTE', 'Ana Gomez', 'ana.gomez@colegio.edu', 'Estudiante123!', 'Decimo A', '10', anio],
    ['ESTUDIANTE', 'Luis Perez', 'luis.perez@colegio.edu', '', 'Decimo A', '10', anio],
    ['GRUPO', 'Decimo A', '10', anio],
    ['GRUPO', 'Noveno B', '9', anio],
  ];
}

function instrucciones(): Fila[] {
  return [
    ['Como llenar la plantilla de importacion'],
    [],
    ['Escribe una fila por persona o grupo en la hoja "Datos". No cambies los encabezados.'],
    [],
    ['Columna', 'Descripcion'],
    ['tipo', 'Obligatorio. ESTUDIANTE o GRUPO.'],
    ['nombre', 'Nombre completo del estudiante, o nombre del grupo.'],
    ['correo', 'Correo electronico. Obligatorio para ESTUDIANTE.'],
    ['contrasena', 'Opcional (minimo 8 caracteres). Si se deja vacia se usa la contrasena por defecto.'],
    ['grupo', 'Solo para ESTUDIANTE: grupo al que pertenece. Si no existe, se crea.'],
    ['grado', 'Grado o nivel (para grupos o al crear uno nuevo).'],
    ['anio', 'Anio escolar del grupo. Si se deja vacio se usa el ano activo.'],
    [],
    ['Consejos'],
    ['- Los correos no pueden repetirse ni existir ya en el sistema.'],
    ['- Puedes importar solo estudiantes, solo grupos, o ambos a la vez.'],
    ['- Antes de importar, el sistema valida el archivo y te muestra los errores por fila.'],
  ];
}

/** Contenido de la plantilla Excel (libro con "Datos" e "Instrucciones"). */
export function construirPlantillaExcel(anio: number): string {
  return construirExcel([
    { nombre: 'Datos', filas: [ENCABEZADO, ...ejemplos(anio)] },
    { nombre: 'Instrucciones', filas: instrucciones() },
  ]);
}

/** Contenido de la plantilla CSV (solo la tabla "Datos"). */
export function construirPlantillaCsv(anio: number): string {
  return construirCsv([ENCABEZADO, ...ejemplos(anio)]);
}

/** Construye la plantilla en el formato indicado. */
export function construirPlantilla(formato: FormatoPlantilla, anio: number): string {
  return formato === 'csv' ? construirPlantillaCsv(anio) : construirPlantillaExcel(anio);
}

import {
  COLUMNAS_IMPORTACION,
  ErrorImportacion,
  type ColumnaImportacion,
  type FilaCruda,
} from './tipos';

/* ------------------------------------------------------------------ *
 * Lectura de la plantilla: CSV y XML Spreadsheet 2003 (.xls/.xml)
 * ------------------------------------------------------------------ */

const ALIAS_COLUMNAS: Record<string, ColumnaImportacion> = {
  tipo: 'tipo',
  clase: 'tipo',
  registro: 'tipo',
  nombre: 'nombre',
  'nombre completo': 'nombre',
  estudiante: 'nombre',
  alumno: 'nombre',
  correo: 'correo',
  email: 'correo',
  'e-mail': 'correo',
  'correo electronico': 'correo',
  contrasena: 'contrasena',
  password: 'contrasena',
  clave: 'contrasena',
  grupo: 'grupo',
  curso: 'grupo',
  grado: 'grado',
  nivel: 'grado',
  anio: 'anio',
  ano: 'anio',
  year: 'anio',
  ciclo: 'anio',
};

/** Normaliza un texto: minusculas, sin tildes, sin espacios sobrantes. */
export function normalizar(texto: string): string {
  return texto
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function decodificarXml(texto: string): string {
  return texto
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&#(\d+);/g, (_, codigo: string) => String.fromCharCode(Number(codigo)))
    .replace(/&#x([0-9a-fA-F]+);/g, (_, codigo: string) => String.fromCharCode(parseInt(codigo, 16)))
    .replace(/&amp;/g, '&');
}

/** Decodifica el archivo a texto, con respaldo para codificaciones ANSI (Windows-1252). */
function decodificarTexto(contenido: Buffer): string {
  let texto = contenido.toString('utf8');
  if (texto.includes('\uFFFD')) {
    // Los bytes no eran UTF-8 validos: es casi seguro un CSV guardado en ANSI.
    texto = contenido.toString('latin1');
  }
  return texto.replace(/^\uFEFF/, '');
}

/* ---------------------------- CSV ---------------------------- */

function detectarSeparador(primeraLinea: string): string {
  const candidatos = [';', ',', '\t'];
  let mejor = ';';
  let maximo = -1;
  for (const candidato of candidatos) {
    const cuenta = primeraLinea.split(candidato).length - 1;
    if (cuenta > maximo) {
      maximo = cuenta;
      mejor = candidato;
    }
  }
  return mejor;
}

/** Parser CSV con soporte de comillas, comillas escapadas y saltos dentro de comillas. */
export function parsearCsv(texto: string): string[][] {
  const separador = detectarSeparador(texto.split(/\r?\n/, 1)[0] ?? '');
  const filas: string[][] = [];
  let campo = '';
  let fila: string[] = [];
  let entreComillas = false;

  const cerrarFila = () => {
    fila.push(campo);
    filas.push(fila);
    fila = [];
    campo = '';
  };

  for (let i = 0; i < texto.length; i += 1) {
    const caracter = texto[i];
    if (entreComillas) {
      if (caracter === '"') {
        if (texto[i + 1] === '"') {
          campo += '"';
          i += 1;
        } else {
          entreComillas = false;
        }
      } else {
        campo += caracter;
      }
      continue;
    }
    if (caracter === '"') {
      entreComillas = true;
    } else if (caracter === separador) {
      fila.push(campo);
      campo = '';
    } else if (caracter === '\n') {
      cerrarFila();
    } else if (caracter === '\r') {
      if (texto[i + 1] !== '\n') cerrarFila();
    } else {
      campo += caracter;
    }
  }
  if (campo !== '' || fila.length > 0) cerrarFila();
  return filas;
}

/* -------------------- XML Spreadsheet 2003 -------------------- */

function parsearWorksheet(xml: string): string[][] {
  const filas: string[][] = [];
  const reFila = /<Row\b[^>]*>([\s\S]*?)<\/Row>/g;
  let coincidenciaFila: RegExpExecArray | null;

  while ((coincidenciaFila = reFila.exec(xml)) !== null) {
    const contenido = coincidenciaFila[1] ?? '';
    const celdas: string[] = [];
    let columna = 0;
    const reCelda = /<Cell\b([^>]*?)(?:\/>|>([\s\S]*?)<\/Cell>)/g;
    let coincidenciaCelda: RegExpExecArray | null;

    while ((coincidenciaCelda = reCelda.exec(contenido)) !== null) {
      const atributos = coincidenciaCelda[1] ?? '';
      const cuerpo = coincidenciaCelda[2] ?? '';

      const indice = /ss:Index="(\d+)"/.exec(atributos);
      if (indice) {
        const objetivo = Number(indice[1]) - 1;
        while (columna < objetivo) {
          celdas.push('');
          columna += 1;
        }
      }

      const dato = /<Data\b[^>]*>([\s\S]*?)<\/Data>/.exec(cuerpo);
      celdas.push(dato ? decodificarXml(dato[1] ?? '') : '');
      columna += 1;
    }

    filas.push(celdas);
  }
  return filas;
}

function filaTieneEncabezado(fila: string[]): boolean {
  const normalizadas = fila.map((celda) => ALIAS_COLUMNAS[normalizar(celda)]);
  return normalizadas.includes('tipo') && normalizadas.includes('nombre');
}

/** Elige, entre las hojas, la que contiene los encabezados esperados. */
function elegirHoja(hojas: string[][][]): string[][] {
  for (const hoja of hojas) {
    if (hoja.some((fila) => filaTieneEncabezado(fila))) return hoja;
  }
  return hojas[0] ?? [];
}

export function parsearSpreadsheetXml(texto: string): string[][] {
  const hojas: string[][][] = [];
  const reHoja = /<Worksheet\b[^>]*>([\s\S]*?)<\/Worksheet>/g;
  let coincidencia: RegExpExecArray | null;
  while ((coincidencia = reHoja.exec(texto)) !== null) {
    hojas.push(parsearWorksheet(coincidencia[1] ?? ''));
  }
  if (hojas.length === 0) {
    // Sin etiqueta Worksheet: tratar todo el documento como una hoja.
    return parsearWorksheet(texto);
  }
  return elegirHoja(hojas);
}

/* --------------------- Tabla -> filas crudas --------------------- */

function tablaAFilas(tabla: string[][]): FilaCruda[] {
  const indiceEncabezado = tabla.findIndex((fila) => filaTieneEncabezado(fila));
  if (indiceEncabezado === -1) {
    throw new ErrorImportacion(
      'No se encontraron las columnas de la plantilla. Descarga la plantilla y no cambies los encabezados.',
    );
  }

  const encabezado = tabla[indiceEncabezado] ?? [];
  const mapaColumnas = new Map<number, ColumnaImportacion>();
  encabezado.forEach((celda, indice) => {
    const columna = ALIAS_COLUMNAS[normalizar(celda)];
    if (columna && ![...mapaColumnas.values()].includes(columna)) {
      mapaColumnas.set(indice, columna);
    }
  });

  const filas: FilaCruda[] = [];
  for (let i = indiceEncabezado + 1; i < tabla.length; i += 1) {
    const celdas = tabla[i] ?? [];
    const valores: Partial<Record<ColumnaImportacion, string>> = {};
    let tieneDatos = false;
    for (const [indice, columna] of mapaColumnas) {
      const valor = (celdas[indice] ?? '').trim();
      if (valor !== '') {
        valores[columna] = valor;
        tieneDatos = true;
      }
    }
    if (tieneDatos) filas.push({ fila: i + 1, valores });
  }
  return filas;
}

/* ------------------------- API publica ------------------------- */

export function parsearHoja(nombreArchivo: string, contenido: Buffer): FilaCruda[] {
  if (contenido.length === 0) throw new ErrorImportacion('El archivo esta vacio.');

  const extension = (nombreArchivo.split('.').pop() ?? '').toLowerCase();
  const firma = contenido.subarray(0, 2).toString('latin1');

  if (extension === 'xlsx' || firma === 'PK') {
    throw new ErrorImportacion(
      'El formato .xlsx no esta soportado. En Excel usa "Guardar como" > "Hoja de calculo XML 2003" (.xls) o "CSV UTF-8", o descarga la plantilla .xls.',
    );
  }

  const texto = decodificarTexto(contenido);
  const pareceXml =
    extension === 'xml' || extension === 'xls' || /^\s*<\?xml|<Workbook[\s>]/i.test(texto);

  const tabla = pareceXml ? parsearSpreadsheetXml(texto) : parsearCsv(texto);

  if (tabla.length === 0) throw new ErrorImportacion('No se encontro ninguna fila en el archivo.');

  return tablaAFilas(tabla);
}

export { COLUMNAS_IMPORTACION };

import { prisma } from '@/lib/db';
import { hashearContrasena } from '@/lib/auth/password';
import { obtenerAjuste, obtenerAjusteNumero } from '@/lib/settings';
import { normalizar, parsearHoja } from './parsear';
import type {
  Analisis,
  FilaCruda,
  FilaLista,
  ResultadoFila,
  ResumenImportacion,
} from './tipos';

/* ------------------------------------------------------------------ *
 * Validacion e importacion de estudiantes y grupos
 * ------------------------------------------------------------------ */

const TIPOS_ESTUDIANTE = ['estudiante', 'alumno', 'student'];
const TIPOS_GRUPO = ['grupo', 'curso', 'group', 'clase'];

const CORREO_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const MIN_CONTRASENA = 8;
const MAX_CONTRASENA = 72;
const ANIO_MIN = 2000;
const ANIO_MAX = 2100;

/** Clave normalizada para comparar nombres (grupos, correos). */
export function clave(texto: string): string {
  return normalizar(texto);
}

export type ContextoValidacion = {
  anioDefecto: number;
  contrasenaPorDefecto: string;
  correosExistentes: Set<string>;
  gruposExistentes: Set<string>;
};

type FilaEstudiante = Extract<FilaLista, { tipo: 'ESTUDIANTE' }>;
type FilaGrupo = Extract<FilaLista, { tipo: 'GRUPO' }>;

function leerAnio(texto: string, porDefecto: number): { anio: number; error: string | null } {
  if (!texto) return { anio: porDefecto, error: null };
  const numero = Number(texto);
  if (!Number.isInteger(numero) || numero < ANIO_MIN || numero > ANIO_MAX) {
    return { anio: porDefecto, error: `Anio invalido: "${texto}". Usa un numero entre ${ANIO_MIN} y ${ANIO_MAX}.` };
  }
  return { anio: numero, error: null };
}

export function validarFilas(crudas: FilaCruda[], ctx: ContextoValidacion): Analisis {
  const filas: ResultadoFila[] = [];
  const listas: FilaLista[] = [];
  const correosVistos = new Set<string>();
  const gruposVistos = new Set<string>();

  for (const cruda of crudas) {
    const v = cruda.valores;
    const tipoCrudo = (v.tipo ?? '').trim();
    const nombre = (v.nombre ?? '').trim();
    const correoCrudo = (v.correo ?? '').trim();
    const contrasena = (v.contrasena ?? '').trim();
    const grupo = (v.grupo ?? '').trim();
    const grado = (v.grado ?? '').trim();
    const anioTexto = (v.anio ?? '').trim();

    const mensajes: string[] = [];
    const tipoNormalizado = clave(tipoCrudo);

    let tipo: 'ESTUDIANTE' | 'GRUPO' | null = null;
    if (tipoNormalizado) {
      if (TIPOS_ESTUDIANTE.includes(tipoNormalizado)) tipo = 'ESTUDIANTE';
      else if (TIPOS_GRUPO.includes(tipoNormalizado)) tipo = 'GRUPO';
      else mensajes.push(`Tipo desconocido: "${tipoCrudo}". Usa ESTUDIANTE o GRUPO.`);
    } else if (correoCrudo) {
      tipo = 'ESTUDIANTE';
    } else if (nombre) {
      tipo = 'GRUPO';
    }

    if (!tipo) {
      filas.push({
        fila: cruda.fila,
        tipo: tipoCrudo,
        nombre,
        correo: correoCrudo,
        grupo,
        estado: 'ERROR',
        mensajes: mensajes.length > 0 ? mensajes : ['Falta el tipo (ESTUDIANTE o GRUPO).'],
      });
      continue;
    }

    let duplicado = false;

    if (tipo === 'ESTUDIANTE') {
      const correo = correoCrudo.toLowerCase();
      if (nombre.length < 3) mensajes.push('El nombre debe tener al menos 3 caracteres.');
      if (!correo) mensajes.push('El correo es obligatorio para un estudiante.');
      else if (!CORREO_RE.test(correo)) mensajes.push(`Correo invalido: "${correoCrudo}".`);

      if (contrasena) {
        if (contrasena.length < MIN_CONTRASENA || contrasena.length > MAX_CONTRASENA) {
          mensajes.push(`La contrasena debe tener entre ${MIN_CONTRASENA} y ${MAX_CONTRASENA} caracteres.`);
        }
      } else if (ctx.contrasenaPorDefecto.length < MIN_CONTRASENA) {
        mensajes.push('No hay una contrasena por defecto valida; escribe una contrasena.');
      }

      if (correo && ctx.correosExistentes.has(correo)) {
        mensajes.push('Ya existe un usuario con ese correo.');
        duplicado = true;
      } else if (correo && correosVistos.has(correo)) {
        mensajes.push('Correo repetido en el archivo.');
        duplicado = true;
      }

      const { anio, error: errorAnio } = leerAnio(anioTexto, ctx.anioDefecto);
      if (errorAnio) mensajes.push(errorAnio);

      const estado: ResultadoFila['estado'] =
        mensajes.length > 0 ? (duplicado ? 'DUPLICADO' : 'ERROR') : 'LISTO';

      if (estado === 'LISTO') {
        correosVistos.add(correo);
        listas.push({
          tipo: 'ESTUDIANTE',
          fila: cruda.fila,
          nombre,
          correo,
          contrasena: contrasena || ctx.contrasenaPorDefecto,
          grupo: grupo || null,
          grado,
          anio,
        });
      }

      filas.push({ fila: cruda.fila, tipo: 'ESTUDIANTE', nombre, correo: correoCrudo, grupo, estado, mensajes });
      continue;
    }

    // GRUPO
    if (nombre.length < 2) mensajes.push('El nombre del grupo debe tener al menos 2 caracteres.');
    const { anio, error: errorAnio } = leerAnio(anioTexto, ctx.anioDefecto);
    if (errorAnio) mensajes.push(errorAnio);

    const claveGrupo = clave(nombre);
    if (claveGrupo && ctx.gruposExistentes.has(claveGrupo)) {
      mensajes.push('Ya existe un grupo con ese nombre.');
      duplicado = true;
    } else if (claveGrupo && gruposVistos.has(claveGrupo)) {
      mensajes.push('Grupo repetido en el archivo.');
      duplicado = true;
    }

    const estado: ResultadoFila['estado'] =
      mensajes.length > 0 ? (duplicado ? 'DUPLICADO' : 'ERROR') : 'LISTO';

    if (estado === 'LISTO') {
      gruposVistos.add(claveGrupo);
      listas.push({ tipo: 'GRUPO', fila: cruda.fila, nombre, grado, anio });
    }

    filas.push({ fila: cruda.fila, tipo: 'GRUPO', nombre, correo: '', grupo: '', estado, mensajes });
  }

  const resumen: ResumenImportacion = {
    total: filas.length,
    listas: filas.filter((fila) => fila.estado === 'LISTO').length,
    errores: filas.filter((fila) => fila.estado === 'ERROR').length,
    duplicadas: filas.filter((fila) => fila.estado === 'DUPLICADO').length,
    estudiantes: listas.filter((fila) => fila.tipo === 'ESTUDIANTE').length,
    grupos: listas.filter((fila) => fila.tipo === 'GRUPO').length,
  };

  return { filas, listas, resumen };
}

/** Lee el archivo y valida sus filas contra el estado actual de la base. */
export async function analizarArchivo(nombreArchivo: string, contenido: Buffer): Promise<Analisis> {
  const crudas = parsearHoja(nombreArchivo, contenido);

  const [anioDefecto, contrasenaPorDefecto, usuarios, grupos] = await Promise.all([
    obtenerAjusteNumero('institucion.anio', new Date().getFullYear()),
    obtenerAjuste('seguridad.contrasenaPorDefecto'),
    prisma.user.findMany({ select: { email: true } }),
    prisma.group.findMany({ select: { name: true } }),
  ]);

  return validarFilas(crudas, {
    anioDefecto,
    contrasenaPorDefecto,
    correosExistentes: new Set(usuarios.map((usuario) => usuario.email.toLowerCase())),
    gruposExistentes: new Set(grupos.map((grupo) => clave(grupo.name))),
  });
}

export type ResultadoImportacion = {
  gruposCreados: number;
  usuariosCreados: number;
  membresiasCreadas: number;
  errores: { fila: number; mensaje: string }[];
};

/**
 * Importa las filas validas. Los grupos se crean primero (para que los
 * estudiantes puedan referenciarlos) y luego los estudiantes con su membresia.
 * Todo ocurre en una sola transaccion.
 */
export async function importarAnalisis(
  analisis: Analisis,
  actorId: string,
): Promise<ResultadoImportacion> {
  const estudiantes = analisis.listas.filter(
    (fila): fila is FilaEstudiante => fila.tipo === 'ESTUDIANTE',
  );
  const grupos = analisis.listas.filter((fila): fila is FilaGrupo => fila.tipo === 'GRUPO');

  // El hash de contrasena es costoso: se calcula fuera de la transaccion.
  const hashes = new Map<number, string>();
  for (const estudiante of estudiantes) {
    hashes.set(estudiante.fila, await hashearContrasena(estudiante.contrasena));
  }

  return prisma.$transaction(async (tx) => {
    const gruposDb = await tx.group.findMany({ select: { id: true, name: true } });
    const correosDb = new Set(
      (await tx.user.findMany({ select: { email: true } })).map((usuario) => usuario.email.toLowerCase()),
    );

    const idPorNombre = new Map<string, string>();
    for (const grupo of gruposDb) idPorNombre.set(clave(grupo.name), grupo.id);

    let gruposCreados = 0;
    let usuariosCreados = 0;
    let membresiasCreadas = 0;
    const errores: { fila: number; mensaje: string }[] = [];

    const crearGrupo = async (nombre: string, grado: string, anio: number): Promise<string> => {
      const creado = await tx.group.create({
        data: { name: nombre, grade: grado || null, year: anio, createdById: actorId },
      });
      idPorNombre.set(clave(nombre), creado.id);
      gruposCreados += 1;
      return creado.id;
    };

    for (const grupo of grupos) {
      if (idPorNombre.has(clave(grupo.nombre))) continue;
      await crearGrupo(grupo.nombre, grupo.grado, grupo.anio);
    }

    for (const estudiante of estudiantes) {
      if (correosDb.has(estudiante.correo)) {
        errores.push({ fila: estudiante.fila, mensaje: `El correo ${estudiante.correo} ya existe.` });
        continue;
      }

      let grupoId: string | null = null;
      if (estudiante.grupo) {
        const llave = clave(estudiante.grupo);
        grupoId = idPorNombre.get(llave) ?? (await crearGrupo(estudiante.grupo, estudiante.grado, estudiante.anio));
      }

      const usuario = await tx.user.create({
        data: {
          name: estudiante.nombre,
          email: estudiante.correo,
          passwordHash: hashes.get(estudiante.fila) ?? '',
          role: 'STUDENT',
          active: true,
        },
      });
      correosDb.add(estudiante.correo);
      usuariosCreados += 1;

      if (grupoId) {
        await tx.groupMembership.create({ data: { userId: usuario.id, groupId: grupoId } });
        membresiasCreadas += 1;
      }
    }

    return { gruposCreados, usuariosCreados, membresiasCreadas, errores };
  });
}

