'use client';

import { useRef, useState } from 'react';
import { useRouter } from 'next/navigation';
import { ErrorPeticion, peticion } from '@/lib/cliente/api';
import { Alerta, Boton, Insignia, Tabla, Tarjeta, Vacio } from '@/components/ui';

type EstadoFila = 'LISTO' | 'ERROR' | 'DUPLICADO';
type FilaResultado = { fila: number; tipo: string; nombre: string; correo: string; grupo: string; estado: EstadoFila; mensajes: string[] };
type Resumen = { total: number; listas: number; errores: number; duplicadas: number; estudiantes: number; grupos: number };
type Analisis = { filas: FilaResultado[]; resumen: Resumen };
type ResultadoImportacion = { gruposCreados: number; usuariosCreados: number; membresiasCreadas: number; errores: { fila: number; mensaje: string }[] };

export function ImportadorDatos({ anioActual }: { anioActual: number }) {
  const router = useRouter();
  const inputRef = useRef<HTMLInputElement>(null);
  const [archivo, setArchivo] = useState<File | null>(null);
  const [analisis, setAnalisis] = useState<Analisis | null>(null);
  const [resultado, setResultado] = useState<ResultadoImportacion | null>(null);
  const [validando, setValidando] = useState(false);
  const [importando, setImportando] = useState(false);
  const [mensaje, setMensaje] = useState<{tipo:'exito'|'error'|'aviso'; texto:string}|null>(null);

  function elegirArchivo(file: File | null) {
    setArchivo(file);
    setAnalisis(null);
    setResultado(null);
    setMensaje(null);
  }

  async function subir(url: string): Promise<Analisis & { resultado?: ResultadoImportacion }> {
    if (!archivo) throw new ErrorPeticion(400, 'SIN_ARCHIVO', 'Selecciona un archivo.');
    const formulario = new FormData();
    formulario.append('archivo', archivo);
    return peticion(url, { method: 'POST', cuerpoCrudo: formulario });
  }

  async function validar() {
    setValidando(true); setMensaje(null); setResultado(null);
    try {
      const datos = await subir('/api/admin/importar/validar');
      setAnalisis({ filas: datos.filas, resumen: datos.resumen });
      if (datos.resumen.listas === 0) setMensaje({ tipo:'aviso', texto:'No hay filas validas. Revisa los errores marcados.' });
      else setMensaje({ tipo:'exito', texto:`Archivo validado: ${datos.resumen.listas} fila(s) listas para importar.` });
    } catch (error) {
      setMensaje({ tipo:'error', texto: error instanceof ErrorPeticion ? error.message : 'No se pudo validar el archivo.' });
    } finally { setValidando(false); }
  }

  async function importar() {
    setImportando(true); setMensaje(null);
    try {
      const datos = await subir('/api/admin/importar');
      setAnalisis({ filas: datos.filas, resumen: datos.resumen });
      setResultado(datos.resultado ?? null);
      const r = datos.resultado;
      setMensaje({ tipo: 'exito', texto: r ? `Importacion completada: ${r.usuariosCreados} estudiante(s) y ${r.gruposCreados} grupo(s).` : 'Importacion completada.' });
      setArchivo(null);
      if (inputRef.current) inputRef.current.value = '';
      router.refresh();
    } catch (error) {
      setMensaje({ tipo:'error', texto: error instanceof ErrorPeticion ? error.message : 'No se pudo importar.' });
    } finally { setImportando(false); }
  }
  ...
}
