206:  * estudiantes puedan referenciarlos) y luego los estudiantes con su membresia.
207:  * Todo ocurre en una sola transaccion.
208:  */
209: export async function importarAnalisis(
210:   analisis: Analisis,
211:   actorId: string,
212: ): Promise<ResultadoImportacion> {
213:   const estudiantes = analisis.listas.filter(
214:     (fila): fila is FilaEstudiante => fila.tipo === 'ESTUDIANTE',
215:   );
216:   const grupos = analisis.listas.filter((fila): fila is FilaGrupo => fila.tipo === 'GRUPO');
217: 
218:   // El hash de contrasena es costoso: se calcula fuera de la transaccion.
219:   const hashes = new Map<number, string>();
220:   for (const estudiante of estudiantes) {
221:     hashes.set(estudiante.fila, await hashearContrasena(estudiante.contrasena));
222:   }
223: 
224:   return prisma.$transaction(async (tx) => {
225:     const gruposDb = await tx.group.findMany({ select: { id: true, name: true } });
226:     const correosDb = new Set(
227:       (await tx.user.findMany({ select: { email: true } })).map((usuario) => usuario.email.toLowerCase()),
228:     );
229: 
230:     const idPorNombre = new Map<string, string>();
231:     for (const grupo of gruposDb) idPorNombre.set(clave(grupo.name), grupo.id);
232: 
233:     let gruposCreados = 0;
234:     let usuariosCreados = 0;
235:     let membresiasCreadas = 0;
236:     const errores: { fila: number; mensaje: string }[] = [];
237: 
238:     const crearGrupo = async (nombre: string, grado: string, anio: number): Promise<string> => {
239:       const creado = await tx.group.create({
240:         data: { name: nombre, grade: grado || null, year: anio, createdById: actorId },
241:       });
242:       idPorNombre.set(clave(nombre), creado.id);
243:       gruposCreados += 1;
244:       return creado.id;
245:     };
246: 
247:     for (const grupo of grupos) {
248:       if (idPorNombre.has(clave(grupo.nombre))) continue;
249:       await crearGrupo(grupo.nombre, grupo.grado, grupo.anio);
250:     }
251: 
252:     for (const estudiante of estudiantes) {
253:       if (correosDb.has(estudiante.correo)) {
254:         errores.push({ fila: estudiante.fila, mensaje: `El correo ${estudiante.correo} ya existe.` });
255:         continue;
256:       }
257: 
258:       let grupoId: string | null = null;
259:       if (estudiante.grupo) {
260:         const llave = clave(estudiante.grupo);
261:         grupoId = idPorNombre.get(llave) ?? (await crearGrupo(estudiante.grupo, estudiante.grado, estudiante.anio));
262:       }
263: 
264:       const usuario = await tx.user.create({
265:         data: {
266:           name: estudiante.nombre,
267:           email: estudiante.correo,
268:           passwordHash: hashes.get(estudiante.fila) ?? '',
269:           role: 'STUDENT',
270:           active: true,
271:         },
272:       });
273:       correosDb.add(estudiante.correo);
274:       usuariosCreados += 1;
275: 
276:       if (grupoId) {
277:         await tx.groupMembership.create({ data: { userId: usuario.id, groupId: grupoId } });
278:         membresiasCreadas += 1;
279:       }
280:     }
281: 
282:     return { gruposCreados, usuariosCreados, membresiasCreadas, errores };
283:   });
284: }

