import { normalizar } from './parsear';
import type {
  Analisis,
  FilaCruda,
  FilaLista,
  ResultadoFila,
  ResumenImportacion,
} from './tipos';

/* ------------------------------------------------------------------ *
 * Validacion (pura, sin base de datos) de las filas de la plantilla
 * ------------------------------------------------------------------ */

const TIPOS_ESTUDIANTE = ['estudiante', 'alumno', 'student'];
const TIPOS_GRUPO = ['grupo', 'curso', 'group', 'clase'];

const CORREO_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const MIN_CONTRASENA = 8;
const MAX_CONTRASENA = 72;
const ANIO_MIN = 2000;
const ANIO_MAX = 2100;

/** Clave normalizada para comparar nombres (grupos, correos). */
export function clave(texto: string): string {
  return normalizar(texto);
}

export type ContextoValidacion = {
  anioDefecto: number;
  contrasenaPorDefecto: string;
  correosExistentes: Set<string>;
  gruposExistentes: Set<string>;
};

export type FilaEstudiante = Extract<FilaLista, { tipo: 'ESTUDIANTE' }>;
export type FilaGrupo = Extract<FilaLista, { tipo: 'GRUPO' }>;

function leerAnio(texto: string, porDefecto: number): { anio: number; error: string | null } {
  if (!texto) return { anio: porDefecto, error: null };
  const numero = Number(texto);
  if (!Number.isInteger(numero) || numero < ANIO_MIN || numero > ANIO_MAX) {
    return {
      anio: porDefecto,
      error: `Anio invalido: "${texto}". Usa un numero entre ${ANIO_MIN} y ${ANIO_MAX}.`,
    };
  }
  return { anio: numero, error: null };
}

function estadoDe(mensajes: string[], duplicado: boolean): ResultadoFila['estado'] {
  if (mensajes.length === 0) return 'LISTO';
  return duplicado ? 'DUPLICADO' : 'ERROR';
}

export function validarFilas(crudas: FilaCruda[], ctx: ContextoValidacion): Analisis {
  const filas: ResultadoFila[] = [];
  const listas: FilaLista[] = [];
  const correosVistos = new Set<string>();
  const gruposVistos = new Set<string>();

  for (const cruda of crudas) {
    const v = cruda.valores;
    const tipoCrudo = (v.tipo ?? '').trim();
    const nombre = (v.nombre ?? '').trim();
    const correoCrudo = (v.correo ?? '').trim();
    const contrasena = (v.contrasena ?? '').trim();
    const grupo = (v.grupo ?? '').trim();
    const grado = (v.grado ?? '').trim();
    const anioTexto = (v.anio ?? '').trim();

    const mensajes: string[] = [];
    const tipoNormalizado = clave(tipoCrudo);

    let tipo: 'ESTUDIANTE' | 'GRUPO' | null = null;
    if (tipoNormalizado) {
      if (TIPOS_ESTUDIANTE.includes(tipoNormalizado)) tipo = 'ESTUDIANTE';
      else if (TIPOS_GRUPO.includes(tipoNormalizado)) tipo = 'GRUPO';
      else mensajes.push(`Tipo desconocido: "${tipoCrudo}". Usa ESTUDIANTE o GRUPO.`);
    } else if (correoCrudo) {
      tipo = 'ESTUDIANTE';
    } else if (nombre) {
      tipo = 'GRUPO';
    }

    if (!tipo) {
      filas.push({
        fila: cruda.fila,
        tipo: tipoCrudo,
        nombre,
        correo: correoCrudo,
        grupo,
        estado: 'ERROR',
        mensajes: mensajes.length > 0 ? mensajes : ['Falta el tipo (ESTUDIANTE o GRUPO).'],
      });
      continue;
    }

    let duplicado = false;

    if (tipo === 'ESTUDIANTE') {
      const correo = correoCrudo.toLowerCase();
      if (nombre.length < 3) mensajes.push('El nombre debe tener al menos 3 caracteres.');
      if (!correo) mensajes.push('El correo es obligatorio para un estudiante.');
      else if (!CORREO_RE.test(correo)) mensajes.push(`Correo invalido: "${correoCrudo}".`);

      if (contrasena) {
        if (contrasena.length < MIN_CONTRASENA || contrasena.length > MAX_CONTRASENA) {
          mensajes.push(
            `La contrasena debe tener entre ${MIN_CONTRASENA} y ${MAX_CONTRASENA} caracteres.`,
          );
        }
      } else if (ctx.contrasenaPorDefecto.length < MIN_CONTRASENA) {
        mensajes.push('No hay una contrasena por defecto valida; escribe una contrasena.');
      }

      if (correo && ctx.correosExistentes.has(correo)) {
        mensajes.push('Ya existe un usuario con ese correo.');
        duplicado = true;
      } else if (correo && correosVistos.has(correo)) {
        mensajes.push('Correo repetido en el archivo.');
        duplicado = true;
      }

      const { anio, error: errorAnio } = leerAnio(anioTexto, ctx.anioDefecto);
      if (errorAnio) mensajes.push(errorAnio);

      const estado = estadoDe(mensajes, duplicado);
      if (estado === 'LISTO') {
        correosVistos.add(correo);
        listas.push({
          tipo: 'ESTUDIANTE',
          fila: cruda.fila,
          nombre,
          correo,
          contrasena: contrasena || ctx.contrasenaPorDefecto,
          grupo: grupo || null,
          grado,
          anio,
        });
      }

      filas.push({ fila: cruda.fila, tipo: 'ESTUDIANTE', nombre, correo: correoCrudo, grupo, estado, mensajes });
      continue;
    }

    // GRUPO
    if (nombre.length < 2) mensajes.push('El nombre del grupo debe tener al menos 2 caracteres.');
    const { anio, error: errorAnio } = leerAnio(anioTexto, ctx.anioDefecto);
    if (errorAnio) mensajes.push(errorAnio);

    const claveGrupo = clave(nombre);
    if (claveGrupo && ctx.gruposExistentes.has(claveGrupo)) {
      mensajes.push('Ya existe un grupo con ese nombre.');
      duplicado = true;
    } else if (claveGrupo && gruposVistos.has(claveGrupo)) {
      mensajes.push('Grupo repetido en el archivo.');
      duplicado = true;
    }

    const estado = estadoDe(mensajes, duplicado);
    if (estado === 'LISTO') {
      gruposVistos.add(claveGrupo);
      listas.push({ tipo: 'GRUPO', fila: cruda.fila, nombre, grado, anio });
    }

    filas.push({ fila: cruda.fila, tipo: 'GRUPO', nombre, correo: '', grupo: '', estado, mensajes });
  }

  const resumen: ResumenImportacion = {
    total: filas.length,
    listas: filas.filter((fila) => fila.estado === 'LISTO').length,
    errores: filas.filter((fila) => fila.estado === 'ERROR').length,
    duplicadas: filas.filter((fila) => fila.estado === 'DUPLICADO').length,
    estudiantes: listas.filter((fila) => fila.tipo === 'ESTUDIANTE').length,
    grupos: listas.filter((fila) => fila.tipo === 'GRUPO').length,
  };

  return { filas, listas, resumen };
}

import { prisma } from '@/lib/db';
import { hashearContrasena } from '@/lib/auth/password';
import { obtenerAjuste, obtenerAjusteNumero } from '@/lib/settings';
import { parsearHoja } from './parsear';
import { clave, validarFilas, type FilaEstudiante, type FilaGrupo } from './validar';
import type { Analisis } from './tipos';

/* ------------------------------------------------------------------ *
 * Analisis e importacion de estudiantes y grupos (con base de datos)
 * ------------------------------------------------------------------ */

/** Lee el archivo y valida sus filas contra el estado actual de la base. */
export async function analizarArchivo(nombreArchivo: string, contenido: Buffer): Promise<Analisis> {
  const crudas = parsearHoja(nombreArchivo, contenido);

  const [anioDefecto, contrasenaPorDefecto, usuarios, grupos] = await Promise.all([
    obtenerAjusteNumero('institucion.anio', new Date().getFullYear()),
    obtenerAjuste('seguridad.contrasenaPorDefecto'),
    prisma.user.findMany({ select: { email: true } }),
    prisma.group.findMany({ select: { name: true } }),
  ]);

  return validarFilas(crudas, {
    anioDefecto,
    contrasenaPorDefecto,
    correosExistentes: new Set(usuarios.map((usuario) => usuario.email.toLowerCase())),
    gruposExistentes: new Set(grupos.map((grupo) => clave(grupo.name))),
  });
}

export type ResultadoImportacion = {
  gruposCreados: number;
  usuariosCreados: number;
  membresiasCreadas: number;
  errores: { fila: number; mensaje: string }[];
};

/**
 * Importa las filas validas. Los grupos se crean primero (para que los
 * estudiantes puedan referenciarlos) y luego los estudiantes con su membresia.
 * Todo ocurre en una sola transaccion.
 */
export async function importarAnalisis(
  analisis: Analisis,
  actorId: string,
): Promise<ResultadoImportacion> {
  const estudiantes = analisis.listas.filter(
    (fila): fila is FilaEstudiante => fila.tipo === 'ESTUDIANTE',
  );
  const grupos = analisis.listas.filter((fila): fila is FilaGrupo => fila.tipo === 'GRUPO');

  // El hash de contrasena es costoso: se calcula fuera de la transaccion.
  const hashes = new Map<number, string>();
  for (const estudiante of estudiantes) {
    hashes.set(estudiante.fila, await hashearContrasena(estudiante.contrasena));
  }

  return prisma.$transaction(async (tx) => {
    const gruposDb = await tx.group.findMany({ select: { id: true, name: true } });
    const correosDb = new Set(
      (await tx.user.findMany({ select: { email: true } })).map((usuario) =>
        usuario.email.toLowerCase(),
      ),
    );

    const idPorNombre = new Map<string, string>();
    for (const grupo of gruposDb) idPorNombre.set(clave(grupo.name), grupo.id);

    let gruposCreados = 0;
    let usuariosCreados = 0;
    let membresiasCreadas = 0;
    const errores: { fila: number; mensaje: string }[] = [];

    const crearGrupo = async (nombre: string, grado: string, anio: number): Promise<string> => {
      const creado = await tx.group.create({
        data: { name: nombre, grade: grado || null, year: anio, createdById: actorId },
      });
      idPorNombre.set(clave(nombre), creado.id);
      gruposCreados += 1;
      return creado.id;
    };

    for (const grupo of grupos) {
      if (idPorNombre.has(clave(grupo.nombre))) continue;
      await crearGrupo(grupo.nombre, grupo.grado, grupo.anio);
    }

    for (const estudiante of estudiantes) {
      if (correosDb.has(estudiante.correo)) {
        errores.push({ fila: estudiante.fila, mensaje: `El correo ${estudiante.correo} ya existe.` });
        continue;
      }

      let grupoId: string | null = null;
      if (estudiante.grupo) {
        const llave = clave(estudiante.grupo);
        grupoId =
          idPorNombre.get(llave) ?? (await crearGrupo(estudiante.grupo, estudiante.grado, estudiante.anio));
      }

      const usuario = await tx.user.create({
        data: {
          name: estudiante.nombre,
          email: estudiante.correo,
          passwordHash: hashes.get(estudiante.fila) ?? '',
          role: 'STUDENT',
          active: true,
        },
      });
      correosDb.add(estudiante.correo);
      usuariosCreados += 1;

      if (grupoId) {
        await tx.groupMembership.create({ data: { userId: usuario.id, groupId: grupoId } });
        membresiasCreadas += 1;
      }
    }

    return { gruposCreados, usuariosCreados, membresiasCreadas, errores };
  });
}

