31: export function respuestaOk<T>(datos: T, estado = 200): NextResponse {
32:   return NextResponse.json({ datos }, { status: estado });
33: }
34: 
35: function cuerpoError(estado: number, codigo: string, mensaje: string, campos?: unknown) {
36:   return NextResponse.json({ error: { codigo, mensaje, campos } }, { status: estado });
37: }
38: 
39: /** Convierte cualquier excepcion en una respuesta JSON homogenea. */
40: export function respuestaError(error: unknown): NextResponse {
41:   if (error instanceof ErrorApi) {
42:     return cuerpoError(error.estado, error.codigo, error.message, error.detalles);
43:   }
44:   if (error instanceof ZodError) {
45:     const campos: Record<string, string> = {};
46:     for (const problema of error.errors) {
47:       campos[problema.path.join('.') || '_'] = problema.message;
48:     }
49:     return cuerpoError(400, 'DATOS_INVALIDOS', 'Los datos enviados no son validos.', campos);
50:   }
51:   const mensaje = error instanceof Error ? error.message : 'Error desconocido';
52:   if (process.env.NODE_ENV !== 'production') {
53:     console.error('[API]', error);
54:   }
55:   return cuerpoError(500, 'ERROR_INTERNO', `Error interno del servidor: ${mensaje}`);
56: }
