76: /** Lee y valida el cuerpo JSON de una peticion. */
77: export async function leerCuerpo<E extends z.ZodTypeAny>(
78:   req: NextRequest,
79:   esquema: E,
80: ): Promise<z.output<E>> {
81:   let json: unknown;
82:   try {
83:     json = await req.json();
84:   } catch {
85:     throw solicitudInvalida('El cuerpo de la peticion no es JSON valido.');
86:   }
87:   return validar(esquema, json);
88: }
