90: /** Valida datos que pueden venir de query string, JSON o formulario. */
91: export function validar<E extends z.ZodTypeAny>(esquema: E, datos: unknown): z.output<E> {
92:   const resultado = esquema.safeParse(datos);
93:   if (!resultado.success) throw resultado.error;
94:   return resultado.data;
95: }
