/**
 * Lectura y volcado de todos los datos del sistema.
 *
 * El volcado es la base comun del respaldo (SQL o JSON), de la restauracion y
 * de la migracion entre motores: siempre se lee con el cliente de Prisma (que
 * conoce los tipos) y luego se escribe con el dialecto del motor destino.
 *
 * Modulo SOLO de servidor.
 */

import { prisma } from '@/lib/db';
import { TABLAS, type DefinicionTabla, type ModeloPrisma } from './catalogo';
import { sentenciaInsert } from './sql';
import { motorActivo, type MotorBd } from './motores';

/** Maximo de filas por tabla que se volcaran en memoria. */
const LIMITE_FILAS = 500_000;

export type ContenidoTabla = {
  tabla: string;
  columnas: string[];
  filas: unknown[][];
};

export type Volcado = {
  version: 1;
  generadoEn: string;
  motor: MotorBd;
  tablas: ContenidoTabla[];
  totalFilas: number;
};

type DelegadoPrisma = {
  findMany: (args?: unknown) => Promise<Array<Record<string, unknown>>>;
};

function delegado(modelo: ModeloPrisma): DelegadoPrisma {
  const cliente = prisma as unknown as Record<ModeloPrisma, DelegadoPrisma>;
  const encontrado = cliente[modelo];
  if (!encontrado) throw new Error(`Modelo de Prisma desconocido: ${modelo}`);
  return encontrado;
}

/** Lee todas las tablas del sistema. */
export async function leerTodo(motor: MotorBd | null = motorActivo()): Promise<Volcado> {
  const tablas: ContenidoTabla[] = [];
  let totalFilas = 0;

  for (const definicion of TABLAS) {
    const registros = await delegado(definicion.modelo).findMany();
    if (registros.length > LIMITE_FILAS) {
      throw new Error(
        `La tabla ${definicion.tabla} tiene demasiadas filas para volcarla (${registros.length}).`,
      );
    }
    const filas = registros.map((registro) =>
      definicion.columnas.map((columna) => valorPlano(registro[columna.nombre])),
    );
    totalFilas += filas.length;
    tablas.push({
      tabla: definicion.tabla,
      columnas: definicion.columnas.map((columna) => columna.nombre),
      filas,
    });
  }

  return {
    version: 1,
    generadoEn: new Date().toISOString(),
    motor: motor ?? 'sqlite',
    tablas,
    totalFilas,
  };
}

/** Deja solo valores serializables con `JSON.stringify`. */
function valorPlano(valor: unknown): unknown {
  if (valor === null || valor === undefined) return null;
  if (valor instanceof Date) return valor.toISOString();
  if (typeof valor === 'bigint') return Number(valor);
  return valor;
}

/** Convierte el valor del JSON al tipo que espera la columna. */
function coercionar(tipo: string, valor: unknown): unknown {
  if (valor === null || valor === undefined) return null;
  if (tipo === 'fecha') return valor instanceof Date ? valor : new Date(String(valor));
  if (tipo === 'booleano') {
    if (typeof valor === 'boolean') return valor;
    return valor === 1 || valor === '1' || valor === 'true' || valor === true;
  }
  if (tipo === 'entero') return typeof valor === 'number' ? Math.trunc(valor) : Number(valor);
  if (tipo === 'real') return typeof valor === 'number' ? valor : Number(valor);
  return typeof valor === 'string' ? valor : String(valor);
}

/** Serializa el volcado a JSON (fechas en ISO 8601). */
export function volcadoAJson(volcado: Volcado): string {
  return JSON.stringify(volcado, null, 2);
}

export type DatosVolcadoJson = {
  version: number;
  generadoEn: string;
  motor: string;
  tablas: { tabla: string; columnas: string[]; filas: unknown[][] }[];
};

/** Valida y convierte el JSON de un respaldo en un volcado utilizable. */
export function volcadoDesdeJson(datos: DatosVolcadoJson): Volcado {
  const porNombre = new Map(TABLAS.map((definicion) => [definicion.tabla, definicion]));
  const tablas: ContenidoTabla[] = [];
  let totalFilas = 0;

  for (const definicion of TABLAS) {
    const entrada = datos.tablas.find((t) => t.tabla === definicion.tabla);
    if (!entrada) {
      tablas.push({ tabla: definicion.tabla, columnas: definicion.columnas.map((c) => c.nombre), filas: [] });
      continue;
    }
    const tipos = new Map(definicion.columnas.map((columna) => [columna.nombre, columna.tipo]));
    const filas = entrada.filas.map((fila) =>
      definicion.columnas.map((columna, indice) => {
        const tipo = tipos.get(columna.nombre) ?? 'texto';
        return coercionar(tipo, fila[indice]);
      }),
    );
    totalFilas += filas.length;
    tablas.push({
      tabla: definicion.tabla,
      columnas: definicion.columnas.map((columna) => columna.nombre),
      filas,
    });
  }

  // Se ignoran tablas desconocidas para no romper con respaldos de otra version.
  const desconocidas = datos.tablas.filter((t) => !porNombre.has(t.tabla)).map((t) => t.tabla);

  return {
    version: 1,
    generadoEn: datos.generadoEn,
    motor: (['sqlite', 'postgresql', 'mysql'] as const).includes(datos.motor as MotorBd)
      ? (datos.motor as MotorBd)
      : 'sqlite',
    tablas,
    totalFilas: totalFilas + desconocidas.length * 0,
  };
}

/** Sentencias `INSERT` de todo el volcado, en lotes. */
export function sentenciasInsert(
  volcado: Volcado,
  motor: MotorBd,
  tamanoLote = 250,
): string[] {
  const definiciones = new Map(TABLAS.map((definicion) => [definicion.tabla, definicion]));
  const sentencias: string[] = [];

  for (const contenido of volcado.tablas) {
    const definicion = definiciones.get(contenido.tabla);
    if (!definicion || contenido.filas.length === 0) continue;
    for (let i = 0; i < contenido.filas.length; i += tamanoLote) {
      sentencias.push(sentenciaInsert(definicion, contenido.filas.slice(i, i + tamanoLote), motor));
    }
  }

  return sentencias;
}

/** Resumen de filas por tabla. */
export function resumenVolcado(volcado: Volcado): { tabla: string; etiqueta: string; filas: number }[] {
  const etiquetas = new Map(TABLAS.map((definicion) => [definicion.tabla, definicion.etiqueta]));
  return volcado.tablas.map((contenido) => ({
    tabla: contenido.tabla,
    etiqueta: etiquetas.get(contenido.tabla) ?? contenido.tabla,
    filas: contenido.filas.length,
  }));
}

export function definicionDeTabla(tabla: string): DefinicionTabla | undefined {
  return TABLAS.find((definicion) => definicion.tabla === tabla);
}

