import { NextResponse } from 'next/server';
import { ruta, infoCliente } from '@/lib/http';
import { requiereRolApi } from '@/lib/auth/guard';
import { auditar, ACCIONES } from '@/lib/audit';
import { convertirError, crearRespaldo, type FormatoRespaldo } from '@/lib/basedatos/servicio';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 120;

/**
 * GET /api/admin/base-datos/respaldo?formato=sql|json
 * Descarga un respaldo completo de la base de datos activa
 * (funciona con SQLite, PostgreSQL y MySQL).
 */
export const GET = ruta(async (req) => {
  const sesion = await requiereRolApi('ADMIN');
  const { ip } = infoCliente(req);
  const parametro = new URL(req.url).searchParams.get('formato');
  const formato: FormatoRespaldo = parametro === 'json' ? 'json' : 'sql';

  let respaldo;
  try {
    respaldo = await crearRespaldo(formato);
  } catch (error) {
    throw convertirError(error);
  }

  await auditar({
    accion: ACCIONES.RESPALDO_GENERADO,
    actorId: sesion.usuario.id,
    tipoEntidad: 'BaseDatos',
    meta: { formato, archivo: respaldo.nombre },
    ip,
  });

  return new NextResponse(respaldo.contenido, {
    headers: {
      'Content-Type': respaldo.mime,
      'Content-Disposition': `attachment; filename="${respaldo.nombre}"`,
      'Cache-Control': 'no-store',
    },
  });
});

import { ruta, respuestaOk, solicitudInvalida, validar, infoCliente } from '@/lib/http';
import { requiereRolApi, verificarCsrf } from '@/lib/auth/guard';
import { auditar, ACCIONES } from '@/lib/audit';
import { leerArchivoMultipart } from '@/lib/archivos';
import { esquemaRespaldo } from '@/lib/esquemas/base-datos';
import { convertirError, restaurarRespaldo } from '@/lib/basedatos/servicio';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 120;

const MAX_BYTES = 64 * 1024 * 1024;

/**
 * POST /api/admin/base-datos/restaurar
 * Reemplaza los datos actuales con los de un respaldo JSON.
 * Antes de sobrescribir guarda una copia de seguridad en disco.
 */
export const POST = ruta(async (req) => {
  const sesion = await requiereRolApi('ADMIN');
  verificarCsrf(req, sesion);
  const { ip } = infoCliente(req);

  const { nombre, contenido } = await leerArchivoMultipart(req, {
    maxBytes: MAX_BYTES,
    mensajeFaltante: 'Adjunta un respaldo en formato JSON.',
    nombrePorDefecto: 'respaldo.json',
  });

  let json: unknown;
  try {
    json = JSON.parse(contenido.toString('utf8').replace(/^\uFEFF/, ''));
  } catch {
    throw solicitudInvalida('El archivo no es un respaldo JSON valido.');
  }

  const datos = validar(esquemaRespaldo, json);

  let informe;
  try {
    informe = await restaurarRespaldo(datos);
  } catch (error) {
    throw convertirError(error);
  }

  await auditar({
    accion: ACCIONES.RESPALDO_RESTAURADO,
    actorId: sesion.usuario.id,
    tipoEntidad: 'BaseDatos',
    meta: {
      archivo: nombre,
      totalFilas: informe.totalFilas,
      respaldoPrevio: informe.respaldoPrevio,
    },
    ip,
  });

  return respuestaOk({ informe });
});

import { ruta, respuestaOk, leerCuerpo } from '@/lib/http';
import { requiereRolApi, verificarCsrf } from '@/lib/auth/guard';
import { esquemaProbarConexion } from '@/lib/esquemas/base-datos';
import { convertirError, probarConexion } from '@/lib/basedatos/servicio';
import type { ConfiguracionConexion } from '@/lib/basedatos/conexion';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 60;

/**
 * POST /api/admin/base-datos/probar
 * Comprueba que la base de datos destino existe y acepta conexiones.
 * No crea ni modifica nada.
 */
export const POST = ruta(async (req) => {
  const sesion = await requiereRolApi('ADMIN');
  verificarCsrf(req, sesion);

  const { conexion } = await leerCuerpo(req, esquemaProbarConexion);

  try {
    const resultado = await probarConexion(conexion as ConfiguracionConexion);
    return respuestaOk({ resultado });
  } catch (error) {
    throw convertirError(error);
  }
});

import { ruta, respuestaOk, leerCuerpo, infoCliente } from '@/lib/http';
import { requiereRolApi, verificarCsrf } from '@/lib/auth/guard';
import { auditar, ACCIONES } from '@/lib/audit';
import { esquemaMigracion } from '@/lib/esquemas/base-datos';
import { convertirError, migrarBaseDatos } from '@/lib/basedatos/servicio';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 300;

/**
 * POST /api/admin/base-datos/migrar
 * Crea el esquema en la base destino y copia todos los datos.
 * Si `cambiarConfiguracion` es true, tambien deja .env y el esquema de Prisma
 * apuntando al nuevo motor (el cambio se aplica al reiniciar el servidor).
 */
export const POST = ruta(async (req) => {
  const sesion = await requiereRolApi('ADMIN');
  verificarCsrf(req, sesion);
  const { ip } = infoCliente(req);

  const { conexion, cambiarConfiguracion } = await leerCuerpo(req, esquemaMigracion);

  let informe;
  try {
