                  <Entrada
                    id="migrar-usuario"
                    value={conexion.usuario}
                    onChange={(evento) => actualizarCampo('usuario', evento.target.value)}
                    autoComplete="off"
                  />
                </Campo>
                <Campo etiqueta="Contrasena" htmlFor="migrar-contrasena">
                  <Entrada
