/**
 * Prepara la base de datos antes de arrancar la aplicacion.
 *
 * Prisma exige que el `provider` de `prisma/schema.prisma` sea un literal, asi
 * que este script:
 *
 *   1. Deduce el motor a partir de `DATABASE_URL`.
 *   2. Si el esquema declara otro motor, lo actualiza.
 *   3. Si el cliente de Prisma se genero para otro motor, lo vuelve a generar.
 *
 * Se ejecuta automaticamente antes de `npm run dev`, `npm run build` y
 * `npm run seed` (ganchos predev/prebuild/preseed) y tambien a mano con
 * `npm run db:preparar`.
 */
import 'dotenv/config';
import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { etiquetaMotor, motorDeUrl } from '../src/lib/basedatos/motores';

const RAIZ = process.cwd();
const RUTA_ESQUEMA = path.join(RAIZ, 'prisma', 'schema.prisma');
const RUTA_CLI = path.join(RAIZ, 'node_modules', 'prisma', 'build', 'index.js');
/** Marca con el motor para el que se genero el cliente de Prisma. */
const RUTA_MARCA = path.join(RAIZ, 'node_modules', '.prisma', 'motor.txt');

