/**
 * Reglas de la "inicializacion sin datos de prueba".
 *
 * Deja la base de datos como recien instalada: se vacian los datos de trabajo
 * (usuarios, grupos, documentos, preguntas, quices e intentos) y se conservan
 * el esquema, la configuracion del sistema, el registro de auditoria y la
 * cuenta del administrador que ejecuta la accion.
 *
 * Modulo PURO (sin acceso a la base de datos) para poder probarlo con Vitest.
 */

import { TABLAS_INVERSO, type DefinicionTabla, type ModeloPrisma } from './catalogo';

/**
 * Tablas que NO se vacian:
 *  - `Setting`   guarda la configuracion del sistema (nombre, ano escolar...).
 *  - `AuditLog`  es el rastro de auditoria; no debe borrarse nunca.
 */
export const TABLAS_CONSERVADAS: readonly string[] = ['Setting', 'AuditLog'];

export function esTablaConservada(tabla: string): boolean {
  return TABLAS_CONSERVADAS.includes(tabla);
}

/** Tablas que se vacian, en orden seguro (primero las que dependen de otras). */
export function tablasQueSeVacian(): DefinicionTabla[] {
  return TABLAS_INVERSO.filter((definicion) => !esTablaConservada(definicion.tabla));
}

/**
 * Filtro de borrado de un modelo, o `null` si hay que vaciar la tabla entera.
 * Se conservan la cuenta que ejecuta la accion y sus sesiones abiertas, para
 * que quien pulsa el boton no se quede fuera del sistema.
 */
export function filtroVaciar(
  modelo: ModeloPrisma,
  usuarioId: string,
): { where: Record<string, unknown> } | null {
  if (modelo === 'user') return { where: { id: { not: usuarioId } } };
  if (modelo === 'session') return { where: { userId: { not: usuarioId } } };
  return null;
}

import { randomBytes } from 'node:crypto';

/** Cuenta de administrador que crea `npm run db:inicializar`. */
export const CORREO_ADMIN_POR_DEFECTO = 'admin@colegio.edu';
export const NOMBRE_ADMIN_POR_DEFECTO = 'Administrador';
/** Misma regla que la validacion de usuarios del sistema. */
export const LARGO_MINIMO_CONTRASENA = 8;

export type AdministradorInicial = {
  correo: string;
  nombre: string;
  contrasena: string;
  /** `true` cuando la contrasena se genero (no vino de `ADMIN_PASSWORD`). */
  generada: boolean;
  /** Aviso cuando `ADMIN_PASSWORD` se ignora por no cumplir el minimo. */
  aviso: string | null;
};

/**
 * Contrasena aleatoria en base64url (letras, digitos, "-" y "_"): se puede
 * copiar y pegar sin escapes y cumple el minimo de 8 caracteres.
 */
export function generarContrasena(longitud = 16): string {
  const bytes = Math.max(12, Math.ceil((longitud * 3) / 4));
  return randomBytes(bytes).toString('base64url').slice(0, Math.max(longitud, LARGO_MINIMO_CONTRASENA));
}

/**
 * Decide el administrador que creara `npm run db:inicializar`.
 *
 * Usa `ADMIN_EMAIL` y `ADMIN_PASSWORD` si estan definidos en el entorno.
 * Si falta la contrasena (o es demasiado corta) genera una aleatoria.
 */
export function resolverAdministradorInicial(
  entorno: Record<string, string | undefined> = process.env,
): AdministradorInicial {
  const correo = (entorno.ADMIN_EMAIL ?? '').trim() || CORREO_ADMIN_POR_DEFECTO;
  const nombre = (entorno.ADMIN_NAME ?? '').trim() || NOMBRE_ADMIN_POR_DEFECTO;
  const definida = (entorno.ADMIN_PASSWORD ?? '').trim();

  if (definida.length >= LARGO_MINIMO_CONTRASENA) {
    return { correo, nombre, contrasena: definida, generada: false, aviso: null };
  }

  return {
    correo,
    nombre,
    contrasena: generarContrasena(),
    generada: true,
    aviso: definida
      ? `ADMIN_PASSWORD debe tener al menos ${LARGO_MINIMO_CONTRASENA} caracteres; se genero una contrasena nueva.`
      : null,
  };
}

